    private object HandleQiBuy(HttpListenerContext ctx)
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var p = ReadJson(ctx);
        var itemId = GetParam<string>(p, "id");
        var count = GetParamOr(p, "count", 1);

        if (string.IsNullOrEmpty(itemId))
            return new { ok = false, error = "Missing item id" };

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;

                // 查价格
                int unitPrice = 0;
                try
                {
                    var shopData = Game1.content.Load<Dictionary<string, string>>("Data/Shops");
                    if (shopData.TryGetValue("QiGemShop", out var raw))
                    {
                        foreach (var part in raw.Split('/'))
                        {
                            var fields = part.Split(' ');
                            if (fields.Length >= 2 && fields[0] == itemId)
                                unitPrice = int.TryParse(fields[1], out var pp) ? pp : 0;
                        }
                    }
                }
                catch { }

                // 如果从数据没读到，用兜底价格
                if (unitPrice == 0)
                {
                    var fallbackPrices = new Dictionary<string, int>
                    {
                        ["(O)69"] = 5, ["(O)70"] = 5, ["(O)71"] = 5, ["(O)350"] = 5,
                        ["(O)645"] = 10, ["(O)337"] = 5, ["(O)279"] = 20, ["(O)835"] = 20,
                        ["(O)446"] = 20, ["(O)237"] = 10, ["(O)346"] = 50, ["(O)303"] = 25,
                        ["(O)73"] = 50, ["(O)60"] = 40, ["(O)62"] = 40, ["(O)64"] = 20,
                        ["(O)66"] = 20, ["(O)68"] = 20, ["(O)74"] = 80, ["(O)110"] = 100,
                        ["(O)803"] = 100, ["(O)804"] = 100, ["(O)805"] = 100, ["(O)168"] = 50,
                        ["(O)688"] = 10, ["(O)128"] = 10, ["(O)44"] = 5, ["(O)635"] = 30,
                        ["(O)610"] = 1, ["(O)458"] = 30, ["(O)459"] = 5,
                        ["(O)898"] = 20, ["(O)899"] = 20, ["(O)900"] = 20, ["(O)901"] = 20,
                        ["(O)872"] = 20,
                    };
                    fallbackPrices.TryGetValue(itemId, out unitPrice);
                }
                if (unitPrice == 0)
                    unitPrice = 10; // 兜底

                int totalCost = unitPrice * count;
                if (farmer.QiGems < totalCost)
                {
                    tcs.SetResult(new { ok = false, error = $"Need {totalCost} Qi Gems, have {farmer.QiGems}" });
                    return;
                }

                farmer.QiGems -= totalCost;
                var item = ItemRegistry.Create(itemId, count);
                farmer.addItemByMenuIfNecessary(item);

                tcs.SetResult(new { ok = true, given = item.DisplayName, count,
                    cost = totalCost, currency = "QiGem",
                    remainingQiGems = farmer.QiGems });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleClearGround(HttpListenerContext ctx)
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var qs = ctx.Request.QueryString;
        int tx = int.Parse(qs["x"] ?? "0");
        int ty = int.Parse(qs["y"] ?? "0");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var toRemove = new List<Debris>();
                foreach (var d in loc.debris)
                    if (d != null && d.Chunks.Count > 0
                        && (int)(d.Chunks[0].position.X / 64f) == tx
                        && (int)(d.Chunks[0].position.Y / 64f) == ty)
                        toRemove.Add(d);
                foreach (var d in toRemove)
                    loc.debris.Remove(d);
                var tileVec = new Vector2(tx, ty);
                if (loc.objects.ContainsKey(tileVec))
                    loc.objects.Remove(tileVec);
                // Also remove terrain features (trees, weeds, stones, etc.)
                if (loc.terrainFeatures.ContainsKey(tileVec))
                    loc.terrainFeatures.Remove(tileVec);
                // Remove large terrain features (like giant stumps) from resource clusters
                if (loc.largeTerrainFeatures?.Count > 0)
                {
                    var toRemoveLarge = loc.largeTerrainFeatures
                        .Where(ltf => ltf != null && (int)ltf.Tile.X == tx && (int)ltf.Tile.Y == ty).ToList();
                    foreach (var ltf in toRemoveLarge)
                        loc.largeTerrainFeatures.Remove(ltf);
                }
                tcs.SetResult(new { ok = true, cleared = new { x = tx, y = ty } });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleDebris()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var debrisList = new List<object>();
                foreach (var d in loc.debris)
                {
                    if (d != null && d.Chunks.Count > 0)
                    {
                        string name = "?";
                        int stack = 1;
                        try
                        {
                            if (d.item != null)
                            {
                                name = d.item.Name ?? "";
                                stack = d.item.Stack;
                            }
                            else if (!string.IsNullOrEmpty(d.itemId?.Value))
                            {
                                // SDV 1.6: d.item 常为 null（炸矿/敲碎的 debris），用 itemId 兜底取名字
                                var dropItem = ItemRegistry.Create(d.itemId.Value, 1);
                                name = dropItem?.DisplayName ?? dropItem?.Name ?? d.itemId.Value;
                            }
                        }
                        catch { }
                        // 🎁 丢弃者标记（2026-09-11 反编译实锤）：只有**玩家手动丢**才非 0——
                        //    全量反编译里只有两处赋值，都在 `Game1.player` 上：
                        //      InventoryPage.receiveLeftClick  拖出背包格子外松手（256191）
                        //      Toolbar.receiveRightClick        Shift/Ctrl + 右键点快捷栏格（283154，不开背包）
                        //    砍树/挖矿/钓鱼/机器产出的 debris 恒为 0 ⇒ 这是"谁丢给你的"唯一权威来源。
                        //    NetLong 字段、随 NetFields 同步 ⇒ 对端进程理论上也读得到（本次探测就是在验这条）。
                        long dropId = 0;
                        try { dropId = d.DroppedByPlayerID.Value; } catch { }
                        debrisList.Add(new
                        {
                            x = (int)(d.Chunks[0].position.X / 64f),
                            y = (int)(d.Chunks[0].position.Y / 64f),
                            itemName = name,
                            stack = stack,
                            droppedBy = dropId,
                            droppedByName = DropNameOf(dropId)
                        });
                    }
                }
                tcs.SetResult(new { ok = true, location = loc.Name, debris = debrisList });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// 🎁 UniqueMultiplayerID → 玩家名（丢弃标记解码用）。0/查不到 → ""；查得到 ID 但对不上人 → "#id"。
    /// </summary>
    internal static string DropNameOf(long id)
    {
        if (id == 0) return "";
        try
        {
            foreach (var f in Game1.getAllFarmers())
                if (f != null && f.UniqueMultiplayerID == id) return f.Name;
        }
        catch { }
        return $"#{id}";
    }

    /// <summary>
    /// POST /drop_item  { item: "名字或ID", count?: N(默认整叠) }
    /// 🤲 "递给"的底座（2026-09-11）：把背包物品像**玩家手动丢**那样扔在脚下。
    ///   命门是补上 `DroppedByPlayerID = 自己的 UniqueMultiplayerID` —— 与游戏那两处手动丢
    ///   （`InventoryPage.receiveLeftClick` 拖出背包外 / `Toolbar.receiveRightClick` Shift+右键）**逐字一致**。
    ///   对方磁吸捡走时，他那边的 `DebrisCollectPatch` 才认得出"这是轮回丢给我的"，播 🎁。
    ///   ⚠️ 光调 `createItemDebris` 不给标记 = 在对方眼里和砍树掉的无主 debris 没区别，彩蛋不会响。
    /// </summary>
    private object HandleDropItem(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var itemName = GetParam<string>(p, "item");
        int wantCount = GetParamOr(p, "count", 0);          // 0 = 整叠

        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                // 找背包物品（英文内部名 → 中文显示名 → QualifiedItemId，同 HandleGift）
                int idx = -1;
                Item? item = null;
                for (int i = 0; i < farmer.Items.Count; i++)
                {
                    var it = farmer.Items[i];
                    if (it == null) continue;
                    if (it.Name.Equals(itemName, StringComparison.OrdinalIgnoreCase)
                        || (it.DisplayName ?? "").Equals(itemName, StringComparison.OrdinalIgnoreCase)
                        || (it.QualifiedItemId ?? "").Equals(itemName, StringComparison.OrdinalIgnoreCase))
                    { idx = i; item = it; break; }
                }
                if (item == null)
                {
                    tcs.SetResult(new { ok = false, error = $"背包里没有 {itemName}" });
                    return;
                }

                // ⚠️ 游戏自己的规矩，必须补（恒 2026-09-11 提醒"工具是禁止扔出背包的"）：
                //   `/drop_item` **绕过了 UI**，不自己拦就会让 AI 把斧头镐子丢地上。
                //   `canBeDropped()` 拦工具（`StardewValley.Tool` 覆写成 false，正是 Toolbar 那条路的判据）；
                //   `canBeTrashed()` 再拦任务物品/镰刀（InventoryPage 那条路的判据）。两道取交集最保守。
                if (!item.canBeDropped() || !item.canBeTrashed())
                {
                    tcs.SetResult(new { ok = false, error = $"{SafeDisplayName(item)} 不能丢出背包（工具/任务物品/镰刀——游戏本身就拦）" });
                    return;
                }

                int dropCount = (wantCount <= 0 || wantCount > item.Stack) ? item.Stack : wantCount;
                Item thrown;
                if (dropCount >= item.Stack)
                {
                    thrown = item;                          // 整叠：直接挪出去（同游戏 takeHeldItem 的做法）
                    farmer.Items[idx] = null;
                }
                else
                {
                    thrown = item.getOne();
                    thrown.Stack = dropCount;
                    item.Stack -= dropCount;
                }

                // ⚠️ 名字要在 createItemDebris **之前**读：Debris 构造器会对同一实例调 item.resetState()
                string display = SafeDisplayName(thrown);
                string internalName = thrown.Name ?? "";

                var debris = Game1.createItemDebris(thrown, farmer.getStandingPosition(), farmer.FacingDirection);
                if (debris == null)
                {
                    tcs.SetResult(new { ok = false, error = "createItemDebris 没返回 debris（物品已取出背包，注意别丢）" });
                    return;
                }
                debris.DroppedByPlayerID.Value = farmer.UniqueMultiplayerID;   // 👈 全彩蛋的命门

                tcs.SetResult(new
                {
                    ok = true,
                    item = display,
                    name = internalName,
                    count = dropCount,
                    x = farmer.TilePoint.X,
                    y = farmer.TilePoint.Y,
                    droppedBy = farmer.Name
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// POST /toggle_doors  { building?: "Deluxe Barn", doorX?: 37, doorY?: 13 }
    /// **翻转**动物建筑的门（⚠️ **忽略 `action`**——只有"翻一下"这一种动作，方向是**调用方的意图**；
    /// 门态的**只读口**在 `GET /farm_buildings` 的 `animalDoorOpen`）。
    ///
    /// 🧭 2026-10-03 加「够得着」闸（恒点头，口径见 `ReachTiles` 那段总注释）：只翻**玩家人在农场、
    ///    且门格 ≤ `ReachTiles` 格**的建筑；够不着的进 `skipped`（带门坐标 + `reason`）。
    ///
    /// ⚠️ 为什么必须能**点名单栋**翻：闸门是按"玩家周围 N 格"选的 ⇒ 若你站在 B 栋门口
    ///    再叫一次"全翻"，刚翻好的 A 栋只要也在 N 格内就**会被翻回去**（来回翻，永远收敛不了）。
    ///    `building` 用**子串**匹配（`"Barn"` 能中 Deluxe Barn）；⚠️ **同名两栋**（两个 Deluxe Coop）
    ///    靠名字分不开 ⇒ 精确点名用 `doorX`/`doorY`（`/farm_buildings` 的 `animalDoorX/Y`，按坐标只翻那一栋）。
    /// </summary>
    private object HandleToggleDoors(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var wantBuilding = GetParamOr(p, "building", "");
        var wantDoorX = GetParamOr(p, "doorX", -1);
        var wantDoorY = GetParamOr(p, "doorY", -1);
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farm = Game1.getFarm();
                var farmer = Game1.player;
                var fTile = farmer?.TilePoint ?? Point.Zero;
                bool onFarm = farm != null && ReferenceEquals(farmer?.currentLocation, farm);
                int toggled = 0;
                var details = new List<object>();
                var skipped = new List<object>();

                foreach (var building in farm.buildings)
                {
                    if (building == null) continue;
                    var bType = building.buildingType?.Value ?? "";
                    bool isAnimalBuilding = bType.Contains("Coop") || bType.Contains("Barn");
                    if (!isAnimalBuilding) continue;
                    // 点名那一栋（子串、大小写不敏感）；不点名＝翻所有**够得着**的
                    if (wantBuilding.Length > 0
                        && !bType.Contains(wantBuilding, StringComparison.OrdinalIgnoreCase)) continue;

                    // 🧭 闸：人不在农场 / 读不到门坐标 / 门太远 ⇒ 不翻，点名报出去（**不静默跳过**）
                    bool hasDoor = TryGetAnimalDoorTile(building, out int dx, out int dy);
                    // 精确点名那一栋的门（同名两栋靠名字分不开，必须按坐标）
                    if (wantDoorX >= 0 && wantDoorY >= 0 && (!hasDoor || dx != wantDoorX || dy != wantDoorY))
                        continue;
                    if (!onFarm || !hasDoor || !IsWithinReach(farmer, farm, new Vector2(dx, dy)))
                    {
                        skipped.Add(new
                        {
                            building = bType,
                            doorX = hasDoor ? dx : -1,
                            doorY = hasDoor ? dy : -1,
                            reason = !onFarm ? "not_on_farm" : (!hasDoor ? "no_door_coords" : "too_far"),
                            distance = hasDoor
                                ? Math.Max(Math.Abs(fTile.X - dx), Math.Abs(fTile.Y - dy))
                                : (int?)null
                        });
                        continue;
                    }

                    try
                    {
                        // Try to toggle animal door via reflection on actual runtime type
                        var bType_runtime = building.GetType();
                        var doorField = bType_runtime.GetField("animalDoorOpen",
                            BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                        if (doorField != null && doorField.GetValue(building) is Netcode.NetBool netBool)
                        {
                            netBool.Value = !netBool.Value;
                            toggled++;
                            details.Add(new { building = bType, door_open = netBool.Value, doorX = dx, doorY = dy });
                        }
                        else
                        {
                            // Try method instead
                            var method = bType_runtime.GetMethod("ToggleAnimalDoor",
                                BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                            if (method != null)
                            {
                                method.Invoke(building, null);
                                toggled++;
                                details.Add(new { building = bType, toggled_via = "ToggleAnimalDoor", doorX = dx, doorY = dy });
                            }
                            else
                            {
                                details.Add(new { building = bType, error = "no door field or method found",
                                    runtime_type = bType_runtime.Name });
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        details.Add(new { building = bType, error = ex.Message });
                    }
                }

                tcs.SetResult(new
                {
                    ok = true,
                    location = farm?.Name,
                    onFarm,                                   // 🧭 人不在农场 ⇒ 一条都没翻（全在 skipped 里）
                    reachTiles = ReachTiles,
                    playerX = fTile.X,
                    playerY = fTile.Y,
                    toggled,
                    details,                                  // 翻了哪几栋（带 doorX/doorY + 翻后门态）
                    skipped                                   // 🧭 够不着的（doorX/doorY + reason）⇒ 走过去再叫一次
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /sprinklers
    /// Scans current location (or farm) for sprinklers and their coverage area.
    /// Returns sprinkler positions and the tiles they cover.
    /// </summary>
    private object HandleSprinklers()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var sprinklers = new List<object>();

                foreach (var obj in loc.Objects.Values)
                {
                    if (obj == null) continue;
                    var name = obj.Name;
                    int range = 0;
                    string type = "none";

                    if (name.Contains("Sprinkler"))
                    {
                        if (name.Contains("Iridium"))
                        { range = 2; type = "iridium"; }      // 5x5
                        else if (name.Contains("Quality"))
                        { range = 1; type = "quality"; }       // 3x3
                        else
                        { range = 1; type = "basic"; }         // 4 adjacent

                        var tiles = new List<Dictionary<string, int>>();
                        int ox = (int)obj.TileLocation.X;
                        int oy = (int)obj.TileLocation.Y;

                        if (type == "basic")
                        {
                            tiles.Add(new() { ["x"] = ox, ["y"] = oy - 1 });
                            tiles.Add(new() { ["x"] = ox, ["y"] = oy + 1 });
                            tiles.Add(new() { ["x"] = ox - 1, ["y"] = oy });
                            tiles.Add(new() { ["x"] = ox + 1, ["y"] = oy });
                        }
                        else
                        {
                            for (int dx = -range; dx <= range; dx++)
                                for (int dy = -range; dy <= range; dy++)
                                    if (dx != 0 || dy != 0)
                                        tiles.Add(new() { ["x"] = ox + dx, ["y"] = oy + dy });
                        }

                        sprinklers.Add(new
                        {
                            name,
                            type,
                            x = ox,
                            y = oy,
                            tiles
                        });
                    }
                }

                tcs.SetResult(new
                {
                    ok = true,
                    location = loc.Name,
                    count = sprinklers.Count,
                    sprinklers
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// POST /till_area
    /// Directly creates HoeDirt terrain features on specified tiles (bypasses tool animation).
    /// Body: { tiles: [{x,y}, ...], power?: 0-4 }
    ///       OR { x, y, length, direction, power? }
    /// </summary>
    private object HandleTillArea(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var farmer = Game1.player;
                var tiles = CalculateAreaTiles(p, farmer);
                var tilled = new List<Dictionary<string, int>>();
                var skipped = new List<Dictionary<string, object?>>();

                foreach (var (tx, ty) in tiles)
                {
                    var vec = new Vector2(tx, ty);
                    // Skip if already has HoeDirt or occupied
                    if (loc.terrainFeatures.ContainsKey(vec))
                    {
                        if (loc.terrainFeatures[vec] is HoeDirt)
                            skipped.Add(new() { ["x"] = tx, ["y"] = ty, ["reason"] = "already_tilled" });
                        else
                            skipped.Add(new() { ["x"] = tx, ["y"] = ty, ["reason"] = "occupied" });
                        continue;
                    }
                    if (loc.objects.ContainsKey(vec))
                    {
                        skipped.Add(new() { ["x"] = tx, ["y"] = ty, ["reason"] = "object" });
                        continue;
                    }
                    // ⚠️ 2026-08-13：不可耕地块不强行锄（恒：补漏把非耕地也改了=bug）
                    if (loc.doesTileHaveProperty(tx, ty, "Diggable", "Back") == null)
                    {
                        skipped.Add(new() { ["x"] = tx, ["y"] = ty, ["reason"] = "not_diggable" });
                        continue;
                    }

                    // 🌧️ 2026-09-17 恒真机抓到：直接 `new HoeDirt()` 绕过了游戏锄地的"雨天自动浇湿"。
                    //    铁证（同一场雷暴雨里做的 A/B）：逐格真挥锄 → watered=true；/tool_area → watered 空。
                    //    后果比看着严重：water 域 op **遇雨自动跳过**（恒 09-12 拍板），
                    //    所以这些格子**永远喝不到水**、作物不长 —— 而 DLL 自动补漏也走这条 ⇒
                    //    连普通 farm till 都会悄悄留下干土（真机见"2 干 2 湿"）。
                    //    判据用 loc.IsRainingHere() 而不是 Game1.isRaining：温室不能被外面下雨浇到。
                    var dirt = new HoeDirt();
                    if (loc.IsRainingHere()) dirt.state.Value = 1;
                    loc.terrainFeatures[vec] = dirt;
                    tilled.Add(new() { ["x"] = tx, ["y"] = ty });
                }

                tcs.SetResult(new
                {
                    ok = true,
                    location = loc.Name,
                    tilled_count = tilled.Count,
                    skipped_count = skipped.Count,
                    tilled,
                    skipped
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// ⚠️ /water_area 已删除（2026-08-15 恒：直接改 dirt.state 是作弊，会误导 AI）。
    /// 浇水一律 tool_area 蓄力 + 逐锚点（`position`/`DoFunction` 真浇）——
    /// 🚫 **2026-10-04 恒拍板：水的"补漏直写"也删了**（原来 `PatchMissingOnMain` 的水分支仍是
    ///    `wdirt.state.Value = 1`，恒两次抓到"咔嚓一下全改了"）⇒ 现在水的漏格**只报不改**
    ///    （`still_missing` 回给 Python，让它打水/换锚点再浇）。锄地那条补漏仍在（造土没有别的路）。
    /// </summary>

    /// <summary>
    /// Helper: parse tile list from request body.
    /// Accepts explicit {tiles:[{x,y}]} OR {x, y, length, direction, power}
    /// </summary>
    private List<(int x, int y)> CalculateAreaTiles(Dictionary<string, object?> p, Farmer farmer)
    {
        // Explicit tile list takes priority
        if (p.TryGetValue("tiles", out var tilesObj) && tilesObj != null)
        {
            var list = new List<(int x, int y)>();
            if (tilesObj is JsonElement je && je.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in je.EnumerateArray())
                {
                    int tx = item.GetProperty("x").GetInt32();
                    int ty = item.GetProperty("y").GetInt32();
                    list.Add((tx, ty));
                }
            }
            if (list.Count > 0) return list;
        }

        // Power-based area calculation
        int x = GetParamOr(p, "x", -1);
        int y = GetParamOr(p, "y", -1);
        int power = GetParamOr(p, "power", 0);
        int length = GetParamOr(p, "length", -1);
        string direction = GetParamOr(p, "direction", "");

        // Default: use player's facing tile if no coordinates given
        if (x < 0 || y < 0)
        {
            var facingTile = GetFacingTile(farmer);
            x = (int)facingTile.X;
            y = (int)facingTile.Y;
        }

        var result = new List<(int x, int y)>();

        if (length > 0 && !string.IsNullOrEmpty(direction))
        {
            // Line mode
            int dx = direction == "horizontal" ? 1 : 0;
            int dy = direction == "vertical" ? 1 : 0;
            for (int i = 0; i < length; i++)
                result.Add((x + dx * i, y + dy * i));
        }
        else
        {
            // Power-based area (matches tool upgrade levels)
            int dx = farmer.FacingDirection switch { 1 => 1, 3 => -1, _ => 0 };
            int dy = farmer.FacingDirection switch { 0 => -1, 2 => 1, _ => 0 };
            // Line perpendicular to facing direction
            int px = dy, py = dx; // perpendicular

            switch (power)
            {
                case 0: // 1 tile
                    result.Add((x, y));
                    break;
                case 1: // 3 tiles in a line (copper)
                    for (int i = -1; i <= 1; i++)
                        result.Add((x + px * i, y + py * i));
                    break;
                case 2: // 5 tiles in a line (steel)
                    for (int i = -2; i <= 2; i++)
                        result.Add((x + px * i, y + py * i));
                    break;
                case 3: // 3x3 square (gold)
                    for (int dx2 = -1; dx2 <= 1; dx2++)
                        for (int dy2 = -1; dy2 <= 1; dy2++)
                            result.Add((x + dx2, y + dy2));
                    break;
                case 4: // 3x6/6x3 rectangle (iridium)
                    for (int dx2 = 0; dx2 <= 2; dx2++)
                        for (int dy2 = -2; dy2 <= 2; dy2++)
                            result.Add((x + dx2, y + dy2));
                    break;
                default:
                    result.Add((x, y));
                    break;
            }
        }

        return result;
    }

    /// <summary>
    /// POST /tool_area
    /// Tool area operation with proper charge-release animation.
    /// Auto-detects target area if not specified.
    /// Body: { operation: "water"|"till", x1?, y1?, x2?, y2? }
    /// </summary>
    private object HandleToolArea(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var operation = GetParam<string>(p, "operation");

        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");
        if (operation != "water" && operation != "till")
            return new { ok = false, error = "operation must be 'water' or 'till'" };

        // 🧹 2026-09-23：本轮状态**开工前先清**。`_commandQueueTcs` 是上一轮的 TCS——本轮 calc 若早退
        //    （比如"矩形里没有要浇的作物"），下面 `if (_commandQueueTcs != null)` 会**拿上一次的结果当本次回包**
        //    ⇒ 明明报错却回一个陈旧的 ok:true（"工具说谎"那一族）。清掉即走 calcResult 里的真错误。
        _commandQueueTcs = null;
        _toolAreaOutOfWater = false;

        // 1. CALCULATION — runs on main thread (needs game state)
        var calcTcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                var loc = farmer.currentLocation;

                // Validate tool
                Tool? tool = farmer.CurrentTool;
                string requiredTool = operation == "water" ? "Watering Can" : "Hoe";
                if (tool == null || !tool.Name.Contains(requiredTool))
                {
                    var found = farmer.Items.OfType<Tool>()
                        .FirstOrDefault(t => t.Name.Contains(requiredTool));
                    if (found == null)
                    { calcTcs.SetResult(new { ok = false, error = $"No {requiredTool} in inventory" }); return; }
                    farmer.CurrentToolIndex = farmer.Items.IndexOf(found);
                    tool = found;
                }

                int upgradeLevel = 0;
                try { upgradeLevel = tool.UpgradeLevel; } catch { }

                var (toolW, toolH, chargeFrames) = upgradeLevel switch
                {
                    // toolW=垂直宽, toolH=面向距离（实测2026-08-02：宽3距离6，非6宽3距离）
                    0 => (1, 1, 0), 1 => (1, 3, 20), 2 => (1, 5, 40),
                    3 => (3, 3, 60), 4 => (3, 6, 80), _ => (1, 1, 0)
                };

                // Determine target tiles
                int x1 = GetParamOr(p, "x1", -1), y1 = GetParamOr(p, "y1", -1);
                int x2 = GetParamOr(p, "x2", -1), y2 = GetParamOr(p, "y2", -1);
                ModEntry.Instance?.Monitor.Log($"[tool-area] op={operation} 收到 rect: x1={x1} y1={y1} x2={x2} y2={y2}（-1=无，走自动检测）", LogLevel.Info);
                List<(int tx, int ty)> targetTiles = new();

                if (x1 >= 0 && y1 >= 0 && x2 >= 0 && y2 >= 0)
                {
                    // ⚠️ 2026-08-13：矩形路径加 Diggable 校验——只锄可耕地，路径/建筑/水不碰（恒：栅栏外凭空造土块=bug）
                    // ⚠️ 2026-09-03 恒：再加物件校验——箱子/洒水器等占了格就整格跳过，否则锄到箱子上（AI 冒烟实测打卡）
                    // ⚠️ 2026-09-10 恒（"加强认定"）：补上**第二道门** `IsTileBlockedBy`——与游戏 `makeHoeDirt` 逐字对齐
                    //    （同 4768 那条 08-15 给 plot_plan 的修正；`/surroundings` 的 diggable 早就是两道门，只有这里漏了）。
                    //    病根：只查 Diggable 会把"**可耕但被建筑/物件挡住**"的格当目标 → 游戏 `DoFunction` 的
                    //    `makeHoeDirt` 按第二道门**拒绝**它 → 它变成"漏格" → 再被 `PatchMissingOnMain` **强行写土**
                    //    ⇒ 土长到建筑/小屋贴图上（恒 09-10 沙滩抓到）。补漏绝不该比游戏自己更敢种土。
                    // 🚨 2026-09-23 恒真机：「浇水和播种还有点点不满意…**没有作物、没有耕的地也在浇**！很笨笨。」
                    //    根因：这一段**从来没按 operation 分岔**——`operation=water` 也套上面那套**锄地**两道门，
                    //    于是"目标格"= 矩形里的**可耕空地**（压根没有 HoeDirt、没有作物），而真正该用的浇水判据
                    //    只写在**没传 rect** 的自动检测分支里（下面那个 else）。后果是一串：
                    //      ① 锚点围着空地排 ⇒ 没作物/没翻的地也挥（白磨体力、白耗水）；
                    //      ② `FindMissingToolAreaTiles("water")` / 补漏那一层也吃这个错集合 ⇒ **浇水这路的"验证"一直在空转**。
                    //    ⇒ 按 operation 分岔：water 与自动检测分支**共用同一份** IsWaterTarget（判据只有一份）。
                    for (int x = Math.Min(x1, x2); x <= Math.Max(x1, x2); x++)
                        for (int y = Math.Min(y1, y2); y <= Math.Max(y1, y2); y++)
                        {
                            // 🪱 2026-09-19：两道门收敛进 IsTillTarget，并补上**斑点例外**
                            //    （斑点自己就是物件，原先被"有物件就跳过"整格排除 → 一个都挖不动）
                            if (operation == "water" ? IsWaterTarget(loc, x, y) : IsTillTarget(loc, x, y))
                                targetTiles.Add((x, y));
                        }
                }
                else
                {
                    for (int dx = -25; dx <= 25; dx++)
                        for (int dy = -25; dy <= 25; dy++)
                        {
                            int cx = farmer.TilePoint.X + dx, cy = farmer.TilePoint.Y + dy;
                            var vec = new Vector2(cx, cy);
                            if (operation == "water")
                            {
                                // 💧 2026-09-23：判据抽成 IsWaterTarget，与**矩形分支共用一份**（别两处各写各的）
                                if (IsWaterTarget(loc, cx, cy))
                                    targetTiles.Add((cx, cy));
                            }
                            else
                            {
                                // ⚠️ 2026-09-10 恒："加强认定"——自动检测分支同样补第二道门（理由见矩形分支）
                                // 🪱 2026-09-19：同矩形分支，改走 IsTillTarget（含斑点例外）
                                if (!loc.terrainFeatures.ContainsKey(vec) && IsTillTarget(loc, cx, cy))
                                    targetTiles.Add((cx, cy));
                            }
                        }
                }

                if (targetTiles.Count == 0)
                { calcTcs.SetResult(new { ok = false, error = $"No {(operation == "water" ? "unwatered crops" : "diggable tiles")} nearby" }); return; }

                // Calculate anchors (蓄力锚点生成，till/water 共用；补漏轮次也用它)
                var commands = BuildToolAreaCommands(targetTiles, toolW, toolH, chargeFrames, upgradeLevel);
                int minX = targetTiles.Min(t => t.tx), maxX = targetTiles.Max(t => t.tx);
                int minY = targetTiles.Min(t => t.ty), maxY = targetTiles.Max(t => t.ty);

                // Set up queue (main thread will process it tick by tick)
                _commandQueueTcs = new TaskCompletionSource<object>();
                _commandResults.Clear();
                _commandQueue = new Queue<Dictionary<string, object?>>(commands);
                _commandDelay = 0;
                _waitingForMove = false;
                // 存补漏参数（2026-08-15 恒：蓄力补漏用，不直接改地块）
                _toolAreaTargets = targetTiles;
                _toolAreaOperation = operation;
                _toolAreaToolW = toolW; _toolAreaToolH = toolH;
                _toolAreaChargeFrames = chargeFrames; _toolAreaUpgradeLevel = upgradeLevel;
                _toolAreaTotalSwings = commands.Count / 3;

                calcTcs.SetResult(new
                {
                    ok = true, operation, tool = tool.Name, upgrade_level = upgradeLevel,
                    target_area = new { x1 = minX, y1 = minY, x2 = maxX, y2 = maxY },
                    sw_width = toolW, sw_height = toolH, charge_frames = chargeFrames,
                    swings = commands.Count / 3  // move + face + charge per swing
                });
            }
            catch (Exception ex) { calcTcs.SetResult(new { ok = false, error = ex.Message }); }
        });

        // Wait for calc to finish (HTTP thread — fine)
        var calcResult = calcTcs.Task.GetAwaiter().GetResult();

        // 2. EXECUTION — wait on HTTP thread, NOT in EnqueueMainThread
        if (_commandQueueTcs != null)
        {
            bool completed = _commandQueueTcs.Task.Wait(TimeSpan.FromMinutes(10));
            var result = completed ? _commandQueueTcs.Task.Result
                : new { ok = false, error = "Tool area operation timed out" };

            // 3. 补漏（取余补站位逐格，2026-08-15 恒：main thread 直接 DoFunction，不走 queue/charge——
            //    实测 charge 蓄力等待期间位置可能漂移、fallback 从错位算导致浇不上（73,20-22 列案例）；
            //    直接 DoFunction（等效 /tool）position 站位可靠。仍漏的报 still_missing 原因）
            int patches = 0;
            // 💧 2026-09-23 恒真机："然后浇了一会儿**作弊把地块全改了不浇水了**"——就是这个循环干的：
            //    壶空停手后，剩下的格全成了"漏格" ⇒ 这里把 `wdirt.state.Value = 1` **咔嚓一下直写**，
            //    不挥壶、不费水、不走位。补漏的定位是"把游戏该做却漏掉的零星几格补上"（2026-09-03 恒：调体力），
            //    **不是"替 AI 把没水可浇的地全浇了"**。壶空时该做的事是**如实报剩多少格**，
            //    让 Python 去打水、回来拿同一块矩形再浇一遍（矩形过滤只挑"还没浇的"，幂等）。
            if (completed && !_toolAreaOutOfWater && operation == "till")
            {
                for (int round = 0; round < 4; round++)
                {
                    var missing = FindMissingToolAreaTiles(operation);
                    if (missing.Count == 0) break;
                    // 🔍 2026-09-03 恒（调体力）：每轮补漏看漏了几格、补上几格
                    ModEntry.Instance?.Monitor.Log($"[patch-loop] round={round} missing={missing.Count}", LogLevel.Info);
                    int fixedNow = PatchMissingOnMain(operation, missing.Select(m => (m.tx, m.ty)).ToList());
                    patches += fixedNow;
                    ModEntry.Instance?.Monitor.Log($"[patch-loop] round={round} fixedNow={fixedNow} accumPatches={patches}", LogLevel.Info);
                    if (fixedNow == 0) break;   // 一轮都补不上（被包围/水挡）→ 报告原因
                }
            }

            // 4. 最终仍漏（报告给 Python，AI 决定下一步；附原因——2026-08-15 恒：加报错原因）
            var still = completed ? FindMissingToolAreaTiles(operation) : new List<(int tx, int ty, string reason)>();
            var stillList = still.Select(t => new { x = t.tx, y = t.ty, reason = t.reason }).ToList();

            return new Dictionary<string, object?>
            {
                ["ok"] = completed,
                ["operation"] = operation,
                ["swings"] = _toolAreaTotalSwings,
                ["patches"] = patches,
                ["still_missing"] = stillList,
                // 💧 2026-09-23：壶空了、队列中途停手 ⇒ 让 Python 知道"这不是浇完了，是没水了"（含下一步：打水后重浇）
                ["out_of_water"] = _toolAreaOutOfWater,
                ["result"] = result
            };
        }

        return calcResult;
    }

    /// <summary>蓄力锚点生成（till/water 共用，补漏轮次也用它）。
    /// 面向下蓄力：toolW=垂直宽, toolH=面向距离（实测 1→3距离, 2→5, 4→6距离×3宽）。
    /// 锚点站耕地外上方（ay = tile_y - 1），charge 释放时覆盖 forward 范围。</summary>
    private static List<Dictionary<string, object?>> BuildToolAreaCommands(
        List<(int tx, int ty)> targetTiles, int toolW, int toolH, int chargeFrames, int upgradeLevel)
    {
        int minX = targetTiles.Min(t => t.tx), maxX = targetTiles.Max(t => t.tx);
        int minY = targetTiles.Min(t => t.ty), maxY = targetTiles.Max(t => t.ty);
        int nx = (int)Math.Ceiling((double)(maxX - minX + 1) / toolW);
        int ny = (int)Math.Ceiling((double)(maxY - minY + 1) / toolH);
        // 🚫 2026-09-23 恒真机："**还是会浇到未耕地！**"——锚点到这一步是按**外框**铺 `nx×ny` 个的，
        //    跟"这一锚点底下到底有没有要浇/要锄的格"**完全无关**。基础壶(1 格)碰上 11×7 的外框 =
        //    **77 个锚点**，可真实目标只有 49 格 ⇒ 人走满 77 格、对着没作物的空地照样挥。
        //    更疼的是**水也被空地喝掉了**：那趟 40 格水只浇到 18 格真作物，22 格喂了空地，
        //    壶一空就把剩下的 31 格丢给"补漏直写地块"（不挥壶不费水）——恒看到的就是
        //    "浇了一会儿，咔嚓一下全改了、人不浇了"。⇒ **只有喷到的范围里真有目标格的锚点才留**。
        var targetSet = new HashSet<(int, int)>(targetTiles);
        var commands = new List<Dictionary<string, object?>>();
        int anchorsAll = 0, anchorsKept = 0;
        // 🔍 2026-09-03 恒（调体力）：看目标矩形会切几个锚点（每个锚点=move+face+charge=3 条命令，释放一次 DoFunction）
        ModEntry.Instance?.Monitor.Log($"[build-cmds] rect=({minX},{minY})-({maxX},{maxY}) toolW={toolW} toolH={toolH} → nx={nx} ny={ny} anchors={nx * ny} totalCmds={nx * ny * 3}", LogLevel.Info);
        for (int row = 0; row < ny; row++)
        {
            int start = row % 2 == 0 ? 0 : nx - 1, end = row % 2 == 0 ? nx - 1 : 0, step = row % 2 == 0 ? 1 : -1;
            // 🎯 2026-09-04 恒（取余站位·根治）：站位从"机械 row*toolH 整推进"改成**顶对齐起手、底对齐收尾、允许相邻重叠**。
            //    余数行靠上一排喷范围往回重叠延伸覆盖——锄过的地可再锄，重叠无害；不越界、不缺行。
            //    ay = 锚点格子（面朝下喷 [ay+1, ay+toolH]）：首排站 minY-1，末排站 maxY-toolH，中间均匀。
            //    ①整除(toolH|H) → 排距=toolH，零重叠零缺；②余数 → 排距<toolH，末排回拉覆盖余数行。
            int ay;
            if (ny <= 1) ay = minY - 1;
            else
            {
                int hSpan = maxY - minY + 1;                     // H=目标行数
                int hDelta = hSpan - toolH;                       // 首尾锚点站位差（余数时 <toolH 产生重叠）
                ay = minY - 1 + (int)Math.Round((double)hDelta * row / (ny - 1), MidpointRounding.AwayFromZero);
            }
            for (int col = start; ; col += step)
            {
                // 🎯 2026-09-04 恒（横向取余·对称）：列中心同规则——左对齐起手、右对齐收尾、允许重叠。
                //    ax = 格子中心（喷 [ax-half, ax+half]，half=(toolW-1)/2）：首列中心 minX+half，末列中心 maxX-half，中间均匀。
                int ax;
                if (nx <= 1) ax = minX + toolW / 2;
                else
                {
                    int wSpan = maxX - minX + 1;                 // W=目标列数
                    int half = (toolW - 1) / 2;
                    int wDelta = wSpan - toolW;                   // 首尾中心差（余数时 <toolW 产生重叠）
                    ax = minX + half + (int)Math.Round((double)wDelta * col / (nx - 1), MidpointRounding.AwayFromZero);
                }
                anchorsAll++;
                // 逐锚点验证用（2026-08-15 恒）：该锚点蓄力/单格覆盖的格（toolW 宽 × toolH 高，面向下）
                var anchorTargets = new List<(int tx, int ty)>();
                int halfW2 = (toolW - 1) / 2;
                for (int dxx = -halfW2; dxx <= halfW2; dxx++)
                    for (int dyy = 1; dyy <= toolH; dyy++)
                        anchorTargets.Add((ax + dxx, ay + dyy));
                // 🚫 只留"喷得到真目标"的锚点（见函数头那条长注释）；喷了个空 → 这条命令整条不发。
                var hit = anchorTargets.FindAll(t => targetSet.Contains(t));
                if (hit.Count == 0)
                {
                    if (col == end) break;
                    continue;
                }
                anchorsKept++;
                commands.Add(new Dictionary<string, object?> { ["action"] = "move", ["x"] = ax, ["y"] = ay });
                commands.Add(new Dictionary<string, object?> { ["action"] = "face", ["direction"] = 2 });
                // targets 给**喷到的真目标**（不是整块几何范围）——逐锚点验证只该验真的目标格。
                if (chargeFrames > 0)
                    commands.Add(new Dictionary<string, object?> { ["action"] = "charge", ["frames"] = chargeFrames, ["power"] = upgradeLevel, ["targets"] = hit });
                else
                    commands.Add(new Dictionary<string, object?> { ["action"] = "use", ["targets"] = hit });
                if (col == end) break;
            }
        }
        ModEntry.Instance?.Monitor.Log($"[build-cmds] 锚点 {anchorsKept}/{anchorsAll} 个留（喷到空地的 {anchorsAll - anchorsKept} 个已丢）⇒ {anchorsKept} swings", LogLevel.Info);
        return commands;
    }

    /// <summary>主线程自检漏格（till: 应锄可锄但没成 HoeDirt；water: 有作物未浇）。
    /// 蓄力补漏的输入——只报漏，不改地块。reason=四向被什么挡（2026-08-15 恒：报错原因）。
    /// </summary>
    private List<(int tx, int ty, string reason)> FindMissingToolAreaTiles(string operation)
    {
        var tcs = new TaskCompletionSource<List<(int tx, int ty, string reason)>>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var missing = new List<(int tx, int ty, string reason)>();
                foreach (var (tx, ty) in _toolAreaTargets)
                {
                    var vec = new Vector2(tx, ty);
                    bool isMissing;
                    if (operation == "till")
                    {
                        bool hasDirt = loc.terrainFeatures.TryGetValue(vec, out var ttf) && ttf is HoeDirt;
                        // 🪱 2026-09-19：斑点格锄成后会「斑点了、HoeDirt 生」；**只剩斑点没土 = 这锄没成**，
                        //    要如实报出来（旧逻辑「有物件就当不缺」会把没挖成的斑点粉饰成成功）。
                        bool spotLeft = loc.objects.TryGetValue(vec, out var so) && IsDiggableSpot(so);
                        // 🫚 姜点锄成后「姜收了、HoeDirt 还在」⇒ 判据是**姜还在不在**，不是有没有土
                        bool gingerLeft = IsGingerTile(loc, vec);
                        isMissing = gingerLeft || (!hasDirt && (spotLeft
                            || (!loc.objects.ContainsKey(vec)
                                && loc.doesTileHaveProperty(tx, ty, "Diggable", "Back") != null)));
                    }
                    else
                    {
                        // 🍵 2026-10-04：走 `DirtAt` ⇒ 花盆也算（同一把尺）
                        var _dw = DirtAt(loc, vec);
                        isMissing = _dw != null && _dw.crop != null && _dw.state.Value == 0;
                    }
                    if (isMissing)
                        // 🩹 2026-09-23：`MissingReason` 数的是**四邻挡路**——那是**锄地**的口径
                        //    （站不站得住决定能不能挥）。浇水看的是"这格浇上没浇上"，四邻是 HoeDirt 很正常，
                        //    报「右HoeDirt」只会误导（恒 09-23 真机日志里就出现过「仍漏 29 格…右HoeDirt」）。
                        missing.Add((tx, ty, operation == "water" ? "还没浇上（壶里没水 / 蓄力没喷到这格）"
                                                                 : MissingReason(loc, tx, ty)));
                }
                tcs.SetResult(missing);
            }
            catch (Exception) { tcs.SetResult(new List<(int, int, string)>()); }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>漏格报错原因：四向邻格被什么挡（object/terrain/地图外）。</summary>
    private static string MissingReason(GameLocation loc, int tx, int ty)
    {
        // 🪱🫚 2026-09-19：先看**这一格自己**——斑点/姜没挖成的原因就在格上，别去数四邻
        var self = new Vector2(tx, ty);
        if (loc.objects.TryGetValue(self, out var selfObj) && IsDiggableSpot(selfObj))
            return $"格上还有{selfObj.DisplayName}，这一锄没挖成";
        if (IsGingerTile(loc, self))
            return "这格的姜还在，没收到";
        var parts = new List<string>();
        var dirs = new (int dx, int dy, string name)[] { (0, -1, "上"), (0, 1, "下"), (-1, 0, "左"), (1, 0, "右") };
        foreach (var (dx, dy, name) in dirs)
        {
            var v = new Vector2(tx + dx, ty + dy);
            if (!loc.isTileOnMap(v))
                parts.Add($"{name}地图外");
            else if (loc.objects.TryGetValue(v, out var obj))
                parts.Add($"{name}{obj.DisplayName}");
            else if (loc.terrainFeatures.TryGetValue(v, out var tf))
                parts.Add($"{name}{tf.GetType().Name}");
        }
        return parts.Count > 0 ? string.Join("；", parts) : "四向空旷但补不上";
    }

    /// <summary>逐锚点验证覆盖格是否"落地"（till=成 HoeDirt；water=有作物则已浇/无作物免）。漏的当场补漏。</summary>
    private void VerifyToolAreaAnchor(Dictionary<string, object?> cmd)
    {
        try
        {
            if (!cmd.TryGetValue("targets", out var tval) || tval is not List<(int tx, int ty)> targets) return;
            var missed = new List<(int tx, int ty)>();
            foreach (var (tx, ty) in targets)
            {
                if (!TileDone(_toolAreaOperation, tx, ty))
                    missed.Add((tx, ty));
            }
            if (missed.Count > 0)
                PatchMissingOnMain(_toolAreaOperation, missed);
        }
        catch { }
    }

    private static bool TileDone(string operation, int tx, int ty)
    {
        var loc = Game1.currentLocation;
        var vec = new Vector2(tx, ty);
        if (operation == "water")
        {
            // 🍵 2026-10-04：走 `DirtAt`（花盆里的泥也算这一格的"地"）
            var d = DirtAt(loc, vec);
            return d != null && (d.crop == null || d.state.Value == 1);
        }
        return loc.terrainFeatures.ContainsKey(vec) && loc.terrainFeatures[vec] is HoeDirt;
    }

    /// <summary>主线程直接补漏（取余补站位逐格）：对每个漏格，position 到候选站位 + face + 直接 DoFunction，
    /// 逐个方向尝试直到补上。不走命令队列、不等待蓄力——避开 charge 蓄力等待期间位置漂移导致 fallback 错位的问题
    /// （实测 2026-08-15：tool_area charge 对 (73,20-22) 列失效，手动 position+挥壶能浇上）。
    /// 返回本次补上的格数。</summary>
    private int PatchMissingOnMain(string operation, List<(int tx, int ty)> missing)
    {
        var farmer = Game1.player;
        var loc = farmer?.currentLocation;
        if (farmer == null || loc == null) return 0;
        // ⚠️ 2026-09-03 恒（调体力，真根因）：补漏=直接改地块，**绝不挥 DoFunction**。
        //    旧代码对每个漏格 × 4 方向 DoFunction——level-4 铱锄头每挥吃满 6×3=18 格能量，
        //    实测 5×1 锄地(只想 5 格) → 补漏扫出 31 格 × 多方向 = 数十挥 = 366 能量(353→-13)。
        //    根因：蓄力几何没盖到的"取余漏格"，本该零星几个，却因玩家漂移+重复触发被放大成一片；
        //    且每挥都是整格面积能耗。→ 补漏直接放 HoeDirt / 改水态，等效原版、零能耗、不漂移。
        //    真挥锄(带动画/蓄力感)交给 charge-release(每锚点恰 1 次)。
        int fixedCount = 0;
        foreach (var (tx, ty) in missing)
        {
            var vec = new Vector2(tx, ty);
            bool patched = false;
            try
            {
                if (operation == "till")
                {
                    // 目标格 Diggable 且无 object 才放（与 rect 校验一致，别在水/箱子/设备上造耕土）
                    // 🚨 2026-09-10 恒（"加强认定"）：**必须补第二道门**——这里是全项目**唯一绕过游戏自己造土**的地方。
                    //    少了 `IsTileBlockedBy` 就等于比游戏还敢种：游戏 `makeHoeDirt` 会拒绝的格子（可耕但被建筑/物件挡住），
                    //    补漏照样 `terrainFeatures[vec] = new HoeDirt()` 硬写 ⇒ 土长到建筑/小屋贴图上。
                    //    补漏的定位是"把游戏该种却没种上的补上"，**不是"种游戏不认的"**。
                    if (loc.doesTileHaveProperty(tx, ty, "Diggable", "Back") != null
                        && !loc.objects.ContainsKey(vec)
                        && !loc.terrainFeatures.ContainsKey(vec)
                        && !loc.IsTileBlockedBy(vec, ~(StardewValley.CollisionMask.Characters | StardewValley.CollisionMask.Farmers)))
                    {
                        // 🌧️ 2026-09-17：补漏也用无参构造 ⇒ 同样漏掉"雨天浇湿"（同上面 15726 那条）。
                        //    补漏正是"2 干 2 湿"里那两个干格的来源，别只修主循环。
                        var ndirt = new HoeDirt();   // 与人/132xxx 同款无参构造
                        if (loc.IsRainingHere()) ndirt.state.Value = 1;
                        loc.terrainFeatures[vec] = ndirt;
                        patched = true;
                    }
                }
                else // water
                {
                    // 🚫🚫 **2026-10-04 恒拍板：水的补漏直写整段删掉**（原代码是
                    //   `if (loc.terrainFeatures.TryGetValue(vec, out var wtf) && wtf is HoeDirt wdirt)
                    //        { wdirt.state.Value = 1; patched = true; }`）。
                    //   为什么删：
                    //     ① **它是"作弊"观感的唯一来源**：不挥壶、不费水、不走位，直接改地块
                    //        —— 恒 09-23 真机抓到过（"浇了一会儿**咔嚓一下全改了**、人不浇了"），
                    //        2026-10-04 又问了一次"什么时候又变成了作弊瞬间改整片浇水"。
                    //     ② **判据本身也不该由它来兜**：`water` 的漏格要么是**锚点几何**没盖到
                    //        （那就该修几何 / 换锚点再浇一次），要么是**壶空了**（`_toolAreaOutOfWater`
                    //        ⇒ Python 去打水、拿同一块矩形重浇，天然幂等）。
                    //     ③ 脚本那层早就写好了"还剩几格没浇上"的**如实报**（`still_missing`）。
                    //   ⇒ 现在水的漏格**只报不改**：`still_missing` 原样回给 Python。
                    //   锄地那条**留着**（`terrainFeatures[vec] = new HoeDirt()`）：造土没有别的路，
                    //   且它有两道门（Diggable + IsTileBlockedBy，见上面那段）。
                }
            }
            catch (Exception) { }
            if (patched) fixedCount++;
        }
        return fixedCount;
    }

    /// <summary>
    /// ── 命令队列参数读取：兼容 C# 直接构造的 Dictionary（tool_area）和 HTTP 来的 JsonElement ──
    private static string CmdString(Dictionary<string, object?> cmd, string key, string def = "")
    {
        if (!cmd.TryGetValue(key, out var val) || val == null) return def;
        if (val is JsonElement je)
            return je.ValueKind == JsonValueKind.String ? je.GetString() ?? def : je.ToString() ?? def;
        return val.ToString() ?? def;
    }

    private static int CmdInt(Dictionary<string, object?> cmd, string key, int def = 0)
    {
        if (!cmd.TryGetValue(key, out var val) || val == null) return def;
        if (val is JsonElement je)
        {
            if (je.ValueKind == JsonValueKind.Number) return je.GetInt32();
            return int.TryParse(je.ToString(), out var n) ? n : def;
        }
        if (val is int i) return i;
        return int.TryParse(val.ToString(), out var n2) ? n2 : def;
    }

    /// Calculate tiles affected by a tool swing at (fx, fy) facing direction with given power.
    /// Power: 0=1 tile, 1=3 line, 2=5 line, 3=3x3 area, 4=6x3 area
    /// </summary>
    private static List<(int, int)> GetToolAffectedTiles(int fx, int fy, int facing, int power)
    {
        var tiles = new List<(int, int)>();
        int fdx = facing switch { 1 => 1, 3 => -1, _ => 0 };
        int fdy = facing switch { 0 => -1, 2 => 1, _ => 0 };
        int pdx = facing switch { 0 => 1, 2 => -1, 1 => 0, 3 => 0, _ => 0 };
        int pdy = facing switch { 0 => 0, 2 => 0, 1 => 1, 3 => -1, _ => 0 };

        // w=垂直宽(perp), h=面向距离(forward)。实测2026-08-02：1→3距离, 2→5距离, 4→6距离×3宽
        int w = power switch { 0 => 1, 1 => 1, 2 => 1, 3 => 3, 4 => 3, _ => 1 };
        int h = power switch { 0 => 1, 1 => 3, 2 => 5, 3 => 3, 4 => 6, _ => 1 };
        int halfW = (w - 1) / 2;

        for (int hi = 1; hi <= h; hi++)
            for (int wi = -halfW; wi <= w / 2; wi++)
                tiles.Add((fx + fdx * hi + pdx * wi, fy + fdy * hi + pdy * wi));

        return tiles;
    }

    private object HandleMuseumDonate()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
	                var farmer = Game1.player;
	                var museum = Game1.getLocationFromName("ArchaeologyHouse");
	                if (museum == null)
	                {
	                    tcs.SetResult(new { ok = false, error = "ArchaeologyHouse not found" });
	                    return;
	                }

	                // 获取合法空展位: 用 LibraryMuseum.getFreeDonationSpot()
	                //   判据（反编译 LibraryMuseum.cs:467-478 `isTileSuitableForMuseumPiece`）= 该格**没被占**
	                //   且 Buildings 图层 tile index ∈ {1072,1073,1074} ∪ {1237,1238}。
	                //   ⇒ "哪些格子能摆"由**地图自己**说，不是我们手抄的坐标表（手抄表只留作最后兜底）。
	                var libMuseum = museum as StardewValley.Locations.LibraryMuseum;
	                var displaySlots = new List<(int x, int y)>();
	                try
	                {
	                    if (libMuseum != null)
	                    {
	                        while (true)
	                        {
	                            var spot = libMuseum.getFreeDonationSpot();
	                            if (spot == default || (spot.X == 0 && spot.Y == 0) || displaySlots.Contains(((int)spot.X, (int)spot.Y)))
	                                break;
	                            // ⛔ 2026-09-12 恒：**这道闸不能省**。游戏原版 getFreeDonationSpot() 在
	                            //   **找不到任何空位时返回硬编码坐标 (26,5)**（反编译 LibraryMuseum.cs:568 末尾
	                            //    `return new Vector2(26f, 5f);`），而本循环的终止条件只认 (0,0) ⇒
	                            //    "博物馆已满"时它会往 (26,5) 写 _diag_ 占位符、**覆盖掉那儿的真展品**，
	                            //    随后 cleanup 见值是 _diag_ 就 Remove ⇒ **真展品被删掉**。
	                            //    真机实测：满馆调一次 donate ⇒ 展品 95 → 94，且 (26,5) 变空。
	                            //    闸门=占位符**只许写在空位上**；返回的坐标已经有东西 ⇒ 那是"没空位"的哨兵，停手。
	                            var vKey = new Vector2(spot.X, spot.Y);
	                            if (Game1.netWorldState.Value.MuseumPieces.ContainsKey(vKey))
	                                break;
	                            displaySlots.Add(((int)spot.X, (int)spot.Y));
	                            Game1.netWorldState.Value.MuseumPieces[vKey] = "_diag_";
	                        }
	                        foreach (var (sx, sy) in displaySlots)
	                        {
	                            var vKey = new Vector2(sx, sy);
	                            if (Game1.netWorldState.Value.MuseumPieces.TryGetValue(vKey, out var val) && val == "_diag_")
	                                Game1.netWorldState.Value.MuseumPieces.Remove(vKey);
	                        }
	                    }
	                }
	                catch { }
	                // 兜底: 手动扫 Buildings 图层 —— tile index 用**游戏自己的**那几个（1072-1074 / 1237-1238），
	                //   并再过一遍 `isTileSuitableForMuseumPiece`（顺手判"这格是不是已经被占了"）。
	                //   ⛔ 旧代码这里写的是 `TileIndex == 173` —— 不是展位瓦片编号，纯属抄错（真被走到会往非展位塞东西）。
	                if (displaySlots.Count == 0)
	                {
	                    try
	                    {
	                        var bLayer = museum.Map.GetLayer("Buildings");
	                        if (bLayer != null)
	                        {
	                            for (int x = 0; x < bLayer.LayerWidth; x++)
	                                for (int y = 0; y < bLayer.LayerHeight; y++)
	                                {
	                                    int ti = bLayer.Tiles[x, y]?.TileIndex ?? -1;
	                                    bool isDisplayTile = (ti >= 1072 && ti <= 1074) || ti == 1237 || ti == 1238;
	                                    if (isDisplayTile && (libMuseum == null || libMuseum.isTileSuitableForMuseumPiece(x, y)))
	                                        displaySlots.Add((x, y));
	                                }
	                        }
	                    }
	                    catch { }
	                }
	                // 兜底2: 已知标准展位 —— ⚠️这是**猜的**（手抄），只在上面两条路都空手时才用；返回里会标出来。
	                bool slotsAreGuessed = false;
	                if (displaySlots.Count == 0)
	                {
	                    slotsAreGuessed = true;
	                    var known = new (int, int)[] {
	                        (26,11),(27,11),(28,11),(29,11),(30,11),(31,11),(32,11),(33,11),(34,11),(35,11),
	                        (27,8),(28,8),(29,8),(30,8),(31,8),(32,8),(33,8),(34,8),(35,8),
	                        (27,6),(28,6),(29,6),(30,6),(31,6),(32,6),(33,6),(34,6),(35,6),
	                        (27,5),(28,5),(29,5),(30,5),(31,5),(32,5),(33,5),(34,5),(35,5),
	                        (27,4),(28,4),(29,4),(30,4),(31,4),(32,4),(33,4),(34,4),(35,4),
	                    };
	                    displaySlots.AddRange(known);
	                }
	                // 找出空位
	                // ⛔ 2026-10-05 恒："我们的捐献是不是按游戏内名单认的" —— 查证结论（反编译为准）：
	                //   ① "能捐哪些"**从来没抄名单**，是**问游戏**（`isItemSuitableForDonation`，见下面循环）；
	                //      游戏自己那份"名单"也是**算出来的**：遍历 `ItemRegistry.RequireTypeDefinition("(O)")`
	                //      逐件过判据（`LibraryMuseum.totalArtifacts`，反编译 :30-47）。所以没有"五六十件"的手抄表存在。
	                //   ② "这个格子有没有东西"旧代码用 `farmer.archaeologyFound` 比 (x,y) 判 —— **口径错**：
	                //      1.6 的 `archaeologyFound` 是**"捡到过这种几件"**的计数表（`Farmer.foundArtifact`
	                //      写 {n,n}，反编译 Farmer.cs:2959-2976；收藏页取 value[0] 显示"已找到 N 件"，
	                //      CollectionsPage.cs:752），**不是展位坐标表**。
	                //      真机现场：本角色 7 条记录全是 {1,1} ⇒ 比不中任何展位坐标 ⇒ 这道筛子一直在空转（语义是错的）。
	                //   ⇒ 占没占**只认 `MuseumPieces`**（游戏自己就是这么判的：`HasDonatedArtifactAt`，
	                //      反编译 LibraryMuseum.cs:81-84）。
	                var emptySlots = displaySlots
	                    .Where(s => !Game1.netWorldState.Value.MuseumPieces.ContainsKey(new Vector2(s.x, s.y)))
	                    .ToList();

	                var donated = new List<object>();
	                var rejected = new List<object>();   // 如实记账：每件"为什么没捐"
	                int looked = 0;                      // 真正检查过的 Object 件数
	                for (int i = 0; i < farmer.Items.Count && emptySlots.Count > 0; i++)
	                {
	                    if (farmer.Items[i] is StardewValley.Object obj)
	                    {
	                        // 兼容多种 ID 格式：ItemId / QualifiedItemId / 裸 ID
	                        string id = obj.ItemId ?? "";
	                        string qid = obj.QualifiedItemId ?? "";
	                        string bareId = id.Contains(")") ? id.Split(')')[1] : id;
	                        if (string.IsNullOrEmpty(bareId)) bareId = qid.Contains(")") ? qid.Split(')')[1] : qid;
	                        looked++;

	                        // 判据=游戏自己的 LibraryMuseum.isItemSuitableForDonation
	                        //   （not_museum_donatable 标签 / 已捐过 / 既非矿物又非古物 → 它都挡）。
	                        //   ⚠️ "已捐过"它**也管**：`IsItemSuitableForDonation` 内部就调 `HasDonatedArtifact`
	                        //   （扫 `MuseumPieces` 的值，跨角色共享，反编译 :88-103 / :126）⇒ 不需要再自己判一次。
	                        // ⛔ 2026-09-12 恒：**删掉了原来的 category 兜底**。它把"判据说不行"和"判据没拿到"
	                        //    混成了同一种情况，真机实测后果（博物馆本来就 95/95 全齐）：
	                        //      · 已捐过的方解石(-12)/铁铅矿(-12) 被重新塞进第二个展位
	                        //        ⇒ museumPieces 变成 97 条 / 95 个 id（多出 2 条幻影展品）
	                        //      · 羊奶酪(工匠品) 被当成"宝石"捐掉、从背包消失
	                        //    两个根因：① 常量认错 —— -26 是 artisanGoods(工匠品)、-23 是
	                        //    sellAtFishShop(鱼店可售)，真正的宝石是 -2；② "已经捐过"也走这条兜底，
	                        //    所以全齐的博物馆照样能被再塞一遍。
	                        //    按《宁报错别兜底》：判据拿不到就**明确报错**，不许拿一张猜的类别表放行。
	                        bool suitable;
	                        try
	                        {
	                            if (libMuseum == null)
	                            {
	                                tcs.SetResult(new { ok = false,
	                                    error = "ArchaeologyHouse 不是 LibraryMuseum，拿不到可捐性判据 —— 拒绝捐（宁可报错也不猜）" });
	                                return;
	                            }
	                            suitable = libMuseum.isItemSuitableForDonation(obj);
	                        }
	                        catch (Exception ex)
	                        {
	                            tcs.SetResult(new { ok = false,
	                                error = $"可捐性判据调用失败：{ex.Message} —— 拒绝捐（宁可报错也不猜）" });
	                            return;
	                        }
	                        if (!suitable)
	                        {
	                            // 游戏说不行就是不行，别再兜底 —— 但**要记账**（不然"为什么没捐"又变成一句糊话）。
	                            bool alreadyThere = false;
	                            try { alreadyThere = StardewValley.Locations.LibraryMuseum.HasDonatedArtifact(obj.QualifiedItemId); }
	                            catch { }
	                            rejected.Add(new { item = obj.Name, id = bareId,
	                                why = alreadyThere
	                                    ? "博物馆已经收过这件了（`HasDonatedArtifact`：MuseumPieces 里有这个 id，跨角色共享）"
	                                    : "游戏判据说这件不能捐（既非古物/矿物，或带 not_museum_donatable 标签）" });
	                            continue;
	                        }

	                        var slot = emptySlots[0];
	                        emptySlots.RemoveAt(0);
	                        // 同步到博物馆展品数据 —— **这是"真捐"唯一该写的东西**
	                        //   （反编译 `MuseumMenu.cs:214-230`：`isTileSuitableForMuseumPiece && isItemSuitableForDonation`
	                        //    ⇒ `museum.museumPieces.Add(new Vector2(x,y), item.ItemId)` + `completeQuest("24")`
	                        //    + 消耗 1 个 + `stats.checkForArchaeologyAchievements()` + 广播；
	                        //    **全程不碰 `archaeologyFound`**）。
	                        // ⛔ 2026-10-05 恒：删掉了 `farmer.archaeologyFound[bareId] = new int[]{slot.x, slot.y}`。
	                        //   1.6 的 `archaeologyFound` 是"捡到过几件"的计数表（见上），把**展位坐标**写进去
	                        //   = 把"已找到 N 件"写成 28/31 这种数字（收藏页会显示"找到 28 件"）—— 那是污染存档，
	                        //   而且会让下面那句 `alreadyDonated`（旧代码）把"捡到过"误当"捐过"，永久挡住这件。
	                        //   真机现场：古代玩偶 (O)103 在 `archaeologyFound` 里（捡到过）、但**不在** `MuseumPieces` 里
	                        //   （没捐过）⇒ 旧代码一句 `continue` 把它假拒了 —— 就是恒问的"古代玩偶真的不行吗"。
	                        try {
	                            var vec2 = new Vector2(slot.x, slot.y);
	                            var np = Game1.netWorldState.Value.MuseumPieces;
	                            if (!np.ContainsKey(vec2))
	                                np.Add(vec2, bareId);
	                        } catch { }
	                        // 游戏真捐时顺带做的两件事（不做的话"展品在、任务/成就没算"就是半个假捐）。
	                        try { farmer.completeQuest("24"); } catch { }
	                        try { Game1.stats.checkForArchaeologyAchievements(); } catch { }
	                        // 📢 2026-10-05（补24d）**补上补23 漏掉的那声广播** —— 恒真机验过："捐成功了但没广播"
	                        //    （他正是靠"没广播"起疑 ⇒ 又用 7842 拿同一件去捐 ⇒ 捐不动 ⇒ **反证那次捐献确实成功了**）。
	                        //    照反编译 `MuseumMenu.cs:231-247` 抄，**每捐成一件都比一次**（一次捐多件时逐件判）。
	                        //    ⚠️ 反编译里这一整段还套在 `if (!holdingMuseumPiece)` 里 —— 那是"手上捧着展品在重排"的状态；
	                        //       我们是"从背包直接捐"，从来不是那种状态 ⇒ 那个条件恒真，不用抄。
	                        //    ⚠️ 广播失败**绝不许**把捐赠本身搞失败（整段包在 try/catch 里）。
	                        try {
	                            int afterCount = Game1.netWorldState.Value.MuseumPieces.Length;
	                            if (afterCount == StardewValley.Locations.LibraryMuseum.totalArtifacts)
	                                Game1.Multiplayer.globalChatInfoMessage("MuseumComplete", Game1.player.farmName.Value);
	                            else if (afterCount == 40)
	                                Game1.Multiplayer.globalChatInfoMessage("Museum40", Game1.player.farmName.Value);
	                            else
	                                Game1.Multiplayer.globalChatInfoMessage("donation", Game1.player.name.Value,
	                                    StardewValley.TokenizableStrings.TokenStringBuilder.ItemNameFor(obj));
	                        } catch { }
	                        donated.Add(new { item = obj.Name, id = bareId, tileX = slot.x, tileY = slot.y,
	                            itemId = id, qualifiedId = qid });
	                        obj.Stack--;
	                        if (obj.Stack <= 0) farmer.Items[i] = null;
	                    }
	                }

	                // ⚠️ `archaeologyFound.Count` 是"**捡到过**几种"，**不是**"捐了几件"（口径纠正见上）。
	                //    真要报"捐了多少"用 `MuseumPieces.Length`。
	                int foundKinds = farmer.archaeologyFound.Keys.Count();
	                int museumCount = Game1.netWorldState.Value.MuseumPieces.Length;
	                int totalArtifacts = 0;
	                try { totalArtifacts = StardewValley.Locations.LibraryMuseum.totalArtifacts; } catch { }
	                int remaining = emptySlots.Count;
	                if (donated.Count > 0)
	                    tcs.SetResult(new { ok = true, donated, rejected, checkedCount = looked,
	                        foundKinds, museumCount, totalArtifacts,
	                        remainingSlots = remaining, slotsAreGuessed });
	                else
	                {
	                    // ⛔ 2026-10-05 恒：旧代码不管什么原因都回一句英文
	                    //   "No new items to donate or no empty slots" —— 把"没东西可捐"和"没空位"
	                    //   混成一句（就是这句糊话把"古代玩偶明明能捐"盖住的）。现在**分开说 + 带账**。
	                    string why = remaining == 0
	                        ? $"博物馆没有空展位了（已展出 {museumCount} 件 / 游戏名单共 {totalArtifacts} 件）"
	                        : $"背包里没有能捐的了（空展位还有 {remaining} 个；查了 {looked} 件，全被游戏判据挡下）";
	                    tcs.SetResult(new { ok = false, error = why, emptySlots = remaining, checkedCount = looked,
	                        rejected, foundKinds, museumCount, totalArtifacts, slotsAreGuessed });
	                }
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleMachines()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.player.currentLocation;
                var machines = new List<object>();
                ScanLocationMachines(loc, loc.Name, machines, BuildBuildingMap());

                tcs.SetResult(new
                {
                    ok = true,
                    location = loc.Name,
                    count = machines.Count,
                    machines
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// 扫描一个地点的所有 bigCraftable 机器（Keg/Furnace/Dehydrator…），带 location 归属。
    /// 供 /machines（当前地点）和 /farm_report（全农场）复用。
    /// </summary>
    private static void ScanLocationMachines(GameLocation loc, string locationKey, List<object> machines,
        Dictionary<GameLocation, (int x, int y, int doorX, int doorY)>? buildingMap = null)
    {
        foreach (var pair in loc.objects.Pairs)
        {
            var obj = pair.Value;
            if (!obj.bigCraftable.Value) continue;

            string status;
            if (obj is IndoorPot pot)
            {
                // 🍵 2026-10-05（补28d）：花盆原来**恒报 `empty`** —— 补27b 真机逮到：盆里种着小麦，
                //    `/machines` 的 `status` 仍是 `empty`。根因：盆里的作物**不住在** `heldObject` /
                //    `readyForHarvest` 上，而住在 `pot.hoeDirt.Value.crop`（反编译 `IndoorPot.cs:12-24`）
                //    ⇒ 下面那三档判据**根本看不见它**。
                //    ⇒ 这里按**盆里那份泥**问游戏，判据与 `/surroundings`（本文件 7424 行
                //      `harvestable = dirt.readyForHarvest()`）**同一把尺子**，不另立一套。
                //    ⚠️ `growing` 是**新增的第 4 档**（有作物但还不能收）：原来只能落进 empty/processing，
                //      两个都不如实 —— 而 "empty = 盆空着" 是**假信息**，正是恒指出来的那个坑。
                var potDirt = pot.hoeDirt?.Value;
                if (potDirt?.crop == null)
                    status = "empty";
                else if (potDirt.readyForHarvest())
                    status = "ready";
                else
                    status = "growing";
            }
            else if (obj.readyForHarvest.Value)
                status = "ready";
            else if (obj.heldObject.Value != null || obj.MinutesUntilReady > 0)
                status = "processing";
            else
                status = "empty";

            var entry = new Dictionary<string, object?>
            {
                ["type"] = obj.Name,
                // 🆕 2026-09-30：**类型的中文显示名**（`obj.DisplayName`）。
                //    起因（真机）：「本图 箱×5 … 机×96(就绪20): 小桶×53 复制机×18 烘干机×18
                //    **Mini-Fridge×3** 等8种」—— 中英混排，因为调用方那张 `MACHINE_CN` 是**手编名单**、
                //    漏了 Mini-Fridge。📌 通式同 `heldItemDisplay`：**名字问游戏要，别编表**
                //    （名单会烂，本项目栽过：1.6 矿节点 ID、`Jewels Of The Sea`）。
                ["typeDisplay"] = obj.DisplayName,
                ["name"] = obj.Name,
                ["location"] = locationKey,
                // ⚠️ 同名建筑（多间 Cabin）光靠 location 名字**区分不开**——唯一名才是身份
                //    （`FarmHouse&lt;guid&gt;`，反编译 NameOrUniqueName）。下面 building 坐标是
                //    2026-08 的老绕法，两个都留：**坐标给"进门/精确走位"用，唯一名给"按地点过滤"用**
                //    （cabin collect / enum 就是踩了只按 name 过滤，四间小屋的机器被加在一起）。
                ["location_unique"] = loc.NameOrUniqueName,
                ["x"] = (int)pair.Key.X,
                ["y"] = (int)pair.Key.Y,
                ["status"] = status,
                ["minutesLeft"] = obj.MinutesUntilReady
            };

            // 🍵 2026-10-05（补28d）：花盆把**盆里那份作物的真相**也一起报出来 ——
            //    消费侧就不用再靠 `/surroundings` 那一格去猜"这个盆里到底是什么"。
            //    字段名与 `/surroundings` 对齐（`crop` / `cropPhase` / `harvestable`），
            //    取值路径同本文件 7422-7424 行 —— 三处用的都是**游戏自己的对象**，不另立判据。
            if (obj is IndoorPot potInfo && potInfo.hoeDirt?.Value?.crop != null)
            {
                try { entry["crop"] = potInfo.hoeDirt.Value.crop.indexOfHarvest.Value; } catch { }
                try { entry["cropPhase"] = potInfo.hoeDirt.Value.crop.currentPhase.Value; } catch { }
                try { entry["harvestable"] = potInfo.hoeDirt.Value.readyForHarvest(); } catch { }
            }

            if (obj.heldObject.Value != null)
            {
                entry["heldItem"] = obj.heldObject.Value.Name;
                // 🆕 显示名（中文）：`heldItem` 是**内部英文名**，调用方原先得自己凑中文
                //    ⇒ 真机实拍过中英混排的丑行：`翡翠×17、Diamond×1、Iridium Ore×1`。
                //    人看的那份名字由游戏给，别在调用方硬编表。
                entry["heldItemDisplay"] = obj.heldObject.Value.DisplayName;
                entry["heldItemId"] = obj.heldObject.Value.QualifiedItemId;
                entry["heldQuality"] = (obj.heldObject.Value as StardewValley.Object)?.Quality ?? 0;
            }

            // 建筑内部机器：附上建筑坐标+门坐标，供进门/精确定位
            // （多栋同名建筑如 Cabin 按 location 名字区分不开，只能按建筑坐标）。
            if (buildingMap != null && buildingMap.TryGetValue(loc, out var bp))
                entry["building"] = new { x = bp.x, y = bp.y, doorX = bp.doorX, doorY = bp.doorY };

            machines.Add(entry);
        }
    }

    /// <summary>建筑室内 location → (建筑在农场坐标, 门坐标)。门=进建筑用。</summary>
    private static Dictionary<GameLocation, (int x, int y, int doorX, int doorY)> BuildBuildingMap()
    {
        var map = new Dictionary<GameLocation, (int, int, int, int)>();
        var farm = Game1.getFarm();
        if (farm == null) return map;
        foreach (var b in farm.buildings)
        {
            if (b.indoors?.Value is GameLocation il)
            {
                int doorX = b.humanDoor.Value != Point.Zero ? b.tileX.Value + b.humanDoor.X : b.tileX.Value;
                int doorY = b.humanDoor.Value != Point.Zero ? b.tileY.Value + b.humanDoor.Y : b.tileY.Value;
                map[il] = (b.tileX.Value, b.tileY.Value, doorX, doorY);
            }
        }
        return map;
    }

    private object HandleAnimals()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.player.currentLocation;
                var animals = new List<object>();

                IEnumerable<FarmAnimal>? animalList = null;
                if (loc is Farm farm)
                    animalList = farm.animals.Values;
                else if (loc is AnimalHouse ah)
                    animalList = ah.animals.Values;

                if (animalList != null)
                {
                    foreach (var a in animalList)
                    {
                        animals.Add(new
                        {
                            name = a.Name,
                            type = a.type.Value,
                            x = a.TilePoint.X,
                            y = a.TilePoint.Y,
                            wasPetToday = a.wasPet.Value,
                            wasAutoPet = a.wasAutoPet.Value,   // 🖐️ 抚摸机摸过没（`FarmAnimal.cs:113`）；手摸标记是上面那个 `wasPet`
                            friendship = a.friendshipTowardFarmer.Value,
                            happiness = a.happiness.Value,
                            fullness = a.fullness.Value,
                            age = a.age.Value,
                            home = a.home?.indoors.Value?.Name,
                            product = a.currentProduce.Value,
                            productReady = a.currentProduce.Value != null && a.currentProduce.Value != "-1"
                        });
                    }
                }

                // 🆕 2026-09-30：**棚里还没摸的**（按建筑汇总，只报非零的）。
                //    起因（真机）：站 `Farm (40,0)` 时这条回 **0 条**（它只看**当前图**），
                //    而 `/farm_report` 同一时刻是 **24 只待摸**（全在 Deluxe Coop / Deluxe Barn 里）
                //    ⇒ 单子上「摸 还没摸的动物」**整行不出现**（`_pet_can` 只看当前图），
                //      可 `_exec_pet` 本来就会自己走进棚里去摸 —— **判据比执行器窄**。
                //    ⇒ 补一份**汇总**（不是完整列表）：完整列表太肥，会在每次 `intent show` 上白烧 token。
                //  ⚠️ 走 `Utility.ForEachLocation` 而不是 `Game1.locations`：**cabin/barn 的室内是
                //     instanced interior、压根不在 `Game1.locations` 里**（CHANGELOG 80 那条老账）。
                //  ⚠️ lambda **必须恒 `return true`** —— 返回 false 是**中止整个遍历**（同上）。
                var inBuildings = new Dictionary<string, int>();
                try
                {
                    Utility.ForEachLocation(l =>
                    {
                        if (l is AnimalHouse ahh)
                        {
                            int n = 0;
                            foreach (var a in ahh.animals.Values)
                                if (!a.wasPet.Value) n++;
                            if (n > 0)
                            {
                                // ⚠️ 多栋同名（两间 Coop）用**名字**会并成一条 ⇒ 带唯一名
                                var key = string.IsNullOrEmpty(ahh.Name) ? ahh.NameOrUniqueName : ahh.Name;
                                inBuildings[key ?? "?"] = inBuildings.TryGetValue(key ?? "?", out var had)
                                    ? had + n : n;
                            }
                        }
                        return true;
                    });
                }
                catch { }

                tcs.SetResult(new
                {
                    ok = true,
                    location = loc.Name,
                    count = animals.Count,
                    animals,
                    // 🆕 只给**汇总**：`{"Deluxe Coop": 12, "Deluxe Barn": 12}`
                    inBuildings
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /farm_report — 全农场扫描（照抄游戏农场电脑的遍历范围）。
    /// 覆盖：室外 Farm + 所有建筑室内（棚/舍/小屋/温室）+ 独立 location（地窖 Cellar）。
    /// 返回作物聚合计数、动物逐只（带所属建筑）、机器逐台（带类型/位置/状态）。
    /// </summary>
    private object HandleFarmReport()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                // 遍历范围与 `/machines`、`/machine_load` 共用（farm + 建筑室内 + 地窖）
                // （`/machine_collect` 2026-10-03 已删，见路由表那处墓碑）
                var farmLocs = ResolveLocations("");
                var buildingMap = BuildBuildingMap();

                var machines = new List<object>();
                var animals = new List<object>();
                var cropsByLoc = new List<Dictionary<string, object?>>();
                int cTotal = 0, cWatered = 0, cReady = 0;

                foreach (var loc in farmLocs)
                {
                    string locKey = loc.Name;
                    ScanLocationMachines(loc, locKey, machines, buildingMap);
                    ScanLocationCrops(loc, locKey, cropsByLoc, ref cTotal, ref cWatered, ref cReady);
                    foreach (var a in loc.animals.Values)
                    {
                        animals.Add(new
                        {
                            name = a.Name,
                            type = a.type.Value,
                            building = a.home?.indoors.Value?.Name ?? "Farm",
                            x = a.TilePoint.X,
                            y = a.TilePoint.Y,
                            wasPetToday = a.wasPet.Value,
                            wasAutoPet = a.wasAutoPet.Value,   // 🖐️ 抚摸机摸过没（`FarmAnimal.cs:113`）；手摸标记是上面那个 `wasPet`
                            productReady = a.currentProduce.Value != null && a.currentProduce.Value != "-1",
                            product = a.currentProduce.Value
                        });
                    }
                }

                tcs.SetResult(new
                {
                    ok = true,
                    season = Game1.currentSeason,
                    dayOfMonth = Game1.dayOfMonth,
                    year = Game1.year,
                    crops = new { total = cTotal, watered = cWatered, ready = cReady, byLocation = cropsByLoc },
                    animals = new { total = animals.Count, animals },
                    machines = new { total = machines.Count, machines }
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    //  (原 HandleMachineCollect（POST /machine_collect，原子瞬收）**2026-10-03 删除** ——
    //   恒口径：「要么删掉收放兼容之外的所有口，要么…留一个一键快捷收在单子上」；收官选前者。
    //   实现留在 git 历史里（git log -S HandleMachineCollect）；要恢复**先问恒**。)

    /// <summary>
    /// POST /machine_load  { itemId, location?, type?, count? }
    /// 批量往空机器放原料：把背包里匹配的物品设成手持位，再调机器自己的 checkForAction
    /// 让游戏算配方时间（Keg 酒6000/腌菜罐4000/Cask 自动设 daysToMature+agingRate…），
    /// 不手写配方表，副作用（音效/统计）也由游戏处理。
    /// 槽位消耗完自动切下一个有相同物品的槽位；不匹配的机器自动跳过。
    /// </summary>
    private object HandleMachineLoad(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var rawId = GetParam<string>(p, "itemId");
        var location = GetParamOr(p, "location", "");
        var type = GetParamOr(p, "type", "");
        var count = GetParamOr(p, "count", int.MaxValue);

        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;

                // 解析物品：先当 ID，再按名字在背包里找（Name 或中文 DisplayName）
                var qid = ResolveItemId(rawId, farmer);
                if (qid == null)
                {
                    tcs.SetResult(new { ok = false, error = $"找不到物品: {rawId}" });
                    return;
                }
                if (CountItem(farmer, qid) <= 0)
                {
                    tcs.SetResult(new { ok = false, error = $"背包里没有 {rawId}", available = 0 });
                    return;
                }

                var locs = ResolveLocations(location);
                int loaded = 0, emptySeen = 0, rejected = 0, noSlot = 0;

                foreach (var (loc, tile, obj) in EnumerateMachines(locs, type))
                {
                    if (count != int.MaxValue && loaded >= count)
                        break;
                    if (obj.heldObject.Value != null || obj.MinutesUntilReady > 0 || obj.readyForHarvest.Value)
                        continue;   // 只装空机器
                    emptySeen++;

                    int slot = FindItemSlot(farmer, qid);
                    if (slot < 0)
                    {
                        noSlot++;
                        break;      // 原料用完了
                    }
                    farmer.CurrentToolIndex = slot;

                    // ⚠️ checkForAction 要求操作角色和机器同地点（warp 换地点是异步的，
                    // 下个 tick 才生效），所以这里同步把角色挪到机器所在 location + 旁边。
                    RelocateActor(loc, tile);

                    bool acted;
                    try
                    {
                        // 用 /interact 同款路径 loc.checkAction(瓦片) —— 实测这个能触发机器交互；
                        // 直接 obj.checkForAction 会因地点/激活状态不满足而静默失败。
                        acted = loc.checkAction(new Location((int)tile.X, (int)tile.Y), Game1.viewport, farmer);
                    }
                    catch
                    {
                        acted = false;
                    }

                    if (acted && obj.heldObject.Value != null)
                        loaded++;
                    else
                        rejected++;
                }

                tcs.SetResult(new
                {
                    ok = true,
                    loaded,
                    emptySeen,
                    rejected,
                    noSlot,
                    item = rawId,
                    remaining = CountItem(farmer, qid)   // 背包里剩的
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>POST /machine_reqs { type?, x?, y?, location?, item? } —— 这台机器**放料还要什么额外消耗**。
    ///
    /// 用途（2026-10-01 · 恒：「锻造的话，铱锭够/不够/没开饰品精通都检查一下有没有写好」）：
    ///   **铁砧**（`(BC)Anvil`）每次重铸饰品要 **3 铱锭** —— 不够时 `PlaceInMachine` 只弹一句红字、
    ///   东西**放不进去** ⇒ 调用方看到的就是"按了没反应"（09-12 火山晶石那次同一个病：
    ///   报错不说真原因，AI 无从下手）。⇒ 把游戏那把尺子报出来：**要几个 / 有几个 / 够不够**。
    ///
    /// ⚠️ 数量**一律来自游戏内容数据**（`MachineData.AdditionalConsumedItems` + `Items.CountId`），
    ///   不许在这儿写死「3」（换机器/换版本自动跟着变）。
    /// ⚠️ 给了 `item` 就顺手做一次**只问不做**的探针：`Object.PlaceInMachine(..., probe: true, ...)`
    ///   —— 那是游戏自己的原语，**不改任何状态**，只回答"这样放进去成不成"。
    /// ⚠️ 默认只看**当前这张图**（AI 站在机器旁边问它）；给了 `location` 才按 `/machine_load` 那套解析换图。
    /// </summary>
    private object HandleMachineReqs(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var type = GetParamOr(p, "type", "");
        var cx = GetParamOr(p, "x", -1);
        var cy = GetParamOr(p, "y", -1);
        var location = GetParamOr(p, "location", "");
        var itemName = GetParamOr(p, "item", "");

        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                var locs = string.IsNullOrEmpty(location)
                    ? new List<GameLocation> { farmer.currentLocation }
                    : ResolveLocations(location);
                Item? probeItem = null;
                if (!string.IsNullOrEmpty(itemName))
                {
                    probeItem = FindItemByNameOrId(itemName);
                    if (probeItem == null)
                    {
                        tcs.SetResult(new { ok = false, error = $"背包里没有「{itemName}」" });
                        return;
                    }
                }

                var found = new List<object>();
                foreach (var (loc, tile, obj) in EnumerateMachines(locs, type))
                {
                    if (cx >= 0 && (int)tile.X != cx) continue;
                    if (cy >= 0 && (int)tile.Y != cy) continue;
                    var md = obj.GetMachineData();

                    var reqs = new List<object>();
                    bool allEnough = true;
                    var addl = md?.AdditionalConsumedItems;
                    if (addl != null)
                    {
                        foreach (var r in addl)
                        {
                            int have = farmer.Items.CountId(r.ItemId);
                            bool enough = have >= r.RequiredCount;
                            if (!enough) allEnough = false;
                            reqs.Add(new
                            {
                                id = r.ItemId,
                                name = ItemRegistry.GetDataOrErrorItem(r.ItemId).DisplayName,
                                need = r.RequiredCount,
                                have,
                                enough,
                            });
                        }
                    }

                    bool? canPlace = null;
                    if (probeItem != null && md != null)
                    {
                        try { canPlace = obj.PlaceInMachine(md, probeItem, true, farmer, false, false); }
                        catch { canPlace = false; }   // 探针炸了 = 放不进去（**不谎报能放**）
                    }

                    found.Add(new Dictionary<string, object?>
                    {
                        ["type"] = obj.Name,
                        ["typeDisplay"] = obj.DisplayName,
                        ["location"] = loc.Name,
                        ["location_unique"] = loc.NameOrUniqueName,
                        ["x"] = (int)tile.X,
                        ["y"] = (int)tile.Y,
                        ["empty"] = obj.heldObject.Value == null && obj.MinutesUntilReady <= 0
                                    && !obj.readyForHarvest.Value,
                        ["heldItem"] = obj.heldObject.Value?.DisplayName,
                        ["minutesLeft"] = obj.MinutesUntilReady,
                        ["requirements"] = reqs,
                        ["requirementsMet"] = allEnough,
                        ["canPlace"] = canPlace,
                    });
                }
                tcs.SetResult(new { ok = true, count = found.Count, machines = found });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>解析地点参数：指定名字 → 该地点；空 → 全农场（farm + 建筑室内 + 地窖）。</summary>
    private static List<GameLocation> ResolveLocations(string location)
    {
        if (!string.IsNullOrEmpty(location))
        {
            var loc = FindLocationByName(location);
            if (loc == null)
                throw new InvalidOperationException($"找不到地点: {location}");
            return new List<GameLocation> { loc };
        }

        var list = new List<GameLocation>();
        var seen = new HashSet<GameLocation>();
        var farm = Game1.getFarm();
        if (farm != null)
        {
            if (seen.Add(farm)) list.Add(farm);
            foreach (var b in farm.buildings)
            {
                if (b.indoors?.Value is GameLocation indoor && seen.Add(indoor))
                    list.Add(indoor);   // 棚/舍/小屋/温室
            }
        }
        foreach (var loc in Game1.locations)
        {
            if (loc is Cellar && seen.Add(loc))
                list.Add(loc);          // 地窖是独立 location，不在 farm.buildings
        }
        return list;
    }

    /// <summary>
    /// 按名字找地点。⚠️ **同名地点会撞车**——最典型的是农场上的**多间小屋**：它们的
    /// <c>.Name</c> 全是 "Cabin"，唯一身份在 <c>uniqueName</c>（`FarmHouse&lt;guid&gt;`）里
    /// （反编译 Cabin.cs:61 `farmer.homeLocation.Value = base.NameOrUniqueName`）。
    ///
    /// 2026-09-11 真机踩到：`cabin collect` 按 "Cabin" 查到了**别间小屋**，只收到 1 件
    /// （玩家真所在那间有 377 件等着收，第二次收果然 0 件而真屋一台没动）；
    /// `cabin enum` 的"396 台"也是**四间小屋相加**（377+18+1）。
    ///
    /// ⇒ 查找顺序改成：**① 玩家当前所在 → ② 唯一名 → ③ 退回按显示名扫**。
    /// ① 是游戏自己的语义（`Game1.getLocationFromName` 就是先认 currentLocation，
    /// 见 Game1.cs:10240-10247），我们原来的实现把这层丢了、一律先按 Name 扫。
    /// </summary>
    private static GameLocation? FindLocationByName(string name)
    {
        // ① 玩家脚下这间——同名时它最没有歧义
        var cur = Game1.currentLocation;
        if (cur != null
            && (cur.Name.Equals(name, StringComparison.OrdinalIgnoreCase)
                || cur.NameOrUniqueName.Equals(name, StringComparison.OrdinalIgnoreCase)))
            return cur;

        var farm = Game1.getFarm();

        // ② 唯一名（`FarmHouse<guid>` 这种）——同名地点只有它能区分
        foreach (var loc in Game1.locations)
        {
            if (loc.NameOrUniqueName.Equals(name, StringComparison.OrdinalIgnoreCase))
                return loc;
        }
        if (farm != null)
        {
            foreach (var b in farm.buildings)
            {
                if (b.indoors?.Value is GameLocation indoor
                    && indoor.NameOrUniqueName.Equals(name, StringComparison.OrdinalIgnoreCase))
                    return indoor;
            }
        }

        // ③ 退回按显示名扫（老行为，保持兼容）。⚠️ 同名地点只会命中**第一个**——
        //    调用方按地点过滤时请优先传唯一名，别依赖这一步的运气。
        foreach (var loc in Game1.locations)
        {
            if (loc.Name.Equals(name, StringComparison.OrdinalIgnoreCase))
                return loc;
        }
        if (farm != null)
        {
            foreach (var b in farm.buildings)
            {
                if (b.indoors?.Value is GameLocation indoor
                    && indoor.Name.Equals(name, StringComparison.OrdinalIgnoreCase))
                    return indoor;
            }
        }
        return Game1.getLocationFromName(name);
    }

    /// <summary>枚举机器：bigCraftable + 可选类型过滤。供 collect/load 复用。</summary>
    private static IEnumerable<(GameLocation loc, Vector2 tile, StardewValley.Object obj)> EnumerateMachines(
        IEnumerable<GameLocation> locs, string? type)
    {
        foreach (var loc in locs)
        {
            foreach (var pair in loc.objects.Pairs)
            {
                var obj = pair.Value;
                if (!obj.bigCraftable.Value) continue;
                if (!string.IsNullOrEmpty(type) && !obj.Name.Equals(type, StringComparison.OrdinalIgnoreCase))
                    continue;
                yield return (loc, pair.Key, obj);
            }
        }
    }

    /// <summary>解析要装入机器的物品：先当 ItemId，再按名字在背包里找，返回 QualifiedItemId。</summary>
    private static string? ResolveItemId(string rawId, Farmer farmer)
    {
        if (string.IsNullOrWhiteSpace(rawId)) return null;
        var trimmed = rawId.Trim();
        if (trimmed.StartsWith("("))
            return trimmed;
        var tryQ = ItemRegistry.QualifyItemId(trimmed);
        if (tryQ != null)
            return tryQ;
        foreach (var it in farmer.Items)
        {
            if (it == null) continue;
            if (it.Name.Equals(trimmed, StringComparison.OrdinalIgnoreCase)
                || it.DisplayName.Equals(trimmed, StringComparison.OrdinalIgnoreCase))
                return it.QualifiedItemId;
        }
        return null;
    }

    /// <summary>背包里某物品（QualifiedItemId）的总堆叠数。</summary>
    private static int CountItem(Farmer farmer, string qid)
    {
        int total = 0;
        foreach (var it in farmer.Items)
        {
            if (it != null && it.QualifiedItemId == qid)
                total += it.Stack;
        }
        return total;
    }

    /// <summary>找背包里含指定 QualifiedItemId 且有数量的第一个槽位，找不到返回 -1。</summary>
    private static int FindItemSlot(Farmer farmer, string qid)
    {
        for (int i = 0; i < farmer.Items.Count; i++)
        {
            var it = farmer.Items[i];
            if (it != null && it.QualifiedItemId == qid && it.Stack > 0)
                return i;
        }
        return -1;
    }

    /// <summary>
    /// 同步把操作角色挪到指定机器的所在地点 + 旁边格。
    /// 不走 Game1.warpFarmer（那是异步的，下个 tick 才换地点），直接设 currentLocation，
    /// 这样紧随其后的 checkForAction 能通过同地点检查。
    /// </summary>
    private static void RelocateActor(GameLocation loc, Vector2 tile)
    {
        var farmer = Game1.player;
        if (farmer.currentLocation != loc)
        {
            farmer.currentLocation = loc;
        }

        // 机器旁的空白格。skipCenter=true 绝不站到机器本格上
        // （Cask 可踩踏，不然会落到机器身上点不到它）。防 warp 进墙：找不到就不动。
        var walkable = FindWalkableTile(loc, (int)tile.X, (int)tile.Y, skipCenter: true);
        if (walkable != null)
        {
            farmer.Position = new Vector2(walkable.Value.x, walkable.Value.y) * Game1.tileSize;
        }
    }

    /// <summary>
    /// 扫一个地点的 HoeDirt 作物，统计 total/watered/ready，并追加到 byLocation。
    /// 逻辑同 /surroundings 的作物读取（state==1→watered，readyForHarvest→ready）。
    /// </summary>
    private static void ScanLocationCrops(GameLocation loc, string locationKey,
        List<Dictionary<string, object?>> byLocation, ref int total, ref int watered, ref int ready)
    {
        int lTotal = 0, lWatered = 0, lReady = 0;
        foreach (var pair in loc.terrainFeatures.Pairs)
        {
            if (pair.Value is HoeDirt dirt && dirt.crop != null)
            {
                lTotal++;
                if (dirt.state.Value == 1) lWatered++;
                if (dirt.readyForHarvest()) lReady++;
            }
        }
        total += lTotal; watered += lWatered; ready += lReady;
        if (lTotal > 0)
            byLocation.Add(new Dictionary<string, object?>
            {
                ["location"] = locationKey,
                ["total"] = lTotal,
                ["watered"] = lWatered,
                ["ready"] = lReady
            });
    }

    private object HandleScan()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var loc = Game1.currentLocation;
                var actions = new List<object>();
                for (int x = 0; x < loc.Map.Layers[0].LayerWidth; x++)
                {
                    for (int y = 0; y < loc.Map.Layers[0].LayerHeight; y++)
                    {
                        string? action = loc.doesTileHaveProperty(x, y, "Action", "Buildings");
                        if (action != null)
                        {
                            // 🗑️ 2026-10-02：垃圾桶**今天翻过没有** = `Game1.netWorldState.Value.CheckedGarbage`
                            //    （反编译 `GameLocation.CheckGarbage:8383` 就是 `if (!CheckedGarbage.Add(id)) return false`
                            //     ⇒ 这个集合就是"今天已翻过的桶 id"）。判据**由游戏给**，别让消费侧猜：
                            //    单子那行原来只能写"本图有 N 个桶"，说不清"还剩几个没翻"（恒 2026-10-02 记过这笔）。
                            //    非垃圾桶的 Action 瓦片 ⇒ `garbageChecked` 为 `null`（消费侧认 `null` = 不适用）。
                            bool? garbageChecked = null;
                            if (action.StartsWith("Garbage ", StringComparison.OrdinalIgnoreCase))
                            {
                                string gid = action.Substring("Garbage ".Length).Trim();
                                try { garbageChecked = Game1.netWorldState.Value.CheckedGarbage.Contains(gid); }
                                catch { }
                            }
                            actions.Add(new { x, y, action, garbageChecked });
                        }
                    }
                }
                tcs.SetResult(new { ok = true, location = loc.Name, count = actions.Count, actions });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandlePetBowl()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farm = Game1.getFarm();
                if (farm == null)
                {
                    tcs.SetResult(new { ok = false, error = "Not on a farm" });
                    return;
                }

                Point? bowlPos = null;
                string method = "none";
                StardewValley.Buildings.PetBowl? bowlBuilding = null;

                // Method 0 (best, SDV 1.6): Pet Bowl is a Building — 扫 farm.buildings 找 PetBowl 类型
                // ⚠️ 2026-08-16 恒实测：1.6 宠物碗是 PetBowl 建筑（本档 @(53,7) 2x2，门(52,6)），
                //    farm.petBowl 字段/旧 tile 扫描会误报（如 (7,6)）。建筑扫描最准。
                try
                {
                    foreach (var pb in farm.buildings)
                    {
                        if (pb is StardewValley.Buildings.PetBowl pbw)
                        {
                            bowlPos = new Point(pb.tileX.Value, pb.tileY.Value);
                            bowlBuilding = pbw;
                            method = "building:PetBowl";
                            break;
                        }
                    }
                }
                catch { }

                // Method 1: Try to read farm.petBowl field directly (老档/非1.6兜底)
                if (bowlPos == null)
                try
                {
                    var petBowlField = farm.GetType().GetField("petBowl",
                        BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                    if (petBowlField != null && petBowlField.GetValue(farm) is Point pb)
                    {
                        bowlPos = pb;
                        method = "field:petBowl";
                    }
                }
                catch { }

                // Method 2: Scan Buildings layer for pet bowl tile or action
                if (bowlPos == null)
                {
                    var buildingsLayer = farm.Map.GetLayer("Buildings");
                    for (int x = 0; x < buildingsLayer.LayerWidth && bowlPos == null; x++)
                    {
                        for (int y = 0; y < buildingsLayer.LayerHeight && bowlPos == null; y++)
                        {
                            var tile = buildingsLayer.Tiles[x, y];
                            if (tile == null) continue;

                            // Check Action property
                            string? action = farm.doesTileHaveProperty(x, y, "Action", "Buildings");
                            if (action == "PetBowl")
                            {
                                bowlPos = new Point(x, y);
                                method = "action:PetBowl";
                                break;
                            }

                            // Try a broad range of tile indices used by pet bowls
                            int idx = tile.TileIndex;
                            if (idx >= 1930 && idx <= 1960)
                            {
                                bowlPos = new Point(x, y);
                                method = $"tileIndex:{idx}";
                            }
                        }
                    }
                }

                // Method 3: Find the pet NPC and use its position as a hint
                if (bowlPos == null)
                {
                    foreach (var npc in farm.characters)
                    {
                        if (npc is Pet p)
                        {
                            // Pet bowl is typically 1-2 tiles below where the pet stands
                            bowlPos = new Point((int)p.TilePoint.X, (int)p.TilePoint.Y + 1);
                            method = "petPosition";
                            break;
                        }
                    }
                }

                // Method 4: Scan and dump tile indices near the farmhouse for debugging
                if (bowlPos == null)
                {
                    var bldg = farm.Map.GetLayer("Buildings");
                    var house = farm.GetMainFarmHouse();
                    if (house != null)
                    {
                        int hx = house.tileX.Value;
                        int hy = house.tileY.Value;
                        for (int x = Math.Max(0, hx - 10); x < Math.Min(bldg.LayerWidth, hx + 15); x++)
                        {
                            for (int y = Math.Max(0, hy - 10); y < Math.Min(bldg.LayerHeight, hy + 15); y++)
                            {
                                var tile = bldg.Tiles[x, y];
                                if (tile != null)
                                {
                                    int idx = tile.TileIndex;
                                    if ((idx >= 1880 && idx <= 2000) || idx == 2125 || idx == 2126)
                                    {
                                        bowlPos = new Point(x, y);
                                        method = $"tileIndex:{idx}";
                                        break;
                                    }
                                }
                            }
                            if (bowlPos.HasValue) break;
                        }
                    }
                }

                // Method 5: Last resort - dump all tile indices
                if (bowlPos == null)
                {
                    var bldg = farm.Map.GetLayer("Buildings");
                    HashSet<int> indices = new();
                    for (int x = 0; x < bldg.LayerWidth; x++)
                        for (int y = 0; y < bldg.LayerHeight; y++)
                            if (bldg.Tiles[x, y] != null)
                                indices.Add(bldg.Tiles[x, y].TileIndex);
                    tcs.SetResult(new { ok = false, error = "Pet bowl not found",
                        visibleIndices = string.Join(",", indices.OrderBy(i => i)),
                        farmType = farm.Name ?? "Farm" });
                    return;
                }

                if (bowlPos.HasValue)
                {
                    // Also check if there's a pet in the farm
                    NPC? pet = null;
                    foreach (var npc in farm.characters)
                    {
                        if (npc is Pet petNpc)
                        {
                            pet = petNpc;
                            break;
                        }
                    }

                    // Check if the bowl has been watered today
                    bool bowlWatered = false;
                    string waterCheckMethod = "unknown";
                    // ⚠️ 2026-08-16 1.6：宠物碗是 PetBowl 建筑，watered 在 building.watered (NetBool)
                    if (bowlBuilding != null)
                    {
                        try { bowlWatered = bowlBuilding.watered.Value; waterCheckMethod = "building.watered"; }
                        catch { }
                    }
                    if (waterCheckMethod == "unknown")
                    try
                    {
                        // Try direct field access (works in most Stardew versions)
                        var field = farm.GetType().GetField("petBowlWatered",
                            BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                        if (field != null)
                        {
                            bowlWatered = (bool)(field.GetValue(farm) ?? false);
                            waterCheckMethod = "field";
                        }
                    }
                    catch { /* field access failed, try another way */ }

                    if (waterCheckMethod == "unknown")
                    {
                        // Fallback: check if the bowl tile has a "Watered" property
                        try
                        {
                            foreach (var npc in farm.characters)
                            {
                                if (npc is Pet petNpc)
                                {
                                    // Pet's "wasPetToday" or similar could indicate bowl watered
                                    var petField = petNpc.GetType().GetField("wasPetToday",
                                        BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                                    if (petField != null)
                                    {
                                        bowlWatered = false; // couldn't determine, assume false
                                        waterCheckMethod = "unknown";
                                    }
                                    break;
                                }
                            }
                        }
                        catch { }
                    }

                    // 🍽️ 2026-10-02：**把所有碗都列出来**（恒拍板口径：一个档可能有好几个碗 ——
                    //    本档 4 个：农舍旁 (53,7) + 三间小屋旁 (34,26)(36,26)(38,26)）。
                    //    旧版只报"扫到的第一个" ⇒ 消费侧想说"哪碗满了跳过哪碗"就无从说起
                    //    （`_water_pet_bowls` 里那段注释记着这笔账）。
                    //    ⚠️ 1.6 里碗是 `PetBowl` 建筑（`watered` 挂在建筑上）；这里逐个读它的 watered。
                    var allBowls = new List<object>();
                    try
                    {
                        foreach (var b in farm.buildings)
                        {
                            if (b is StardewValley.Buildings.PetBowl pb2)
                            {
                                bool w = false;
                                try { w = pb2.watered.Value; } catch { }
                                allBowls.Add(new
                                {
                                    x = pb2.tileX.Value, y = pb2.tileY.Value, watered = w,
                                    doorX = pb2.tileX.Value + pb2.humanDoor.X,
                                    doorY = pb2.tileY.Value + pb2.humanDoor.Y
                                });
                            }
                        }
                    }
                    catch { }

                    tcs.SetResult(new
                    {
                        ok = true,
                        bowl = new { x = bowlPos.Value.X, y = bowlPos.Value.Y },
                        // ⚠️ 2026-08-16 门坐标 = 浇水站位参考（本档碗(53,7)，门(52,6)，站门+1朝右浇）
                        door = bowlBuilding != null
                            ? new { x = bowlBuilding.tileX.Value + bowlBuilding.humanDoor.X,
                                    y = bowlBuilding.tileY.Value + bowlBuilding.humanDoor.Y }
                            : (object)new { x = bowlPos.Value.X, y = bowlPos.Value.Y },
                        bowlWatered,
                        // 🍽️ 全部碗（含 `watered`）——老消费侧读上面的单个字段，照样能用
                        bowls = allBowls,
                        bowlsTotal = allBowls.Count,
                        method,
                        pet = pet != null ? new { name = pet.Name, x = (int)pet.TilePoint.X, y = (int)pet.TilePoint.Y } : null
                    });
                }
                else
                {
                    // Fallback: check known farm type coordinates
                    tcs.SetResult(new { ok = false, error = "Pet bowl not found on map", farmType = farm.Name });
                }
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    // ⛔ **`HandlePetAll()`（`/petall`）与 `HandleWaterBowl()`（`/waterbowl`）2026-10-03 删除。**
    //
    //   判据不是"拟人不拟人"，是**这两条连"做了那件事"都不是**：
    //     · `HandlePetAll` 遍历 `Game1.getFarm().buildings` 里每个 `AnimalHouse` 的 `animals`
    //       （反编译读法：`building.indoors.Value is AnimalHouse`）+ `farm.characters` 里的 `Pet`，
    //       然后**反射把 `wasPet/wasPetToday/petted` 字段直接置 true**（或调 `pet()`/`checkAction`）
    //       ⇒ 玩家在 FarmHouse（甚至矿洞）里，全农场动物当天就算"摸过了"。
    //       2026-10-03 真机现场：恒人在 FarmHouse，`GET /petall` 回 `petted:4`（砂糖/绿豆/葡萄/龙眼）。
    //     · `HandleWaterBowl` 靠**猜字段名**（`petBowlWatered` 等 7 个）改农场级 bool，真机当场
    //       `ok:false Could not water bowl` —— 它连"假装成功"都做不到。
    //   两条都**零调用点**（`api.petall()` / `api.waterbowl()` 在 `scripts/stardew_api.py` 里
    //   只有定义、全 repo 无调用）⇒ 删除对任何活路零影响。
    //
    //   AI 的拟人路（有调用点、真机验过）是：`pet_walk.py` / `_pet_animals_in_building`
    //   （走过去 → 面朝 → interact 摸）与 `_pet_pets_natural`（walk_to + 邻格判定 + interact），
    //   喂水是 `pet_water` / `_water_pet_bowls`（走到碗位朝右浇）。**要恢复先问恒。**


    // ═══════════════════════════════════════════════════════════════
    //  🏗️ 建筑/干草/精通（2026-08-06 新增）
    // ═══════════════════════════════════════════════════════════════

    /// <summary>
    /// GET /silo — 筒仓干草检测。
    /// 返回筒仓数、已存干草、容量、空余。（每个筒仓容量 240）
    /// </summary>
    private object HandleSilo()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farm = Game1.getFarm();
                int silos = farm.buildings.Count(b => b.buildingType.Value.Contains("Silo"));
                int hay = farm.piecesOfHay.Value;
                int capacity = silos * 240;
                tcs.SetResult(new
                {
                    ok = true,
                    silos,
                    hay,
                    capacity,
                    room = Math.Max(0, capacity - hay),
                    full = silos > 0 && hay >= capacity,
                    noSilo = silos == 0
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /buffs — 当前生效的 buff 列表（右上角那些，含祝福/食物效果），含剩余毫秒。
    /// 吃东西逻辑靠它：知道 buff 还剩多久，快过期就补吃。
    ///
    /// 🔴 2026-10-03 **治本**（恒「记住这一项等会儿治本」）。老版是**反射摸黑 + 一大堆诊断**：
    ///    先扒 `Game1.buffsDisplay` 上叫 `buffs`/`Buff` 的字段——那是
    ///    `Dictionary<ClickableTextureComponent, Buff>`（`BuffsDisplay.cs:30`）即**显示层的图标表**，
    ///    **按图标组件做键** ⇒ 同一个 buff 能有**多条**（真机实测到两条同 id 的 `food`，
    ///    毫秒数一模一样），而且只有"要画图标的"才在里面；摸不到才退到 BuffManager，还靠**猜方法名**
    ///    （`GetAppliedBuffs`/`GetBuffs`——1.6 里两个都不存在）。
    /// ⇒ 现在直读**权威表** `Game1.player.buffs.AppliedBuffs`：
    ///    `IDictionary<string, Buff>`，**键 = buff id**（`BuffManager.Apply` 先 `Remove(buff.id)` 再放
    ///    ⇒ 天然唯一）、含**全部**生效 buff（不管有没有图标）。
    ///    ⚠️ 数值口径与显示层一致（`BuffsDisplay.GetSortedBuffs()` 就是从 `AppliedBuffs.Values` 灌的，
    ///    连 Buff 对象都是同一个引用）——**差的只是容器**，见 `EnumerateBuffs` 那段。
    ///    🗑️ 顺手删掉那段"列出所有集合字段找祝福存哪"的 `diagnostic`：它要查的问题已经查清，
    ///    没有消费方（`grep diagnostic scripts/*.py` 零命中），留着只是每次回包多几百字节。
    /// </summary>
    private object HandleBuffs()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var list = new List<object>();
                var applied = Game1.player?.buffs?.AppliedBuffs;   // public readonly 字段，不用反射
                if (applied != null)
                {
                    foreach (var b in applied.Values)
                    {
                        if (b == null) continue;
                        list.Add(new
                        {
                            id = b.id ?? "",
                            source = b.source ?? "",
                            displaySource = b.displaySource ?? "",
                            displayName = b.displayName ?? "",
                            visible = b.visible,
                            msRemaining = b.millisecondsDuration,
                            totalMs = b.totalMillisecondsDuration,
                            seconds = b.millisecondsDuration / 1000
                        });
                    }
                }
                tcs.SetResult(new { ok = true, count = list.Count, buffs = list });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /mastery — 精通状态（SDV 1.6）。
    ///
    /// ⚠️ 2026-09-16 重写：旧版**反射 `Farmer` 上名字含 "Mastery" 的字段/属性** —— 真机实测回
    ///   `{"ok":true,"fields":[],"props":[]}`，**这个端点从上线起就是死的**，`check mastery` 跟着一起空。
    ///   根因（反编译实锤）：精通经验根本不在 `Farmer` 上，而在 `Game1.stats` 这个 **string-keyed** 容器：
    ///     · `Game1.stats.Increment("MasteryExp", …)`                 （Farmer.cs:3041）
    ///     · `Game1.stats.Get("masteryLevelsSpent")`                  （MasteryTrackerMenu.cs:177）
    ///     · `Game1.player.stats.Get($"mastery_{i}")`   ← 逐技能"这块碑领没领"（StatKeys.cs:186）
    ///   ⇒ 按**字段名**去反射找 string-keyed 的条目，必然一个都找不到。
    ///
    /// ⚠️ 精通**各人各的，没有共享点数池**：`Game1.stats => player.stats`（Game1.cs:1671），而
    ///   `Game1.player` 是**本进程玩家**（Game1.cs:1250）⇒ 联机下读到的是自己那份。AI 领取不会吃掉房主的等级。
    ///
    /// 等级/阈值一律**问游戏**（`MasteryTrackerMenu.getCurrentMasteryLevel` / `getMasteryExpNeededForLevel`），
    /// 不另抄一份阈值表。技能标题走本地化字符串 `Strings\1_6_Strings:{i}_Mastery`——
    /// 正是菜单 `draw()` 渲染标题用的那一个。
    /// </summary>
    private object HandleMastery()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                // 顺序来自游戏自己：GameLocation.cs 的 `case "MasteryCave_{X}"` → `new MasteryTrackerMenu(i)`
                //   0=Farming 1=Fishing 2=Foraging 3=Mining 4=Combat
                string[] skills = { "farming", "fishing", "foraging", "mining", "combat" };

                int exp = (int)Game1.stats.Get("MasteryExp");
                int level = MasteryTrackerMenu.getCurrentMasteryLevel();
                int spent = (int)Game1.stats.Get("masteryLevelsSpent");
                int unspent = level - spent;
                // -1 = 已满级（游戏 getMasteryExpNeededForLevel(6+) 返回 int.MaxValue，别原样吐出去吓人）
                int nextNeed = level >= 5 ? -1 : MasteryTrackerMenu.getMasteryExpNeededForLevel(level + 1);

                // 🎓 2026-09-16 恒：「精通那个经验条…是有数字进度的 xxx/xxx」——游戏画的确实是**本级内**进度，
                //    不是总量。反编译 `MasteryTrackerMenu.drawBar`（第 509 行）原文：
                //        text = (exp − getMasteryExpNeededForLevel(level))
                //             + "/" + (getMasteryExpNeededForLevel(level+1) − getMasteryExpNeededForLevel(level))
                //    条长也按这个比例（num2/num3）。所以照抄游戏的两个数给 Python，
                //    **别让 Python 自己拿总量去 ratio**——那会显示成 74365/100000，跟游戏对不上。
                //    满级(level>=5)时游戏**不画文字**、条拉满 ⇒ 这里给 -1 让 Python 照办。
                int levelBase = level >= 5 ? -1 : MasteryTrackerMenu.getMasteryExpNeededForLevel(level);
                int expThisLevel = levelBase < 0 ? -1 : exp - levelBase;
                int expThisLevelNeed = (levelBase < 0 || nextNeed < 0) ? -1 : nextNeed - levelBase;

                var plaques = new List<object>();
                for (int i = 0; i < skills.Length; i++)
                {
                    bool claimed = false;
                    try { claimed = Game1.player.stats.Get($"mastery_{i}") != 0; } catch { }
                    string cn = "";
                    try { cn = Game1.content.LoadString($"Strings\\1_6_Strings:{i}_Mastery"); } catch { }
                    plaques.Add(new { index = i, skill = skills[i], cn, claimed });
                }

                tcs.SetResult(new
                {
                    ok = true,
                    who = Game1.player?.Name ?? "",
                    exp,
                    level,
                    expForNext = nextNeed,
                    // 🎓 游戏经验条上真正显示的那两个数（本级内 / 本级总需；满级为 -1）
                    expThisLevel,
                    expThisLevelNeed,
                    levelsSpent = spent,
                    unspent,
                    canClaim = unspent > 0,
                    allPlaques = MasteryTrackerMenu.hasCompletedAllMasteryPlaques(),
                    plaques
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /special_items
    /// 钱包特殊物品列表（Game1.player.specialItems / NetStringList）。
    /// 1.6 精通（mastery_farming/mining/combat/foraging/fishing）、小镇钥匙(TownKey)、
    /// 头骨/生锈钥匙等都在这里——与 mailReceived flag 是两个独立钱包源。
    /// has 子对象预解析成 bool，方便 Python 直接查"是否已领取某项"。
    /// ⚠️ specialItems 是 Net 类型，必须主线程读（同 /surroundings 主线程化教训）。
    /// </summary>
    private object HandleSpecialItems()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                var items = (farmer.specialItems?.ToList()) ?? new List<string>();
                var has = new Dictionary<string, bool>
                {
                    ["mastery_farming"] = items.Contains("mastery_farming"),
                    ["mastery_mining"] = items.Contains("mastery_mining"),
                    ["mastery_combat"] = items.Contains("mastery_combat"),
                    ["mastery_foraging"] = items.Contains("mastery_foraging"),
                    ["mastery_fishing"] = items.Contains("mastery_fishing"),
                    ["TownKey"] = items.Contains("TownKey"),
                };
                tcs.SetResult(new { ok = true, specialItems = items, has });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /achievement_probe — 成就探测（只读，2026-08-23 恒）。
    /// 反射 dump Game1.player.stats 上所有含 Achiev 的字段（来自存档 XML：&lt;achievements&gt;&lt;int&gt;ID&lt;/int&gt;...）。
    /// 确认 SDV 1.6 成就的确切存储/类型后再决定正式接入。
    /// </summary>
    private object HandleAchievementProbe()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                // 成就点在 Game1.player.achievements（NetIntHashSet，反编译 Farmer:243 确认）
                var achv = farmer?.achievements;
                var list = new List<object>();
                if (achv != null)
                {
                    foreach (var a in achv)
                    {
                        string name = "";
                        try
                        {
                            // Game1.achievements 是 Dictionary<int,string> "名^描述"（反编译 Game1:820）
                            if (Game1.achievements != null && Game1.achievements.TryGetValue(a, out var raw))
                                name = raw.Split('^')[0];
                        }
                        catch { }
                        list.Add(new { id = a, name });
                    }
                }
                tcs.SetResult(new
                {
                    ok = true,
                    field = "player.achievements(NetIntHashSet)",
                    count = list.Count,
                    achievements = list,
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private static object? UnwrapNetValue(object? v)
    {
        if (v == null) return null;
        var tn = v.GetType().Name;
        if (tn.StartsWith("NetInt") || tn.StartsWith("NetString") || tn.StartsWith("NetBool"))
        {
            try { return v.GetType().GetProperty("Value")?.GetValue(v); } catch { }
        }
        if (v is System.Collections.IEnumerable en and not string)
        {
            var items = new List<string>();
            try
            {
                foreach (var it in en) items.Add(it?.ToString() ?? "?");
            }
            catch { }
            if (items.Count > 0) return "[" + string.Join(", ", items) + "]";
        }
        return v;
    }

    // 🗑️ HandleMasteryClaim（POST /mastery_claim）已于 2026-09-16 删除。
    //    它**什么也不领**却回 `ok:true`（body 只是反射列一串候选方法名 + 一个永远读不到的 MasteryExp），
    //    是个纯粹的期望陷阱；且 stardew_api.mastery_claim() 包装也无人调用（无任何 MCP 工具指向它）。
    //    真正的领取路径是**拟人**的：走到碑前 `interact` 开 MasteryTrackerMenu（GameLocation.cs:8748
    //    `MasteryCave_{X}` → `new MasteryTrackerMenu(i)`）→ `menu read` 看奖励 → `menu click(button=mainButton)`
    //    点游戏自己的领取按钮（MasteryTrackerMenu.receiveLeftClick → claimReward）。

    /// <summary>
    /// GET /carpenter — 木匠商店建筑清单（只读）。
    /// 从 Game1.buildingData 列所有建筑：价格 + 材料 + 尺寸 + 是否买得起。
    /// 1.6 建筑系统是数据驱动的（无 BluePrint 类），建造写操作暂不做（防误扣资源）。
    /// </summary>
    private object HandleCarpenter()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var farmer = Game1.player;
                var buildings = new List<object>();
                int affordable = 0;
                foreach (var kv in Game1.buildingData)
                {
                    var d = kv.Value;
                    if (d == null) continue;
                    var mats = new List<object>();
                    bool hasMats = true;
                    if (d.BuildMaterials != null)
                    {
                        foreach (var m in d.BuildMaterials)
                        {
                            mats.Add(new { id = m.ItemId, amount = m.Amount });
                            var it = StardewValley.ItemRegistry.GetDataOrErrorItem(m.ItemId);
                            hasMats &= farmer.getItemCount(it.QualifiedItemId) >= m.Amount;
                        }
                    }
                    var cost = d.BuildCost;
                    bool affordableThis = farmer.Money >= cost && hasMats;
                    if (affordableThis) affordable++;
                    buildings.Add(new
                    {
                        name = kv.Key,
                        cost,
                        size = d.Size,
                        materials = mats,
                        affordable = affordableThis
                    });
                }
                tcs.SetResult(new { ok = true, count = buildings.Count, affordable, buildings });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /ladder
    /// 检测当前矿洞的梯子和竖井位置。
    /// 直接读 MineShaft.netTileBeneathLadder 字段（SDV 1.6 实测可用）。
    /// </summary>
    private object HandleLadder()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var loc = Game1.player?.currentLocation;
        if (loc == null)
            return new { ok = false, error = "No location" };

        var locName = loc.Name;
        if (locName == null || !locName.StartsWith("UndergroundMine"))
            return new { ok = false, error = "Not in a mine", location = locName };

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                int level = -1;
                try { level = Convert.ToInt32(locName.Replace("UndergroundMine", "")); }
                catch { }

                Vector2? downLadder = null;
                Vector2? shaftPos = null;
                bool spawned = false;
                Vector2 entrancePos = new(-1, -1);

                var type = loc.GetType();
                var flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;

                // ── 1. 读 ladderHasSpawned ──
                try
                {
                    var f = type.GetField("ladderHasSpawned", flags);
                    if (f != null)
                        spawned = Convert.ToBoolean(f.GetValue(loc));
                }
                catch { }

                // ── 2. 读 netTileBeneathLadder（入口梯子位置） ──
                try
                {
                    var f = type.GetField("netTileBeneathLadder", flags);
                    if (f != null)
                    {
                        var val = f.GetValue(loc);
                        if (val != null)
                        {
                            var vt = val.GetType();
                            var xp = vt.GetProperty("X") ?? vt.GetProperty("x");
                            var yp = vt.GetProperty("Y") ?? vt.GetProperty("y");
                            if (xp != null && yp != null)
                                entrancePos = new Vector2(
                                    Convert.ToSingle(xp.GetValue(val)),
                                    Convert.ToSingle(yp.GetValue(val)));
                        }
                    }
                }
                catch { }

                // ── 3. 扫 Buildings 图层找所有 tile index 173（梯子） ──
                // 入口梯子 + 下层梯子都是 173，要排除入口找到下层
                try
                {
                    var buildings = loc.Map?.GetLayer("Buildings");
                    if (buildings != null)
                    {
                        for (int x = 0; x < buildings.LayerWidth; x++)
                        {
                            for (int y = 0; y < buildings.LayerHeight; y++)
                            {
                                var tile = buildings.Tiles[x, y];
                                if (tile == null) continue;
                                var pos = new Vector2(x, y);

                                if (tile.TileIndex == 173)
                                {
                                    // 不是入口位置的 173 = 下楼梯子。
                                    // 去掉 spawned 限制：打飞蛇/敲石头爆出的梯子，ladderHasSpawned 字段可能没同步，
                                    // 但 Buildings 图层已经有 173——只要非入口就该检测到。
                                    if (pos != entrancePos && downLadder == null)
                                        downLadder = pos;
                                }
                                else if (tile.TileIndex == 174)
                                {
                                    if (shaftPos == null)
                                        shaftPos = pos;
                                }
                            }
                        }
                    }
                }
                catch { }

                // ── 如果 spawned 但没找到非入口 173，可能是 SDV 1.6 不同 tile index ──
                // 回退：直接返回所有非入口位置的 173/174
                if (downLadder == null && spawned)
                {
                    try
                    {
                        var buildings = loc.Map?.GetLayer("Buildings");
                        if (buildings != null)
                        {
                            for (int x = 0; x < buildings.LayerWidth; x++)
                            {
                                for (int y = 0; y < buildings.LayerHeight; y++)
                                {
                                    var tile = buildings.Tiles[x, y];
                                    if (tile == null) continue;
                                    var pos = new Vector2(x, y);
                                    if (pos == entrancePos) continue;
                                    if ((tile.TileIndex == 173 || tile.TileIndex == 1375 || tile.TileIndex == 1376) && downLadder == null)
                                        downLadder = pos;
                                    else if ((tile.TileIndex == 174 || tile.TileIndex == 1381 || tile.TileIndex == 1382) && shaftPos == null)
                                        shaftPos = pos;
                                }
                            }
                        }
                    }
                    catch { }
                }

                tcs.SetResult(new
                {
                    ok = true,
                    location = locName,
                    level,
                    ladderSpawned = spawned,
                    entrance = new { x = (int)entrancePos.X, y = (int)entrancePos.Y },
                    ladder = downLadder != null ? new { x = (int)downLadder.Value.X, y = (int)downLadder.Value.Y } : null,
                    shaft = shaftPos != null ? new { x = (int)shaftPos.Value.X, y = (int)shaftPos.Value.Y } : null,
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /bombs
    /// Returns bombs currently sitting un-exploded on the ground (as TemporaryAnimatedSprite
    /// in currentLocation.temporarySprites with bombRadius &gt; 0).
    /// 🔥 反编译：放炸弹时 placementAction 塞一个 TemporaryAnimatedSprite(ParentSheetIndex=286/287/288)，
    /// currentParentTileIndex 即炸弹 object id（樱桃/黑/超级），position/64 即瓦片，爆炸后 endFunction 移除→自动清空。
    /// 用于炸矿防重叠：AI 规划下一个落点可先看这地上哪些格已有真炸弹，避开其爆炸区。
    /// </summary>
    private object HandleBombs()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var loc = Game1.player?.currentLocation;
        if (loc == null)
            return new { ok = false, error = "No location" };

        // 读 temporarySprites 也必须主线程（同 /surroundings 的地图状态访问限制）
        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var bombs = new List<object>();
                foreach (var s in loc.temporarySprites)
                {
                    if (s == null || s.bombRadius <= 0)
                        continue;   // 只认真炸弹（bombRadius 只在炸弹构造时被设为 3/5/7）
                    int x = (int)(s.position.X / 64f);
                    int y = (int)(s.position.Y / 64f);
                    // currentParentTileIndex=炸弹 object id：286=樱桃 287=黑 288=超级
                    string? bt = s.currentParentTileIndex switch
                    {
                        286 => "Cherry Bomb",
                        288 => "Mega Bomb",
                        _ => "Bomb"
                    };
                    bombs.Add(new Dictionary<string, object?>
                    {
                        ["x"] = x, ["y"] = y, ["bomb_type"] = bt,
                        ["bomb_radius"] = s.bombRadius, ["tile"] = $"{x},{y}"
                    });
                }
                tcs.SetResult(new { ok = true, location = loc.Name, bombs });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /mine_debug
    /// 调试用：dump MineShaft 的所有字段和当前值，找梯子字段。
    /// </summary>
    private object HandleMineDebug()
    {
        if (!Context.IsWorldReady)
            return new { ok = false, error = "World not ready" };

        var loc = Game1.player?.currentLocation;
        if (loc == null)
            return new { ok = false, error = "No location" };

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var type = loc.GetType();
                var fields = type.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                var fieldInfos = new List<object>();

                foreach (var f in fields)
                {
                    try
                    {
                        var val = f.GetValue(loc);
                        string valStr = val?.ToString() ?? "null";
                        if (val is Vector2 v)
                            valStr = $"Vector2({v.X},{v.Y})";
                        else if (val is Point pt)
                            valStr = $"Point({pt.X},{pt.Y})";
                        else if (val is System.Collections.IDictionary dict)
                            valStr = $"Dict[{dict.Count}]";

                        // Truncate long values
                        if (valStr.Length > 80)
                            valStr = valStr[..80] + "...";

                        fieldInfos.Add(new
                        {
                            name = f.Name,
                            type = f.FieldType.Name,
                            value = valStr
                        });
                    }
                    catch { }
                }

                // Sort: ladder/shaft related fields first
                fieldInfos.Sort((a, b) =>
                {
                    var an = (string)((dynamic)a).name;
                    var bn = (string)((dynamic)b).name;
                    bool aRelevant = an.IndexOf("ladder", StringComparison.OrdinalIgnoreCase) >= 0
                                    || an.IndexOf("shaft", StringComparison.OrdinalIgnoreCase) >= 0
                                    || an.IndexOf("mine", StringComparison.OrdinalIgnoreCase) >= 0
                                    || an.IndexOf("hole", StringComparison.OrdinalIgnoreCase) >= 0;
                    bool bRelevant = bn.IndexOf("ladder", StringComparison.OrdinalIgnoreCase) >= 0
                                    || bn.IndexOf("shaft", StringComparison.OrdinalIgnoreCase) >= 0
                                    || bn.IndexOf("mine", StringComparison.OrdinalIgnoreCase) >= 0
                                    || bn.IndexOf("hole", StringComparison.OrdinalIgnoreCase) >= 0;
                    if (aRelevant != bRelevant) return aRelevant ? -1 : 1;
                    return string.Compare(an, bn);
                });

                tcs.SetResult(new
                {
                    ok = true,
                    location = loc.Name,
                    typeName = type.FullName,
                    fieldCount = fields.Length,
                    fields = fieldInfos,
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /mine/elevator
    /// 读鹈鹕镇矿井电梯当前可达楼层（动态起始层用，2026-08-22）。
    /// 接齐先生"深处的危险"会重置电梯 → 楼层为空 → reset=true → 起始=1。
    /// 构造一个 throwaway MineElevatorMenu（SDV 自己的电梯选单，反映真实解锁状态），
    /// 反射其楼层按钮组件 elevators 等 List&lt;ClickableComponent&gt;，把组件 name/label 解析为 int 得楼层列表；
    /// 无论成败都还原 Game1.activeClickableMenu，避免副作用。
    /// </summary>
    private object HandleMineElevator()
    {
        if (!Context.IsWorldReady)
            return new { ok = false, error = "World not ready" };

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            var prevMenu = Game1.activeClickableMenu;
            try
            {
                var floors = new List<int>();
                // ① 若当前已打开电梯选单，直接反射真实呈现的楼层；否则构造一个 throwaway 选单读游戏真相
                IClickableMenu? em = Game1.activeClickableMenu is StardewValley.Menus.MineElevatorMenu m ? m
                                   : new StardewValley.Menus.MineElevatorMenu();
                var flags = System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic
                            | System.Reflection.BindingFlags.Instance;
                for (var t = em.GetType(); t != null; t = t.BaseType)
                {
                    foreach (var f in t.GetFields(flags))
                    {
                        if (!typeof(List<StardewValley.Menus.ClickableComponent>).IsAssignableFrom(f.FieldType))
                            continue;
                        if (f.GetValue(em) is System.Collections.IEnumerable comps)
                        {
                            foreach (var c in comps)
                            {
                                if (c is StardewValley.Menus.ClickableComponent cc && cc != null)
                                {
                                    int n = -1;
                                    if (!string.IsNullOrEmpty(cc.name) && int.TryParse(cc.name, out n))
                                    { }
                                    else if (!string.IsNullOrEmpty(cc.label) && int.TryParse(cc.label, out n))
                                    { }
                                    if (n >= 1 && n <= 120)
                                        floors.Add(n);
                                }
                            }
                        }
                    }
                }
                floors = floors.Distinct().OrderBy(x => x).ToList();
                var reset = floors.Count == 0;
                var maxFloor = reset ? 1 : floors.Max();
                // 诊断：当前所在地下层（MineShaft.netMineLevel 私有，用反射读），看电梯可达层 vs 实际层
                var curLevel = 0;
                try
                {
                    var curLoc = Game1.player?.currentLocation;
                    if (curLoc != null)
                    {
                        var fNet = curLoc.GetType().GetField("netMineLevel", flags);
                        if (fNet?.GetValue(curLoc) is Netcode.NetInt curShaftLevel)
                            curLevel = curShaftLevel.Value;
                    }
                }
                catch { }
                tcs.SetResult(new { ok = true, floors = floors, maxFloor = maxFloor, reset = reset, currentLevel = curLevel });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message, floors = new List<int>(), maxFloor = 1, reset = true, currentLevel = 0 });
            }
            finally
            {
                Game1.activeClickableMenu = prevMenu;   // 还原，避免副作用
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleFestival()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var evt = Game1.CurrentEvent;
                if (evt == null)
                {
                    tcs.SetResult(new { ok = false, error = "No active event" });
                    return;
                }

                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
                var actors = new List<object>();

                // Get event actors
                var actorsField = evt.GetType().GetField("actors", flags);
                if (actorsField?.GetValue(evt) is IEnumerable<NPC> npcList)
                {
                    foreach (var npc in npcList)
                    {
                        actors.Add(new
                        {
                            name = npc.Name,
                            displayName = npc.displayName,
                            x = npc.TilePoint.X,
                            y = npc.TilePoint.Y
                        });
                    }
                }

                // Check festival name
                string festivalName = "";
                var nameField = evt.GetType().GetField("FestivalName", flags) ?? evt.GetType().GetField("festivalName", flags);
                if (nameField != null)
                    festivalName = nameField.GetValue(evt) as string ?? "";
                var nameProp = evt.GetType().GetProperty("FestivalName", flags);
                if (string.IsNullOrEmpty(festivalName) && nameProp != null)
                    festivalName = nameProp.GetValue(evt) as string ?? "";

                // Check isFestival
                bool isFestival = false;
                var isFestMethod = typeof(Game1).GetMethod("isFestival", flags, null, Type.EmptyTypes, null);
                if (isFestMethod != null)
                    isFestival = (bool?)isFestMethod.Invoke(null, null) ?? false;

                // 🥚 寻宝倒计时（festivalTimer 字段：>0 = 限时小游戏进行中，蛋蛋节找蛋/冰钓等用，2026-08-17）
                int festivalTimer = -1;
                var timerField = evt.GetType().GetField("festivalTimer", flags);
                if (timerField != null && timerField.GetValue(evt) is int tf) festivalTimer = tf;
                int festivalScore = Game1.player.festivalScore;

                tcs.SetResult(new
                {
                    ok = true,
                    isFestival,
                    festivalName,
                    location = Game1.currentLocation?.Name,
                    actorCount = actors.Count,
                    festivalTimer,     // 🥚 限时小游戏倒计时(ms)，>0=进行中（2026-08-17）
                    festivalScore,     // 🥚 当前玩家 festivalScore（捡蛋数）
                    actors
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>🎬 事件状态机（2026-09-12 恒）—— 一次**便宜**读取，给 Python 侧判「对话 / 演出 / 静默动画 / 卡住」。
    /// 只读 Game1 与 currentEvent 上的简单字段（**不枚举 NPC/背包**，所以可以低频轮询；
    /// `/festival` 会遍历全部 actor，别拿它当轮询源）。
    /// 判据（反编译实锤，Event.cs:3781/3788/3810/3914/3949）：
    ///   · 有对话框                → 点 confirm（有 responseCount&gt;0 = 选项，必须停下让 AI 选）
    ///   · 无对话 + skippable=true → 演出段（花舞/水母那种"看表演"），可 skip 跳过
    ///   · 无对话 + 无跳过键 + currentCommand 在动 → **静默动画**（走路/表演），等着就行，别瞎按
    ///   · 同条件但指针不动超阈值  → 卡住：按一次 confirm，再不动就该**出声报错**，别盲按 Escape
    /// GET /event_state
    /// </summary>
    private object HandleEventState()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var ev = Game1.currentLocation?.currentEvent;
                var db = Game1.activeClickableMenu as StardewValley.Menus.DialogueBox;

                string? msg = null;
                if (db != null)
                {
                    try { msg = db.getCurrentString(); } catch { }
                }

                // 选项数（>0 = 该停下让 AI 选，别拿 confirm 点掉；同 /menu 的反射读法）
                int respCount = 0;
                try
                {
                    var rf = typeof(StardewValley.Menus.DialogueBox).GetField("responses",
                        System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic |
                        System.Reflection.BindingFlags.Instance);
                    if (rf?.GetValue(db!) is IEnumerable<Response> rs)
                        respCount = rs.Count();
                }
                catch { }

                tcs.SetResult(new
                {
                    ok = true,
                    season = Game1.currentSeason,
                    day = Game1.dayOfMonth,
                    timeOfDay = Game1.timeOfDay,
                    location = Game1.currentLocation?.Name,
                    uniqueName = Game1.currentLocation?.NameOrUniqueName,
                    eventUp = Game1.eventUp,
                    // 🎪 2026-09-13 根因探针（恒：「我还是希望治本」）：怀疑**客户端**这个字段是 null ——
                    //    它**只在时钟跳动的那个 tick 块里赋值**，而节日期间时钟恰好是冻的，两件事撞一起。
                    //    若确为 null，就解释了"首次进节日场地不加载 festival_* 事件"
                    //    （`Game1.warpFarmer` 的节日分支 `locationRequest.Name.Equals(whereIsTodaysFest)` 靠它比对）。
                    //    读法：节日当天正常人在 Temp 里 vs 卡在普通 Town 里，各调一次 `/event_state` 对比。
                    whereIsTodaysFest = Game1.whereIsTodaysFest,
                    eventId = ev?.id,                       // null = 没事件在播
                    isFestival = ev?.isFestival ?? false,
                    skippable = ev?.skippable ?? false,     // 跳过键（游戏按这个画，Event.cs:11438）
                    currentCommand = ev?.CurrentCommand ?? -1,
                    commandCount = ev?.eventCommands?.Length ?? -1,
                    playerControlSequence = ev?.playerControlSequence ?? false,   // 玩家接管段（自由走动）
                    festivalTimer = ev?.festivalTimer ?? -1,                      // >0 = 限时小游戏进行中
                    hasDialogue = db != null,
                    responseCount = respCount,
                    message = msg
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>📜 节日事件数据转储（2026-08-17 恒：反编译蛋蛋位置用）。
    /// 读 Data/Festivals/{season}{day} 的 Dictionary&lt;string,string&gt;（事件key→脚本），
    /// 脚本里含找蛋/摆摊等坐标。GET /festival_data?season=spring&amp;day=13（默认今天）。
    /// ⚠️ 内容直接读游戏已加载的 xnb 数据，省得外部解 LZX。</summary>
    private object HandleFestivalData(HttpListenerContext ctx)
    {
        var q = ctx.Request.QueryString;
        string season = q["season"] ?? Game1.currentSeason;
        string day = q["day"] ?? Game1.dayOfMonth.ToString();
        string asset = $"Data/Festivals/{season}{day}";

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var data = Game1.content.Load<Dictionary<string, string>>(asset);
                var entries = new List<object>();
                foreach (var kv in data)
                {
                    entries.Add(new { key = kv.Key, script = kv.Value });
                }
                tcs.SetResult(new { ok = true, asset, count = entries.Count, entries });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, asset, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>🔓 任意 GameStateQuery 条件求值（2026-09-13 恒「矿车的门禁是献祭。电影院的门禁也是献祭。
    /// 说明门禁根本没做好」）。
    ///
    /// 【为什么要这个口子】游戏判一切门禁都走这一句 —— `GameStateQuery.CheckConditions(条件串, 地图, 玩家)`。
    ///   我们过去是在 `/unlocks` 里**手写第二张 flag 对照表**，于是必然"表和游戏漂"：真机撞到
    ///   `/unlocks` 报 `cinema=false` 而人明明进得去电影院；矿车同理（游戏那边不通就弹
    ///   `MineCart_OutOfOrder`「已损坏」，我们这边一个字都没查）。
    ///   ⇒ 以后**别再补 flag**，直接把条件串丢给游戏判。
    ///
    /// GET /gsq?q=&lt;条件串&gt;（如 `PLAYER_HAS_MAIL Current ccBoilerRoom`）
    ///   · 缺 `q` ⇒ 明确报错（**宁报错别兜底**，恒 2026-09-10 拍板）。
    ///   · 空串 / "TRUE" / "FALSE" 照游戏口径（`CheckConditions` 自己的语义，不另立规矩）。
    ///   · 地图/玩家默认取**当前**（`Game1.currentLocation` / `Game1.player`）—— 门禁多半按"当前玩家"算。</summary>
    private object HandleGsq(HttpListenerContext ctx)
    {
        var q = ctx.Request.QueryString;
        string? query = q["q"];   // 可能真缺参 ⇒ 下面显式报错（不是 null 兜底）
        if (string.IsNullOrWhiteSpace(query))
            return new { ok = false, error = "need q=<GameStateQuery 条件串>（如 PLAYER_HAS_MAIL Current ccBoilerRoom）" };

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                bool result = GameStateQuery.CheckConditions(query, Game1.currentLocation, Game1.player);
                tcs.SetResult(new { ok = true, query, result });
            }
            catch (Exception ex)
            {
                // 条件串语法错 ⇒ 如实报（别把"查不了"伪装成 false，那会静默改行为）
                tcs.SetResult(new { ok = false, query, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>🚂 矿车网络原状 + 逐条可行性（2026-09-13 恒「矿车的门禁是献祭」）。
    ///
    /// 【数据源】`DataLoader.Minecarts(Game1.content)` = 游戏自己的 `Data/Minecarts`。
    /// 【门禁照抄游戏】`GameLocation.ShowMineCartMenu`（反编译 GameLocation.cs:10214）两道：
    ///   ① 网络级 `UnlockCondition` —— 不过就 `drawObjectDialogue(LockedMessage)`（默认
    ///      `Strings\Locations:MineCart_OutOfOrder` = 真机看到的「已损坏」）**直接 return，不开菜单**；
    ///   ② 每站级 `Condition` —— 不过的那一站**根本不进菜单**。
    ///   ⇒ 这两条都在这里照样评估一遍，Python 侧就能**在规划期**知道"这车坐不坐得成"，
    ///     不必再"走过去、开菜单、找不到站名才知道"（真机会把 AI 晾在站台上）。
    ///
    /// GET /minecarts → { ok, networks: [ {id, unlockCondition, lockedMessage, unlocked, destinations:[{id,targetLocation,condition,ok}]} ] }</summary>
    private object HandleMinecarts()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var nets = DataLoader.Minecarts(Game1.content);
                var list = new List<object>();
                foreach (var kv in nets)
                {
                    var n = kv.Value;
                    bool unlocked = GameStateQuery.CheckConditions(n.UnlockCondition, Game1.currentLocation, Game1.player);
                    var dests = new List<object>();
                    foreach (var d in (n.Destinations ?? new List<StardewValley.GameData.Minecarts.MinecartDestinationData>()))
                    {
                        bool ok = true;
                        try { ok = GameStateQuery.CheckConditions(d.Condition, Game1.currentLocation, Game1.player); }
                        catch { ok = false; }
                        dests.Add(new { id = d.Id, targetLocation = d.TargetLocation, condition = d.Condition, ok });
                    }
                    list.Add(new
                    {
                        id = kv.Key,
                        unlockCondition = n.UnlockCondition,
                        lockedMessage = n.LockedMessage,
                        unlocked,
                        destinations = dests,
                    });
                }
                tcs.SetResult(new { ok = true, count = list.Count, networks = list });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>🥚 扫地图 Paths 图层 TileSheet 以 "fest" 开头的图块 = 蛋蛋坐标（2026-08-17 恒）。
    /// Event.cs 的 eggHunt 处理器就是这样找蛋（festivalProps.Add）。
    /// GET /egg_tiles?map=Town-EggFestival2（map 省略=当前地图）。奇偶年地图不同：Town-EggFestival / Town-EggFestival2。</summary>
    private object HandleEggTiles(HttpListenerContext ctx)
    {
        var q = ctx.Request.QueryString;
        string mapName = q["map"] ?? "";   // 空 = 当前地图

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                xTile.Map map = string.IsNullOrEmpty(mapName)
                    ? Game1.currentLocation.map
                    : Game1.content.Load<xTile.Map>("Maps/" + mapName);
                var layer = map.GetLayer("Paths");
                if (layer == null)
                {
                    tcs.SetResult(new { ok = true, map = mapName, count = 0, tiles = new List<object>() });
                    return;
                }
                var tiles = new List<object>();
                for (int k = 0; k < layer.LayerWidth; k++)
                {
                    for (int l = 0; l < layer.LayerHeight; l++)
                    {
                        var tile = layer.Tiles[k, l];
                        if (tile != null && tile.TileSheet.Id.StartsWith("fest"))
                            tiles.Add(new { x = k, y = l, tileIndex = tile.TileIndex, sheet = tile.TileSheet.Id });
                    }
                }
                tcs.SetResult(new { ok = true, map = string.IsNullOrEmpty(mapName) ? Game1.currentLocation?.Name : mapName, count = tiles.Count, tiles });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleFestivalInteract(HttpListenerContext ctx)
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var body = ReadJson(ctx);
        string targetName = body.ContainsKey("name") ? body["name"].ToString() : "";

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var evt = Game1.CurrentEvent;
                if (evt == null)
                {
                    tcs.SetResult(new { ok = false, error = "No active event" });
                    return;
                }

                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
                var actorsField = evt.GetType().GetField("actors", flags);
                if (actorsField?.GetValue(evt) is not IEnumerable<NPC> npcList)
                {
                    tcs.SetResult(new { ok = false, error = "No actors found" });
                    return;
                }

                NPC? target = null;
                foreach (var npc in npcList)
                {
                    // ⚠️ 2026-08-16 恒：中文名适配——匹配 Name 或 displayName（罗宾→Robin）
                    bool nameHit = string.IsNullOrEmpty(targetName)
                        || npc.Name.Equals(targetName, StringComparison.OrdinalIgnoreCase)
                        || (npc.displayName ?? "").Equals(targetName, StringComparison.OrdinalIgnoreCase)
                        || (npc.displayName ?? "").Contains(targetName, StringComparison.OrdinalIgnoreCase);
                    if (nameHit)
                    {
                        target = npc;
                        break;
                    }
                }

                if (target == null)
                {
                    tcs.SetResult(new { ok = false, error = $"Actor '{targetName}' not found" });
                    return;
                }

                // 🚶 站到 NPC 旁边 + 朝向 —— **必须挑一个真站得住的邻格**
                // ⚠️ 2026-09-13 恒真机抓到的现场：原版死磕 `(x, y+1)`（NPC 正下方）**且直接设 Position、
                //    不做任何可行性检查** ⇒ NPC 站岸边/水边时 **人直接落水里**（画面上"飘着"）。
                //    时间线（恒的截图）：Python 侧 `_stand_near` 已经先挑好站格（**站对了、朝向也对**），
                //    随后 `/interact` 没收到台词（这 NPC 本来就没台词）⇒ 走本兜底端点 ⇒ **被这一行摁进水里**。
                //    ⇒ Python 那半已修，**这里是 C# 那一半**，两边都得修，否则兜底会绕过去。
                var farmer = Game1.player;
                var npcTile = target.TilePoint;
                int[] standDx = { 0, 0, 1, -1 };          // 正下方优先（原行为），再上/右/左
                int[] standDy = { 1, -1, 0, 0 };
                int standX = npcTile.X, standY = npcTile.Y + 1;   // 四邻都站不住才退回原行为
                bool standPicked = false;
                for (int i = 0; i < standDx.Length; i++)
                {
                    int cx = npcTile.X + standDx[i], cy = npcTile.Y + standDy[i];
                    try
                    {
                        if (Game1.currentLocation.isTilePassable(new Vector2(cx, cy)))
                        { standX = cx; standY = cy; standPicked = true; break; }
                    }
                    catch { }
                }
                farmer.Position = new Vector2(standX, standY) * Game1.tileSize;
                // 朝向：站哪边就朝哪边看 NPC（原版恒 faceDirection(0)，只有站正下方时才碰巧对）
                int sdx = standX - npcTile.X, sdy = standY - npcTile.Y;
                farmer.faceDirection(sdy > 0 ? 0 : sdy < 0 ? 2 : (sdx < 0 ? 1 : 3));

                // Try to trigger NPC action via checkAction
                bool triggered = Game1.currentLocation.checkAction(
                    new xTile.Dimensions.Location(target.TilePoint.X, target.TilePoint.Y),
                    Game1.viewport, farmer);

                if (!triggered)
                {
                    // Fallback: try direct NPC click
                    target.checkAction(farmer, Game1.currentLocation);
                    triggered = true;
                }

                tcs.SetResult(new
                {
                    ok = true,
                    target = target.Name,
                    targetTile = new { x = target.TilePoint.X, y = target.TilePoint.Y },
                    playerTile = new { x = farmer.TilePoint.X, y = farmer.TilePoint.Y },
                    // 🚶 站格是真的挑到的，还是四邻全站不住退回的 y+1（退回时**大概率落水里**，留个读数）
                    standPicked,
                    triggered
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    private object HandleFestivalAnswer(HttpListenerContext ctx)
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var body = ReadJson(ctx);
        int answer = GetParamOr(body, "answer", 0);   // 🆕 2026-08-18 修 JsonElement cast 崩（原 Convert.ToInt32）
        string key = body.ContainsKey("key") ? body["key"].ToString() : "";

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var evt = Game1.CurrentEvent;
                if (evt == null)
                {
                    tcs.SetResult(new { ok = false, error = "No active event" });
                    return;
                }

                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;

                // Try answerDialogueQuestion
                var answerMethod = evt.GetType().GetMethod("answerDialogueQuestion", flags);
                if (answerMethod != null)
                {
                    var npc = Game1.currentLocation.isCharacterAtTile(Game1.player.GetGrabTile());
                    // 🆕 2026-08-18：answerDialogueQuestion 期望 responseKey（不是 index），从当前 DialogueBox 取
                    string answerKey = answer.ToString();
                    if (Game1.activeClickableMenu is DialogueBox db2)
                    {
                        var rf2 = typeof(DialogueBox).GetField("responses", flags);
                        var arr2 = rf2?.GetValue(db2) as IEnumerable<Response>;
                        var list2 = arr2?.ToList();
                        if (list2 != null && answer >= 0 && answer < list2.Count) answerKey = list2[answer].responseKey;
                    }
                    answerMethod.Invoke(evt, new object?[] { npc, answerKey });
                    tcs.SetResult(new { ok = true, method = "answerDialogueQuestion", answer, key = answerKey });
                    return;
                }

                // Fallback: try answerDialogue on the event
                var methods = evt.GetType().GetMethods(flags);
                foreach (var m in methods)
                {
                    if (m.Name.Contains("answer", StringComparison.OrdinalIgnoreCase) ||
                        m.Name.Contains("Answer", StringComparison.OrdinalIgnoreCase))
                    {
                        var parms = m.GetParameters();
                        if (parms.Length >= 1)
                        {
                            try
                            {
                                if (parms[0].ParameterType == typeof(int))
                                    m.Invoke(evt, new object[] { answer });
                                else if (parms[0].ParameterType == typeof(string))
                                    m.Invoke(evt, new object[] { answer.ToString() });
                                tcs.SetResult(new { ok = true, method = m.Name, answer });
                                return;
                            }
                            catch { continue; }
                        }
                    }
                }

                // Fallback: use Game1.currentLocation.answerDialogueAction
                var locMethod = Game1.currentLocation.GetType().GetMethod("answerDialogueAction", flags);
                if (locMethod != null)
                {
                    string actionKey = string.IsNullOrEmpty(key) ? $"festival_{answer}" : key;
                    locMethod.Invoke(Game1.currentLocation, new object[] { actionKey, Array.Empty<string>() });
                    tcs.SetResult(new { ok = true, method = "location.answerDialogueAction", key = actionKey });
                    return;
                }

                tcs.SetResult(new { ok = false, error = "No answer method found" });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// POST /dance_invite  ?target=名字
    /// 💃 花舞节邀请玩家跳舞（2026-08-21：direct=true 作弊已退役，正常端口走通）。
    /// 走 team.SendProposal(ProposalType.Dance)：本玩家发提案，对方弹 "AskedToDance" Yes/No 正常接受，
    /// 接受后双方 dancePartner 各自动设好（PendingProposalDialog/回调）。
    /// ⚠️ 本端点只收玩家（邀 NPC 走自然 interact 流程，见 MCP 引导）；dancePartner 须在舞会开始前设好；farmhand 需在花舞节事件中。
    /// </summary>
    private object HandleDanceInvite(HttpListenerContext ctx)
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var p = ReadJson(ctx);
        var target = GetParamOr(p, "target", "");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var inFlowerDance = Game1.CurrentEvent != null && Game1.CurrentEvent.isSpecificFestival("spring24");

                // 🎯 目标解析：先玩家（按名字，默认=另一个在线玩家），再节日 NPC（只提示走自然流程）
                var others = Game1.getOnlineFarmers()
                    .Where(f => f.UniqueMultiplayerID != Game1.player.UniqueMultiplayerID)
                    .ToList();
                Farmer? targetFarmer = null;
                if (!string.IsNullOrEmpty(target))
                    targetFarmer = others.FirstOrDefault(f => f.Name.Equals(target, StringComparison.OrdinalIgnoreCase));

                // 💃 玩家没匹配上 → 试节日 NPC：只提示走自然流程（本端点只收玩家，direct=true 已退役）
                if (targetFarmer == null && !string.IsNullOrEmpty(target) && Game1.CurrentEvent != null)
                {
                    var evt = Game1.CurrentEvent;
                    NPC? targetNpc = evt.getActorByName(target);
                    if (targetNpc == null)
                    {
                        var actorsField = evt.GetType().GetField("actors",
                            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic |
                            System.Reflection.BindingFlags.Instance);
                        if (actorsField?.GetValue(evt) is IEnumerable<NPC> npcList)
                        {
                            targetNpc = npcList.FirstOrDefault(a =>
                                (a.displayName ?? "").Equals(target, StringComparison.OrdinalIgnoreCase) ||
                                (a.displayName ?? "").Contains(target, StringComparison.OrdinalIgnoreCase) ||
                                a.Name.Contains(target, StringComparison.OrdinalIgnoreCase));
                        }
                    }
                    if (targetNpc != null)
                    {
                        tcs.SetResult(new { ok = false, error = $"邀 NPC {targetNpc.Name} 请走自然流程：站 NPC 紧邻格裸 /interact → 弹「什么事？」→ 选「邀请XX作舞伴」（需4心+）。本端点只收玩家" });
                        return;
                    }
                }

                // ⚠️ 指定了名字但没找到 → 明确报错，绝不静默回退到默认玩家（2026-08-20 修：艾米丽没匹配上回退配错成恒）
                if (targetFarmer == null && !string.IsNullOrEmpty(target))
                {
                    tcs.SetResult(new { ok = false, error = $"找不到目标 '{target}'（无此在线玩家，也无此节日 NPC——英文环境请用英文名如 Emily；空 target 才默认配另一个玩家）" });
                    return;
                }
                targetFarmer ??= others.FirstOrDefault();
                if (targetFarmer == null)
                {
                    tcs.SetResult(new { ok = false, error = "目标为空且无其他在线玩家（需要 target 指定目标）" });
                    return;
                }

                // 🥂 走提案系统（对方弹 "AskedToDance" Yes/No 接受；本方弹等待框 PendingProposalDialog，等对方应答自动关）
                Game1.player.team.SendProposal(targetFarmer, ProposalType.Dance);
                string warn2 = inFlowerDance ? "" : "（⚠️ 当前不在花舞节事件中，对方可能拒绝——确认双方已在花舞节地图）";
                tcs.SetResult(new
                {
                    ok = true,
                    action = "proposal_sent",
                    target = targetFarmer.Name,
                    note = $"已发送跳舞邀请给 {targetFarmer.Name}，等对方接受{warn2}"
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /unlocks
    /// 读游戏解锁状态（邮件 flag / 工具等级 / 技能）→ map_go 据此拦截未解锁地点。
    /// 2026-08-14：mail flag 名 best-effort，需游戏重启后实测核对。
    /// </summary>
    private object HandleUnlocks()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var master = Game1.MasterPlayer;
                var mail = master?.mailReceived;

                bool Has(string flag) => mail != null && mail.Contains(flag);

                // ⚠️ 会员卡是 per-player 物品（2026-08-23 恒：7842恒无卡/7843 AI 有卡）——必须读"当前角色"而非 MasterPlayer。
                // /unlocks 恒从 AI 进程(7843)打 → Game1.player = 实际负责走位开赌场的 AI；恒(7842)=另一角色，无卡。
                // 正确判定=Farmer.hasClubCard 属性（反编译 farmer.cs:1332，读自己 mailReceived 的 "HasClubCard" flag，非物理物品、非 "clubCard"）。
                // 其余全局解锁（矿/巴士/下水道等）仍走 Has（读 MasterPlayer=房主权威端），勿混。

                // 钢斧（秘密森林）：Axe UpgradeLevel >= 2
                int axeLevel = 0;
                try
                {
                    if (master?.getToolFromName("Axe") is Tool axe)
                        axeLevel = axe.UpgradeLevel;
                }
                catch { }

                // 精通山洞：全技能 10 级
                bool mastery = false;
                try
                {
                    var p = master ?? Game1.player;
                    if (p != null && p.farmingLevel.Value >= 10 && p.miningLevel.Value >= 10
                        && p.foragingLevel.Value >= 10 && p.fishingLevel.Value >= 10 && p.combatLevel.Value >= 10)
                        mastery = true;
                }
                catch { }

                // 山顶：100% 完美达成（best-effort 反射探 FarmerTeam 里 Perfection 相关属性）
                bool summit = false;
                try
                {
                    var nwsValue = Game1.netWorldState?.Value;
                    if (nwsValue != null)
                    {
                        var flags = System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance;
                        foreach (var prop in nwsValue.GetType().GetProperties(flags)
                                     .Where(p => p.Name.ToLower().Contains("perfection")))
                        {
                            try
                            {
                                var v = prop.GetValue(nwsValue);
                                if (v != null && Convert.ToDouble(v) >= 1.0) { summit = true; break; }
                            }
                            catch { }
                        }
                    }
                }
                catch { }

                // ⚠️ 2026-08-14 校准（用 /unlock_debug 从全解锁旧档实测的真实 flag）：
                //   HasRustyKey / HasSkullKey / HasTownKey / ccMovieTheater / Pam_cc_Bus / ccDoorUnlock
                // 矿洞/铁路按日期（用户拍板：不用 mail flag，直接天数记）
                bool railroadOpen = Game1.year > 1
                    || (Game1.currentSeason == "summer" && Game1.dayOfMonth >= 3)
                    || Game1.currentSeason == "fall" || Game1.currentSeason == "winter";
                bool mineOpen = Game1.year > 1 || Game1.currentSeason != "spring"
                    || (Game1.currentSeason == "spring" && Game1.dayOfMonth >= 5);
                // 鹦鹉特快（姜岛快捷/图腾，2026-08-15 恒：需喂金核桃解锁）
                //   FarmerTeam.parrotUpgradesDone（NetList<int,NetInt>，已完成的升级 index 列表）。
                //   ⚠️ 用 Count+索引器 反射读（NetList 只实现泛型 IEnumerable<T>，is IEnumerable 判空会静默失败）。
                //   parrotUpgradesRaw 输出原始列表，parrotDiag 说明读取状态（供校准）。
                // 鹦鹉特快/岛升级（2026-08-15 恒：需喂金核桃解锁）。
                //   ⚠️ SDV1.6 字段名实测不在 master.team.parrotUpgradesDone（diag=no-field）→
                //   改为自适应：扫 team/netWorldState 里名字含 parrot/upgrade/walnut 的成员，
                //   读第一个 Count>0 的集合（yr3解锁档非空=✅，yr2未解锁档空=🔒）。
                // 鹦鹉平台/岛升级（2026-08-15 实测字段）：SDV1.6 存于
                //   nws.parrotPlatformsUnlocked（NetList<int>，已解锁平台索引）+ 各岛 GameLocation.parrotPlatforms。
                //   ⚠️ 不是 FarmerTeam.parrotUpgradesDone（之前猜错）。
                bool parrotExpress = false;
                // 🆕 2026-09-19 恒：**直接读游戏自己的完成判据**（下面那套反射扫法一直在误报，见下方长注释）
                bool farmObeliskUnlocked = false;      // 姜岛→农场图腾柱
                bool parrotPlatformsDirect = false;    // 岛内鹦鹉特快
                string farmObeliskDiag = "not-read";
                var parrotUpgradesRaw = new List<int>();
                string parrotDiag = "not-read";
                var parrotMembers = new List<string>();
                try
                {
                    var bf = System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                    var nws = Game1.netWorldState?.Value;

                    // 1. 首选 nws.parrotPlatformsUnlocked（规范：已解锁平台列表）
                    if (nws != null)
                    {
                        var f = nws.GetType().GetField("parrotPlatformsUnlocked", bf)
                                ?? nws.GetType().GetField("ParrotPlatformsUnlocked", bf);
                        if (f != null)
                        {
                            var listObj = f.GetValue(nws);
                            if (listObj != null)
                            {
                                int count = 0;
                                try { count = Convert.ToInt32(listObj.GetType().GetProperty("Count")?.GetValue(listObj)); } catch { }
                                parrotMembers.Add($"nws.parrotPlatformsUnlocked={count}");
                                for (int i = 0; i < count; i++)
                                {
                                    object? item = null;
                                    try { item = listObj.GetType().GetProperty("Item")?.GetValue(listObj, new object[] { i }); } catch { }
                                    int v = 0;
                                    if (item is int iint) v = iint;
                                    else
                                    {
                                        try { v = Convert.ToInt32(item); }
                                        catch { try { v = Convert.ToInt32(item?.GetType().GetProperty("Value")?.GetValue(item)); } catch { } }
                                    }
                                    parrotUpgradesRaw.Add(v);
                                }
                                if (parrotUpgradesRaw.Count > 0)
                                    parrotDiag = $"from:nws.parrotPlatformsUnlocked({count})";
                            }
                        }
                    }

                    // 2. 扫各岛 GameLocation 的 parrotPlatforms（补数据，含 IslandSouth 度假村）
                    foreach (var locName in new[] { "IslandWest", "IslandSouth", "IslandNorth", "IslandEast" })
                    {
                        try
                        {
                            var loc = Game1.getLocationFromName(locName);
                            if (loc == null) continue;
                            var f = loc.GetType().GetField("parrotPlatforms", bf)
                                    ?? loc.GetType().GetField("ParrotPlatforms", bf);
                            if (f == null) continue;
                            var listObj = f.GetValue(loc);
                            if (listObj == null) continue;
                            int count = 0;
                            try { count = Convert.ToInt32(listObj.GetType().GetProperty("Count")?.GetValue(listObj)); } catch { }
                            var vals = new List<int>();
                            for (int i = 0; i < count; i++)
                            {
                                object? item = null;
                                try { item = listObj.GetType().GetProperty("Item")?.GetValue(listObj, new object[] { i }); } catch { }
                                int v = 0;
                                if (item is int iint) v = iint;
                                else
                                {
                                    try { v = Convert.ToInt32(item); }
                                    catch { try { v = Convert.ToInt32(item?.GetType().GetProperty("Value")?.GetValue(item)); } catch { } }
                                }
                                vals.Add(v);
                            }
                            parrotMembers.Add($"{locName}.parrotPlatforms={count}:[{string.Join(",", vals)}]");
                            if (parrotUpgradesRaw.Count == 0 && vals.Count > 0)
                            {
                                parrotUpgradesRaw.AddRange(vals);
                                parrotDiag = $"from:{locName}.parrotPlatforms({count})";
                            }
                        }
                        catch { }
                    }

                    // ⚠️⚠️ 2026-09-19 恒：**判定换掉了** —— 上面这套反射扫法**一直在误报**，两处都错：
                    //   ① `nws.ParrotPlatformsUnlocked` 其实是 **NetBool**（反编译 IslandWest.cs:179
                    //      `Game1.netWorldState.Value.ParrotPlatformsUnlocked = true;`），
                    //      而这里拿 `GetProperty("Count")` 当**列表**读 ⇒ 永远 0
                    //      （诊断里就是 `nws.parrotPlatformsUnlocked=0`，首选路径**永远读空**）。
                    //   ② 兜底去扫各岛 `location.parrotPlatforms` —— 那是**度假村/港口平台**，
                    //      跟鹦鹉特快/图腾柱不是一回事；而且它吐的是"**已解锁平台索引**"，
                    //      判据 `Any(v => v > 0)` 把**合法的索引 0** 当成"没解锁"
                    //      （本档 `IslandSouth.parrotPlatforms=1:[0]` ⇒ 误判成 false）。
                    //   ⇒ 恒：「金核桃早全收集了、图腾柱很久很久前就解锁了，却报未解锁。」
                    //   ⇒ 改成读**游戏自己的完成判据**（IslandWest.cs:160-165 那个 ParrotUpgradePerch：
                    //      站位 Point(72,37)、需 20 金核桃、前置邮件 Island_UpgradeHouse_Mailbox）：
                    //        · 姜岛→农场图腾柱 = `IslandWest.farmObelisk`（public readonly NetBool）
                    //        · 岛内鹦鹉特快   = `nws.ParrotPlatformsUnlocked`（**bool**，不是列表）
                    //   上面的反射结果**保留但只当诊断看**（`parrotUpgradesRaw`/`parrotMembers`），
                    //   **不再参与判定** —— 恒：别把诊断当判据。
                    try
                    {
                        var iw = Game1.getLocationFromName("IslandWest") as IslandWest;
                        if (iw != null)
                        {
                            farmObeliskUnlocked = iw.farmObelisk.Value;
                            // ⚠️ 2026-09-19 恒：**成功也要写诊断** —— 原先成功时不更新这个串，
                            //    于是明明读到了 true 却显示 `not-read`，"诊断在骗人"（恒最烦这类）。
                            //    现在能一眼看出：读到了什么、以及有没有靠邮件兜底（`+mail`）。
                            farmObeliskDiag = "IslandWest.farmObelisk=" + farmObeliskUnlocked;
                        }
                        else farmObeliskDiag = "no-IslandWest";
                    }
                    catch (Exception ex) { farmObeliskDiag = "err:" + ex.GetType().Name; }
                    // 🛡️ 邮件兜底：完成时 `addMailForTomorrow("Island_W_Obelisk", sendToEveryone:true)`
                    //    ⇒ 次日进邮件。**跨客户端更稳** —— `farmObelisk` 是**地图上的** NetField，
                    //    farmhand 没进过 IslandWest 可能读不到（"读全局状态≠读地图上的"，CHANGELOG 09-11）。
                    if (!farmObeliskUnlocked && Has("Island_W_Obelisk"))
                    { farmObeliskUnlocked = true; farmObeliskDiag += "+mail"; }
                    try { parrotPlatformsDirect = Game1.netWorldState.Value.ParrotPlatformsUnlocked; }
                    catch (Exception ex) { farmObeliskDiag += "|plat-err:" + ex.GetType().Name; }
                    parrotExpress = farmObeliskUnlocked || parrotPlatformsDirect;
                    parrotDiag = $"direct:farmObelisk={farmObeliskUnlocked}({farmObeliskDiag}),"
                               + $"platforms={parrotPlatformsDirect}|reflection:{parrotDiag}";
                }
                catch (Exception ex) { parrotDiag = "err:" + ex.GetType().Name; }
                var unlocks = new Dictionary<string, object>
                {
                    ["mine"] = new { unlocked = mineOpen, how = "春5日收到信后可进矿洞" },
                    ["bus"] = new { unlocked = Has("Pam_cc_Bus") || Has("ccVault"), how = "修好巴士（社区中心金库/Joja 42,500g）" },
                    ["sewer"] = new { unlocked = Has("HasRustyKey") || Has("OpenedSewer") || Has("CF_Sewer"), how = "博物馆捐60个古物获得生锈钥匙" },
                    ["secretWoods"] = new { unlocked = axeLevel >= 2, how = "升级到钢斧（砍大木桩）" },
                    ["skullCavern"] = new { unlocked = Has("HasSkullKey") || Has("HasUnlockedSkullDoor") || Has("skullCave"), how = "到达矿井底部120层获得头骨钥匙" },
                    ["island"] = new { unlocked = Has("willyBoatFixed"), how = "完成社区中心后找威利修船" },
                    ["railroad"] = new { unlocked = railroadOpen, how = "夏3日地震后开放" },
                    ["casino"] = new { unlocked = (Game1.player?.hasClubCard ?? false), how = "完成神秘的齐任务线获得会员卡" },
                    ["summit"] = new { unlocked = summit, how = "100%完美达成" },
                    ["mastery"] = new { unlocked = mastery, how = "钓鱼/采集/战斗/挖矿/耕种全10级" },
                    ["greenhouse"] = new { unlocked = Has("ccPantry"), how = "完成社区中心储藏室/Joja温室" },
                    ["communityCenter"] = new { unlocked = Has("ccIsComplete") || Has("ccDoorUnlock") || Has("Lewis_cc_Begin"), how = "完成刘易斯任务/献祭" },
                    ["cinema"] = new { unlocked = Has("ccMovieTheater") || Has("abandonedJojaMartAccessible"), how = "完成Joja路线/电影院" },
                    ["witchSwamp"] = new { unlocked = Has("HasDarkTalisman"), how = "完成黑暗护身符任务（法师）" },
                    ["townKey"] = new { unlocked = Has("HasTownKey"), how = "完成小镇钥匙任务（任意时段进居民家）" },
                    ["forestMagic"] = new { unlocked = Has("Lewis_cc_Begin") || Has("ccIntro"), how = "森林魔法（献祭功能解锁）" },
                    // 🆕 2026-09-19 恒：**单列一个 `farmObelisk`** —— 比复用 `parrotExpress` 精确，
                    //    给"姜岛→农场走图腾柱"那条导航用（那个只认这根柱子，跟岛内特快是两码事）。
                    ["farmObelisk"] = new { unlocked = farmObeliskUnlocked,
                        how = "姜岛→农场图腾柱：喂 20 金核桃给 IslandWest(72,37) 的鹦鹉（前置=先修睡觉小屋）" },
                    ["parrotExpress"] = new { unlocked = parrotExpress, how = "喂金核桃给岛上鹦鹉解锁快捷（姜岛→农场图腾/岛内传送）" },
                    // 🌋 火山近路（2026-09-12 恒：「第一次闯关到10层之后来这里踩机关，之后才可以从入口层直接到火山顶」）
                    //   反编译定论（decomp/full/StardewValley.Locations/Caldera.cs:106 + DwarfGate.cs:121）：
                    //     ① 首次到过 Caldera（`visited`）⇒ 次日 `DayUpdate` 自动补发 `volcanoShortcutUnlocked`
                    //     ② 或者在**入口层 VolcanoDungeon0 的矮人门**踩机关（开关 (40,51)、门 (40,48)）⇒ 当场发
                    //   两条路写的是**同一个 flag**。持有它 ⇒ `VolcanoDungeon.GenerateContents` 里
                    //   `dwarfGates` 全部 `opened=true` 且开关全置真（VolcanoDungeon.cs:817-829）。
                    //   ⚠️ 这个 flag 是唯一的可读判据 —— 门/机关本身是运行时 `DwarfGate` 对象，
                    //      改的是**动态地图层**，`/dump_tile` 读那三格全是空（terrain null、可走）。
                    ["volcanoShortcut"] = new { unlocked = Has("volcanoShortcutUnlocked"),
                        how = "首次到火山顶(Caldera)后次日自动；或在入口层(VolcanoDungeon0)踩矮人门机关(40,51)当场开。开了才能从入口层直通山顶" },
                    ["reachedCaldera"] = new { unlocked = Has("reachedCaldera"), how = "首次抵达火山顶 Caldera（火山第10层）" },
                    ["volcanoShortcutOut"] = new { unlocked = Has("Island_VolcanoShortcutOut"),
                        how = "姜岛鹦鹉升级(第5层)：火山内开捷径直接出到岛北(56,17)" },
                    ["parrotUpgradesRaw"] = parrotUpgradesRaw.ToArray(),
                    ["parrotDiag"] = parrotDiag,
                    ["parrotMembers"] = parrotMembers.ToArray(),
                };

                tcs.SetResult(new { ok = true, unlocks });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    /// <summary>
    /// GET /unlock_debug
    /// 校准用：dump 与解锁相关的真实游戏状态（mail flag / 工具等级 / 技能），
    /// 据此精确定位每个 /unlocks 判定该用哪个 flag（2026-08-14 不猜，实测校准）。
    /// </summary>
    private object HandleUnlockDebug()
    {
        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var tcs = new TaskCompletionSource<object>();
        EnqueueMainThread(() =>
        {
            try
            {
                var master = Game1.MasterPlayer;
                var relevant = new List<string>();
                if (master?.mailReceived != null)
                {
                    foreach (var m in master.mailReceived)
                    {
                        if (!string.IsNullOrEmpty(m))
                            relevant.Add(m);
                    }
                }
                relevant.Sort();

                var tools = new Dictionary<string, int>();
                foreach (var tname in new[] { "Axe", "Pickaxe", "Hoe", "Watering Can" })
                {
                    if (master?.getToolFromName(tname) is Tool tt)
                        tools[tname] = tt.UpgradeLevel;
                }

                tcs.SetResult(new
                {
                    ok = true,
                    relevantMail = relevant,
                    tools,
                    skills = new
                    {
                        farming = master?.farmingLevel.Value ?? 0,
                        mining = master?.miningLevel.Value ?? 0,
                        foraging = master?.foragingLevel.Value ?? 0,
                        fishing = master?.fishingLevel.Value ?? 0,
                        combat = master?.combatLevel.Value ?? 0,
                    },
                    date = $"{Game1.currentSeason} {Game1.dayOfMonth} 年{Game1.year}",
                });
            }
            catch (Exception ex)
            {
                tcs.SetResult(new { ok = false, error = ex.Message });
            }
        });
        return tcs.Task.GetAwaiter().GetResult();
    }

    // ── Walk-to routing ──

    /// <summary>
    /// POST /walk_to  { "location": "Town", "x": 20, "y": 30 }
    /// Walks to a tile on the specified map.
    /// If the target is on a different map, warps there first, then walks.
    /// Returns immediately; progress via /alerts (walk_completed).
    /// </summary>
    private object HandleWalkTo(HttpListenerContext ctx)
    {
        var p = ReadJson(ctx);
        var location = GetParam<string>(p, "location");
        var x = GetParamOr(p, "x", -1);
        var y = GetParamOr(p, "y", -1);
        // 🪙 2026-08-29 恒拍板：淘金/蟹笼走位传 allowWater=true → 允许落水格(站水上淘)，淘完回原位。
        //    每次 /walk_to 都重设(不传=按普通走位排水格)，避免残留影响下一次。
        _walkAllowWater = GetParamOr(p, "allowWater", false);
        // 🚪 2026-10-06：目标格**是门/传送格**时默认**拒**（`allowWarp` 缺省 false）——见下面入口校验。
        //    跨图导航（走门/踩出口格）由 Python 侧显式传 `allowWarp=true` 放行；
        //    AI 直调的坐标走位**不传** ⇒ 闸门就在这一层。
        bool allowWarp = GetParamOr(p, "allowWarp", false);

        if (!Context.IsWorldReady)
            throw new InvalidOperationException("World not ready");

        var farmer = Game1.player;
        // ⚠️ 2026-08-14：fromLoc 用 NameOrUniqueName（真实名），同地图判断才不会把小屋(显示名 Cabin)误判为跨地图
        // ⚠️ 2026-08-26 恒：但只比 NameOrUniqueName 会把农场建筑室内**反向**判错——
        //    畜棚/鸡舍室内的真实名是带 GUID 的实例名（如 Barnf3ed75f9-a0e1-...），
        //    而 /state 报给外面的 location.name 是 loc.Name＝显示名「Deluxe Barn」。
        //    调用方拿显示名回传 → 永远匹配不上 → **棚内每一次 walk_to 都走跨图分支**：
        //    先 warp 到固定入口落点再走 = 肉眼看到的"穿插 warp + 反复落到同一个位置"，
        //    自然走路在畜棚/鸡舍里成功率恒为 0。
        //    修法：显示名和唯一名**任一匹配**即算同图（Cabin 靠唯一名、畜棚靠显示名，两边都保住）。
        var fromUnique = farmer.currentLocation.NameOrUniqueName ?? "";
        var fromName = farmer.currentLocation.Name ?? "";
        var fromLoc = string.IsNullOrEmpty(fromUnique) ? fromName : fromUnique;
        bool sameMap = string.Equals(fromUnique, location, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(fromName, location, StringComparison.OrdinalIgnoreCase);

        // Resolve target coordinates
        if (x < 0 || y < 0)
        {
            x = farmer.TilePoint.X;
            y = farmer.TilePoint.Y;
        }

        // 🛡️ 2026-08-26 恒：入口校验。以前给个越界/不可达坐标，walk_to 会**直接把人瞬移过去**——
        //    实测 Deluxe Coop 只有 23x10，指 (23,13) 人当场飞到墙外。
        //    现在：越界直接 ok:false 拒绝；地图内但站不住 → 退到最近可走格并在返回里注明 adjusted。
        //    ⚠️ IsTilePassable 要遍历 furniture/objects，必须主线程读（同 /surroundings 主线程化教训），
        //    所以整段校验塞进 EnqueueMainThread 再取回结果。
        //
        // 🚪 2026-10-06 恒真机补的第四种拒绝：**门/传送格**。
        //    真机现场：`map walk x=55 y=12` —— 那格**正好是小屋的门格**，上面三条校验**全都放行**
        //    （在界内、站得住、无需就近改格），于是人被游戏 warp 进屋，而执行器继续在新图上
        //    按旧坐标收尾 ⇒ 落在小屋室内 (55,12) ＝ 房间外的空白画布（屋子只占 x 20~41）。
        //    判据（反编译挑的重载）：`GameLocation.doesTileHaveProperty(int,int,string,string,bool)`
        //    （`GameLocation.cs:13153`，返回 `string?`，null = 没这个属性；
        //     它内部也会问 `Building.doesTileHaveProperty`，`:13157-13168`）
        //    ＋ `Building.humanDoor`（"没有门"＝ `Point(-1,-1)`，游戏自己的判据在 `:16704`）。
        //    🔻 2026-10-06 恒「4 收窄吧」：判据**只认真会换图/真门那一类** `Action` 取值（`Door` ＋ 首 token
        //       `Warp*`），不再"带 Action 就算" —— 否则灶台 `Action: kitchen`（只开做菜菜单）走过去也会被拒。
        //       取值口径与"哪些故意没收"全写在 `IsWarpOrDoorTile` / `IsDoorOrWarpAction` 的注释里。
        //    ⛔ **不是**"一刀切禁掉传送格"：`map ops=go` 本来就靠踩出口格换图，
        //       所以跨图那几处由调用方传 `allowWarp=true` 放行（缺省 false 只挡 AI 直调的坐标走位）。
        {
            var vtcs = new TaskCompletionSource<(string kind, int a, int b)>();
            string vErr = "";
            int vx = x, vy = y;
            string vWhy = "";
            EnqueueMainThread(() =>
            {
                try
                {
                    var tgt = sameMap ? farmer.currentLocation : Game1.getLocationFromName(location);
                    if (tgt?.Map == null) { vtcs.SetResult(("notfound", 0, 0)); return; }
                    int mw = tgt.Map.DisplayWidth / 64, mh = tgt.Map.DisplayHeight / 64;
                    if (vx < 0 || vy < 0 || vx >= mw || vy >= mh) { vtcs.SetResult(("oob", mw, mh)); return; }
                    // 🚪 门/传送格（只查**请求的那一格**，不查"就近改"之后那格 ——
                    //    改到传送格上属于另一条路，由 `AbortWalkIfMapChanged` 兜住）
                    if (!allowWarp && IsWarpOrDoorTile(tgt, vx, vy, out vWhy))
                    {
                        vtcs.SetResult(("warp", 0, 0));
                        return;
                    }
                    var near = FindNearestPassableTile(tgt, new Point(vx, vy));
                    vtcs.SetResult(near == null ? ("blocked", mw, mh) : ("ok", near.Value.X, near.Value.Y));
                }
                catch (Exception ex) { vErr = ex.Message; vtcs.SetResult(("error", 0, 0)); }
            });
            var (kind, a, b) = vtcs.Task.GetAwaiter().GetResult();
            if (kind == "notfound")
                return new { ok = false, error = $"Location '{location}' not found" };
            if (kind == "error")
                return new { ok = false, error = $"walk_to 校验出错: {vErr}" };
            if (kind == "oob")
                return new { ok = false, error = $"目标 ({x},{y}) 越界：{location} 只有 {a}x{b} 格（0..{a - 1}, 0..{b - 1}）" };
            if (kind == "warp")
                return new
                {
                    ok = false,
                    warp_tile = true,
                    error = "那格是门/传送格（踩上去会换图）—— 要进门请用 interact；跨图请用 map ops=go",
                    detail = vWhy,
                };
            if (kind == "blocked")
                return new { ok = false, error = $"目标 ({x},{y}) 及周围 8 圈都站不住（被墙/物体/牲畜堵死）" };
            if (a != x || b != y)
            {
                Monitor.Log($"walk_to 目标 ({x},{y}) 站不住 → 就近改到 ({a},{b})", LogLevel.Trace);
                x = a; y = b;
            }
        }

        // Cancel any ongoing movement
        _pathQueue = null;
        _walkRoute = null;
        // 🚪 新路线开始 ⇒ 原生 warp 的"刚发过"记忆清零（不然同图再走一次会不发）
        _nativeWarpFired = null;

        // Same map → just walk
        if (sameMap)
        {
            _walkRoute = new List<WalkSegment> { new WalkSegment(location, x, y) };
            _walkSegIdx = 0;
            _walkSegmentStarted = false;
            _warpPending = false;
            // 🚪🧭 同图坐标走位 ⇒ **不期待换图**：半路被换图就停手（`AbortWalkIfMapChanged`）。
            //    ⚠️ `allowWarp=true` 只是**放行门/传送格**（矿井入口那类"踩上去就是入口"的 POI），
            //       换图停手**照样生效** —— 人已经被游戏送过去了，这一串同图坐标就该作废。
            _walkMapAtStart = fromLoc;
            _walkExpectWarp = false;
            return new { ok = true, action = "walk_to", destination = new { location, x, y }, segments = 1 };
        }

        // Different map: warp to a reliable entry point, then walk to destination.
        // Entry point = the target map's first incoming warp destination (targetX/Y is valid ground).
        int entryX = x, entryY = y;
        var targetLocation = Game1.getLocationFromName(location);
        if (targetLocation?.warps is { Count: > 0 })
        {
            // Use the FIRST outgoing warp's TARGET coords — these are always on valid ground
            // (source X/Y can be -1 or map edge, but target X/Y is where you actually appear)
            var firstWarp = targetLocation.warps[0];
            // Find a warp going INTO this map by checking all locations' warps
            foreach (var gloc in Game1.locations)
            {
                if (gloc == null || gloc.Name == location) continue;
                foreach (var w in gloc.warps)
                {
                    if (w.TargetName == location)
                    {
                        entryX = w.TargetX; entryY = w.TargetY;
                        goto foundEntry;
                    }
                }
            }
            // Fallback: if no incoming warp found, use center-ish of map
            entryX = targetLocation.Map.DisplayWidth / 64 / 2;
            entryY = targetLocation.Map.DisplayHeight / 64 / 2;
            foundEntry:;
        }
        EnqueueMainThread(() => { Game1.warpFarmer(ResolveWarpTarget(location), entryX, entryY, false); });
        _walkRoute = new List<WalkSegment> { new WalkSegment(location, x, y) };
        _walkSegIdx = 0; _walkSegmentStarted = false; _warpPending = true;
        // 🚪🧭 跨图路线 ⇒ **期待换图**：中途换图是它的正常一步，`AbortWalkIfMapChanged` 直接放行，
        //    由上面"自然换图 → 推进下一段"照旧处理（`map ops=go` 就是靠这个踩出口格换图的）。
        _walkMapAtStart = fromLoc;
        _walkExpectWarp = true;
        EnqueueAlert("walk_started", $"Warp to {location} entry→walk ({x},{y})", "info", "walk");

        return new
        {
            ok = true,
            action = "walk_to",
            destination = new { location, x, y },
            warp = new { from = fromLoc, to = location }
        };
    }

    /// <summary>
    /// 🚪🧭 同图坐标走位**半路被换图 ⇒ 立刻停手**（2026-10-06 恒真机：小屋门格）。
    ///
    /// 元凶（真机 + 反编译双证）：
    ///   `map ops=walk x=55 y=12` 那格**正好是小屋的门格** —— 人踩上去被**游戏自己**warp 进屋，
    ///   而"走到 (55,12)"那串执行器**没停**，继续在**新图的同坐标**上收尾
    ///   ⇒ 落点变成小屋室内 (55,12)，那是**房间外的空白画布**（屋子只占 x 20~41）
    ///   ＝ 恒嘴里那句「怎么又飞墙外」。
    ///
    /// 判据 = **起步时那张图**（`_walkMapAtStart`）+ **现在这张图**（显示名/唯一名任一相等即算同图，
    /// 同 `HandleWalkTo` 里 `sameMap` 那套：小屋靠唯一名、畜棚靠显示名）。
    ///
    /// ⛔ **只对"不指望换图"的路线生效**（`_walkExpectWarp == false`）：
    ///    `map ops=go` 的跨图步骤**故意**要踩传送格（它靠踩上去换图），
    ///    那种由下面"自然换图 → 推进下一段"照旧处理 —— 这里一个字都不动。
    ///    所以**不是**"一刀切禁掉传送格"。
    ///
    /// 回包（`/walk_to` 是发射后不管的，只能走警报这条道）：
    ///   `{ok:false, changed_map:true, from:&lt;旧图&gt;, to:&lt;新图&gt;, error:"走到一半换图了…"}`。
    /// </summary>
    /// <returns>true = 换了图、已经停手（调用方立刻 return，别再走这一步）。</returns>
    private bool AbortWalkIfMapChanged()
    {
        if (_walkExpectWarp) return false;                       // 跨图路线：换图是它的正常一步
        if (string.IsNullOrEmpty(_walkMapAtStart)) return false;  // 没记起步图（不是坐标走位）⇒ 不管
        var cur = Game1.player?.currentLocation;
        if (cur == null) return false;
        var curUnique = cur.NameOrUniqueName ?? "";
        var curName = cur.Name ?? "";
        if (string.Equals(curUnique, _walkMapAtStart, StringComparison.OrdinalIgnoreCase)
            || string.Equals(curName, _walkMapAtStart, StringComparison.OrdinalIgnoreCase))
            return false;                                        // 还在起步那张图 ⇒ 一切照旧

        var from = _walkMapAtStart;
        var to = string.IsNullOrEmpty(curUnique) ? curName : curUnique;

        // 清移动状态（路线 + 队列 + 分段游标，一处不漏）
        _walkRoute = null;
        _walkSegIdx = 0;
        _walkSegmentStarted = false;
        _pathQueue = null;
        _walkMapAtStart = null;

        const string err = "走到一半换图了（踩到传送格）—— 已停手；跨图请用 map ops=go";
        EnqueueAlert("walk_changed_map", $"{err}（{from} → {to}）", "warning", "walk",
            new Dictionary<string, object?>
            {
                ["ok"] = false,
                ["changed_map"] = true,
                ["from"] = from,
                ["to"] = to,
                ["error"] = err,
            });
        return true;
    }

    /// <summary>
    /// 🚪 这格是不是**门/传送格**（踩上去会让游戏换图）？给 `HandleWalkTo` 入口校验用。
    ///
    /// 🔻 2026-10-06 恒拍板「4 收窄吧」：老判据是**"带 Action 就算门"**（三个属性各问一句 `!= null`）⇒
    ///    误伤**有 Action 但不换图**的格，AI 直调 `map ops=walk` 会收到一个**理由不准**的 `warp_tile` 拒绝。
    ///    真机会撞上的反例（取值来自反编译，读数来自真机）：
    ///      · `Buildings 19~23,23` 灶台五格 = `Action: kitchen`（`checkAction` 的
    ///        `case "kitchen": case "Kitchen":` → `ActivateKitchen()`，`GameLocation.cs:8979-8980`
    ///        ＝ **只开做菜菜单、一格都不换图**；"灶台在 Buildings 层、值是小写 kitchen"这份真机读数
    ///        见 CHANGELOG 2026-09-11）
    ///      · `Action: Message` / `MessageOnce` / `Dialogue`（`:9595` / `:9764` / `:9621` ＝ 只弹对话）
    ///      · 浴室更衣格的 `TouchAction: ChangeIntoSwimsuit` / `ChangeOutOfSwimsuit`（`:3988-3994` ＝ 只换衣服）
    ///
    /// 现在只挡**真会换图/真门**的那几类（判据全是游戏自己的数据，取值口径照抄反编译）：
    ///   ① `Warp` 属性（查 `Buildings` 与 `Back` 两层）—— ⚠️ 自查结论：1.6 这份全量反编译里**没有一处读
    ///      "瓦片级" `Warp` 属性**（全仓 grep `"Warp"` 只命中 `Utility.cs:908` 那处**地图级**属性，
    ///      当"进入本图的落点"用；瓦片上挂的换图键在 1.6 是 `TouchAction`，见 `FarmHouse.updateCellarWarps`
    ///      `FarmHouse.cs:1953-1957` 改的就是 `TouchAction: Warp Cellar…`）。恒点名要 ① ⇒ 留着
    ///      （xTile 老地图/旧 mod 有用这个键的先例；它的误伤面比"漏掉一个真传送格"小）。
    ///   ② `TouchAction` 是**踩上去就换图**的两条：`Warp <地点> <x> <y>`（`performTouchAction` `case 4`
    ///      `:3696-3711`）与 `MagicWarp <地点> <x> <y>`（9 参那条 `:3649-3691`）—— 见 `IsDoorOrWarpTouchAction`
    ///   ③ `Action` 是**门/传送那一类**：`Door` ＋ `LockedDoorWarp` ＋ 首 token 以 `Warp` 开头
    ///      （`getWarpFromDoor` `:2210-2246` 的 case 名，⚠️ `LockedDoorWarp` 不以 `Warp` 开头、得单列；
    ///       default 分支 `text.Contains("Warp")` `:2239`；`updateDoors` `:17601` 同一条）
    ///      —— 见 `IsDoorOrWarpAction`
    ///   ④ **保留**「这格是某个 `Building` 的 `humanDoor`」：小屋门就靠这条（真机实据 Farm `(55,12)`）。
    ///      "这栋楼没门"的游戏判据是 `Point(-1,-1)`（`:16704`），门格 = `tileX/tileY + humanDoor`。
    ///
    /// ⛔ **故意没收**（踩上去不换图 ⇒ 不是本闸门的靶子；真在门口被换了图还有 `AbortWalkIfMapChanged` 兜底）：
    ///    `ConditionalDoor`(`:9547`)、`ObeliskWarp`(`:9036`)、`ForestPylon`(`:8935`)、`EnterSewer`(`:10006`)、
    ///    `WizardHatch`(`:9991`)、`Mine`/`NextMineLevel`(`:9807-9808`)、`MineElevator`(`:9797`)、
    ///    `MinecartTransport`(`:9790`)、`Theater_Entrance`(`:10063`) —— 这些都要 **interact/菜单再选** 才换图。
    ///
    /// ⚠️ 它**只回答"这格危不危险"**，不决定放不放行 —— 放行与否看调用方传的 `allowWarp`
    ///    （跨图导航故意要踩出口格）。`why` 只用来在拒绝时告诉调用方**是哪条判据命中的**。
    /// </summary>
    private bool IsWarpOrDoorTile(GameLocation? loc, int x, int y, out string why)
    {
        why = "";
        if (loc?.Map == null) return false;
        if (!loc.isTileOnMap(x, y)) return false;   // 图外不问（越界那条校验在前，这是双保险）

        foreach (var layer in new[] { "Buildings", "Back" })
        {
            // ① `Action`：**只认门/传送那一类取值** —— ⛔ 别退回 `!= null`（灶台 `kitchen` 就是这么被误伤的）
            var act = loc.doesTileHaveProperty(x, y, "Action", layer);
            if (IsDoorOrWarpAction(act))
            {
                why = $"Action({layer}) = {act}";
                return true;
            }
            // ② `TouchAction`：**踩上去就换图**的那两条（`Warp …` / `MagicWarp …`）
            var touch = loc.doesTileHaveProperty(x, y, "TouchAction", layer);
            if (IsDoorOrWarpTouchAction(touch))
            {
                why = $"TouchAction({layer}) = {touch}";
                return true;
            }
            // ③ `Warp` 属性：xTile 老式传送格写法，有它就是传送格
            var warp = loc.doesTileHaveProperty(x, y, "Warp", layer);
            if (warp != null)
            {
                why = $"Warp({layer}) = {warp}";
                return true;
            }
        }

        foreach (var b in loc.buildings)
        {
            if (b == null) continue;
            var hd = b.humanDoor.Value;
            if (hd == new Point(-1, -1)) continue;   // 游戏自己判"没门"的那条（GameLocation.cs:16704）
            if (b.tileX.Value + hd.X == x && b.tileY.Value + hd.Y == y)
            {
                why = $"建筑门格 humanDoor（{b.buildingType.Value} @ {b.tileX.Value},{b.tileY.Value} + {hd.X},{hd.Y}）";
                return true;
            }
        }

        // ⑤ 地图**自己的 warp 表**（`GameLocation.warps`）—— ★ 2026-10-06 恒：
        //    「**那个缺口是，出小屋门的传送**」。
        //    小屋/农舍的**室内是 instanced interior、不在 `Game1.locations` 里** ⇒ `/warps` 那张总图
        //    **看不见它的出口格**（本图当时报 0 个），可 `location.warps` 是有的：**出小屋门那一格就在里面**。
        //    ⛔ 不认它，同图走位就会从门口**穿出去**（真机：屋里一路走到屋外空地 `(55,12)`）。
        foreach (var w in loc.warps)
        {
            if (w.X == x && w.Y == y)
            {
                why = $"地图 warp 表({w.TargetName} {w.TargetX},{w.TargetY})";
                return true;
            }
        }
        return false;
    }

    /// <summary>
    /// 🚪 `Action` 取值算不算**门/传送**那一类？—— 本闸门"收窄"就收在这里。
    /// 口径照抄游戏（`getWarpFromDoor` `GameLocation.cs:2210-2246` ＋ `updateDoors` `:17601`）：
    ///   · `Door` —— `performAction` 的 `case "Door"`（`:9566-9590`）→ `openDoor()`（`:8222`，只做开合动画）。
    ///     恒点名的"门那一类"，保留：想进门该 `interact`，不是走过去。
    ///   · `LockedDoorWarp` —— ⚠️ **它不以 `Warp` 开头**，得单列（`getWarpFromDoor` `:2223` / `performAction`
    ///     `:9537-9546` → `lockedDoorWarp(...)` → 开门后 `Game1.warpFarmer`）。真机读到的就是这族门：
    ///     `Town(95,50) = LockedDoorWarp 13 29 JojaMart 900 2300`（Joja 超市）、Leah/Elliott 家门
    ///     （`locations.py:762/772` 记的 `LockedDoorWarp … 1000 1800 Leah/Elliott 500`）。
    ///   · 首 token **以 `Warp` 开头** —— 游戏自己就是这么判的：`getWarpFromDoor` 认的其余 case 名全是 `Warp*`
    ///     （`Warp` / `WarpMensLocker` / `WarpWomensLocker` / `WarpCommunityCenter` /
    ///      `Warp_Sunroom_Door` / `WarpBoatTunnel`），default 分支一句 `text.Contains("Warp")`（`:2239`）
    ///     连带参数的写法 `Warp <x> <y> <地点>`（`performAction` `case "Warp"` `:9475-9490` → `Game1.warpFarmer`）
    ///     和 `WarpGreenhouse`（`:9415`）一起兜住 ⇒ 用 `StartsWith("Warp")` 一个条件覆盖整族。
    ///   · ⛔ **没有** `kitchen`/`Kitchen`（`:8979`）、`Message`（`:9595`）、`Dialogue`（`:9621`）、`Yoba`（`:10033`）
    ///     —— 它们带 Action 但**不换图**；老判据把它们一起拒了，报的还是"踩上去会换图"，理由不准。
    /// </summary>
    private static bool IsDoorOrWarpAction(string? action)
    {
        if (string.IsNullOrEmpty(action)) return false;
        var first = action.Split(' ')[0];   // 首 token ＝ 游戏取的那一段（ArgUtility.Get(array, 0)）
        if (first == "Door" || first == "LockedDoorWarp") return true;   // ⚠️ 后者**不**以 Warp 开头
        return first.StartsWith("Warp", StringComparison.Ordinal);
    }

    /// <summary>
    /// 🚪 `TouchAction` 取值是不是"**踩上去就换图**"？只有这两条（`performTouchAction`，`GameLocation.cs:3606`）：
    ///   · `Warp <地点> <x> <y> [mail]` —— `case 4:` 里的 `if (value == "Warp")`（`:3696-3711`）→ `Game1.warpFarmer`
    ///   · `MagicWarp <地点> <x> <y> [mail]` —— 9 参那条（`:3649-3691`），同样 `Game1.warpFarmer`
    ///     （现网地图未见用它，但它是**真换图**那一类 ⇒ 一并收进；它不可能误伤 `kitchen` 这种值。）
    /// ⛔ 别退回 `!= null`：浴室更衣格的 `ChangeIntoSwimsuit`/`ChangeOutOfSwimsuit`（`:3988-3994`）
    ///    也是 TouchAction，但**只换衣服不换图**（真机坐标见 CHANGELOG 2026-09-10）。
    /// </summary>
    private static bool IsDoorOrWarpTouchAction(string? touchAction)
    {
        if (string.IsNullOrEmpty(touchAction)) return false;
        var first = touchAction.Split(' ')[0];
        return first == "Warp" || first == "MagicWarp";
    }

    /// <summary>
    /// Lazy-build a map graph from all game locations' warp points.
    /// </summary>
    private void EnsureWarpGraph()
    {
        if (_warpGraph != null) return;
        _warpGraph = new Dictionary<string, List<WarpLink>>();

        foreach (var gloc in Game1.locations)
        {
            if (string.IsNullOrEmpty(gloc.Name)) continue;
            if (!_warpGraph.ContainsKey(gloc.Name))
                _warpGraph[gloc.Name] = new List<WarpLink>();

            foreach (var w in gloc.warps)
            {
                if (string.IsNullOrEmpty(w.TargetName)) continue;

                // Deduplicate: same (source → target) may appear on multiple adjacent tiles
                var existing = _warpGraph[gloc.Name].Any(
                    l => l.TargetLocation == w.TargetName && l.SourceX == w.X && l.SourceY == w.Y);
                if (!existing)
                {
                    _warpGraph[gloc.Name].Add(new WarpLink(w.TargetName, w.X, w.Y, w.TargetX, w.TargetY));
                }
            }
        }
    }

    /// <summary>
    /// BFS across maps to find the shortest map-name path.
    /// Returns null if no route exists.
    /// </summary>
    private List<string>? FindMapPath(string fromLocation, string toLocation)
    {
        if (fromLocation == toLocation)
            return new List<string> { fromLocation };

        EnsureWarpGraph();

        // Ensure the starting location is in the graph (handles building interiors)
        var playerLoc = Game1.player?.currentLocation;
        if (playerLoc != null && !_warpGraph!.ContainsKey(fromLocation))
        {
            _warpGraph[fromLocation] = new List<WarpLink>();
            foreach (var w in playerLoc.warps)
            {
                if (!string.IsNullOrEmpty(w.TargetName))
                    _warpGraph[fromLocation].Add(new WarpLink(w.TargetName, w.X, w.Y, w.TargetX, w.TargetY));
            }
        }

        var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { fromLocation };
        var queue = new Queue<(string location, List<string> path)>();
        queue.Enqueue((fromLocation, new List<string> { fromLocation }));

        while (queue.Count > 0)
        {
            var (current, path) = queue.Dequeue();

            if (!_warpGraph!.ContainsKey(current)) continue;

            foreach (var link in _warpGraph[current])
            {
                if (visited.Contains(link.TargetLocation)) continue;

                if (string.Equals(link.TargetLocation, toLocation, StringComparison.OrdinalIgnoreCase))
                {
                    path.Add(toLocation);
                    return path;
                }

                visited.Add(link.TargetLocation);
                var newPath = new List<string>(path) { link.TargetLocation };
                queue.Enqueue((link.TargetLocation, newPath));
            }
        }

        return null; // No path found
    }

    /// <summary>
    /// Build a full walk route from current location/tile to destination.
    /// Each WalkSegment is "(on this map, walk to this tile)".
    /// Intermediate segments target the warp tile; the final segment targets the user's destination.
    /// Returns null if no path exists between locations.
    /// </summary>
    private List<WalkSegment>? BuildWalkRoute(string fromLoc, Point fromTile, string toLoc, int toX, int toY)
    {
        if (string.Equals(fromLoc, toLoc, StringComparison.OrdinalIgnoreCase))
        {
            return new List<WalkSegment> { new WalkSegment(toLoc, toX, toY) };
        }

        var mapPath = FindMapPath(fromLoc, toLoc);
        if (mapPath == null) return null;

        var route = new List<WalkSegment>();

        // Segment 0: find the warp to the next map on the current location
        // Use the live warps list (handles building interiors not yet in the graph)
        WarpLink? firstLink = null;
        var playerLoc = Game1.player?.currentLocation;
        if (playerLoc != null && playerLoc.Name == fromLoc)
        {
            var warp = playerLoc.warps.FirstOrDefault(w =>
                string.Equals(w.TargetName, mapPath[1], StringComparison.OrdinalIgnoreCase));
            if (warp != null)
                firstLink = new WarpLink(warp.TargetName, warp.X, warp.Y, warp.TargetX, warp.TargetY);
        }
        // Fallback to graph
        firstLink ??= _warpGraph?.GetValueOrDefault(fromLoc)?.FirstOrDefault(w =>
            string.Equals(w.TargetLocation, mapPath[1], StringComparison.OrdinalIgnoreCase));
        if (firstLink == null) return null;
        route.Add(new WalkSegment(fromLoc, firstLink.SourceX, firstLink.SourceY));

        // Intermediate maps: walk from entry point to the next map's warp exit
        for (int i = 1; i < mapPath.Count - 1; i++)
        {
            var cur = mapPath[i];
            var next = mapPath[i + 1];
            if (_warpGraph == null || !_warpGraph.TryGetValue(cur, out var curLinks)) return null;

            var link = curLinks.FirstOrDefault(w =>
                string.Equals(w.TargetLocation, next, StringComparison.OrdinalIgnoreCase));
            if (link == null) return null;
            route.Add(new WalkSegment(cur, link.SourceX, link.SourceY));
        }

        // Final segment: walk to user's target tile on the destination map
        route.Add(new WalkSegment(toLoc, toX, toY));

        return route;
    }

    private Vector2 GetFacingTile(Farmer farmer)
    {
        int x = farmer.TilePoint.X;
        int y = farmer.TilePoint.Y;
        return farmer.FacingDirection switch
        {
            0 => new Vector2(x, y - 1),
            1 => new Vector2(x + 1, y),
            2 => new Vector2(x, y + 1),
            3 => new Vector2(x - 1, y),
            _ => new Vector2(x, y)
        };
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  🛡️ 贴身自动防御（字段区那段长注释有来龙去脉；调用点在 OnUpdateTicked 蓄力块之后）
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>🛡️ 贴身自动防御：每 tick 一次。开关只走 HTTP `/guard`。
    ///
    /// 【判据链的顺序有讲究，别随手重排】
    ///   ① 世界门 → ② **先还债**（换回武器） → ③ 开关 → ④ "这角色归不归我管"
    ///   → ⑤ 照抄游戏 `leftClick` 的那串门 → ⑥ 别抢正在播的动画 → ⑦ 找怪 → ⑧ 换武器/转向/挥。
    ///
    /// 【② 为什么要还债、且必须在 ③ 之前】挥完那一刀后手里还攥着剑，要等动画播完才换回
    ///   （原因见 `_guardPendingRestore` 的注释：`showSwordSwipe` 每帧重读 `CurrentTool`）。
    ///   放在开关之前 ⇒ guard 中途被关掉、或换存档，也能把武器还回去，不会留一把剑攥在手里。
    ///
    /// 【⑤ 是照抄游戏自己的】`MeleeWeapon.leftClick`（`MeleeWeapon.cs:487`）：
    ///   `who.health > 0 && Game1.activeClickableMenu == null && Game1.farmEvent == null
    ///    && !Game1.eventUp && !who.swimming.Value && !who.bathingClothes.Value && !who.onBridge.Value`
    ///   少一条就会做出"游戏不让挥、我们却挥了"的动作（比如 2am 昏迷那个 Event 里挥剑）。
    ///
    /// 【⛔ 两道绝不能碰的线】
    ///   ① **别在"不挥"的那一帧写 `FacingDirection`**。工具动画的 frame68 会按
    ///      `GetToolLocation()` 提交落地格（血案见蓄力块那段"没等"的注释），
    ///      顺手转身会把它挪到**错的格**上。所以"只转向不挥"是**错的** ——
    ///      转向必须和挥击绑死在**同一帧**里。这也是 `GuardFacing` 同格时返回 -1 的原因。
    ///   ② **别动 `_walkRoute` / `_pathQueue` / `farmer.Position`**。恒拍板的"只转向+挥"
    ///      就是为了不跟走位抢人；`Character.Halt()` 也不碰 `Position` ⇒ 挥剑不会打断走位。
    ///
    /// 【挥速不用自己限流】门 ⑥ 判的是 `UsingTool`，它由动画收尾帧的 `Farmer.canMoveNow`
    ///   （`Farmer.cs:6759`）置回 false ⇒ 节奏 = **游戏自己的挥速**，不需要手搓冷却。
    ///   ⚠️ **别改成判 `_toolAnimWait`**：那个闩是给**工具**动画用的（存在理由是工具帧 frame68
    ///      的 `Farmer.useTool`），而剑帧表里根本没有 `useTool`；何况它的**清零点在
    ///      `_commandQueue.Count > 0` 那个块里面**，队列为空时走不到 ⇒ 值可能一直留着，
    ///      拿它当门 = guard 可能被一个陈旧值**永久关掉**（本 bug 的形状重现一遍）。
    ///
    /// 【副作用（拟人，接受）】`DoDamage` 末尾会对 AoE 边框格逐个 `performToolAction`
    ///   （`MeleeWeapon.cs:1398`）⇒ 顺手割掉面前那几格的杂草。**真人挥剑也这样**，不额外处理。
    ///
    /// 【武器形态】剑/匕首走平砍（同帧结算）；**锤子冷却好了走重砸**
    ///   （`triggerClubFunction` 是 **6×6 格** AoE，但伤害在 320ms 后的动画收尾帧才落）——
    ///   完整理由与两个坑见 ⑨ 段注释。
    /// </summary>
    private void GuardTick()
    {
        if (!Context.IsWorldReady || Game1.player == null) return;   // ①

        var farmer = Game1.player;

        // ② 先还债：挥完那一刀后，等动画播完再把武器槽换回去（原因见 _guardPendingRestore）。
        if (_guardPendingRestore >= 0 && !farmer.UsingTool)
        {
            // 🔴 2026-10-04 真机（恒「打怪愣住」）：**只还我们自己借的那次**。
            //    老代码无条件写回 `prev` —— 而 `prev` 是"开打前脚本手里那个槽"，通常就是**炸弹**。
            //    脚本在"借出→还回"这一拍里刚 `/select` 好的镐子会被我们抢回去 ⇒ 脚本接着
            //    `/tool {}`（name 默认 current，见 bomb_common `use_tool()`）时手上是炸弹 ⇒
            //    `Farmer.CurrentTool => CurrentItem as Tool`（`Farmer.cs:1745`）= null ⇒
            //    老 `HandleTool` 那条路**不回包** ⇒ 脚本 10s 超时重试、无限循环 ⇒ 人站着挨打。
            //    现在：槽已经被别人改过（脚本自己选的）⇒ **放弃还债**，绝不抢回。
            if (farmer.CurrentToolIndex == _guardPendingRestoreSlot)
            {
                try { farmer.CurrentToolIndex = _guardPendingRestore; } catch { }
            }
            _guardPendingRestore = -1;
            _guardPendingRestoreSlot = -1;
        }

        if (!_guardOn) { _guardBlock = 2; return; }                  // ③

        // ④ ⛔硬门：这个进程的 Game1.player 是恒（房主）⇒ **绝对不替他挥剑**。
        //    （`/guard on` 在房主进程上会直接报错，这里是不依赖调用方的第二道保险。）
        if (farmer.IsMainPlayer) { _guardBlock = 3; return; }

        // 🔬 采样（2026-09-20 诊断）：**放在所有门之前**。原因：要回答的那个问题是
        //    "头骨矿洞里为什么一刀不挥"，而"卡在哪道门"和"这张图上到底有几只怪"
        //    是**两个独立的未知** —— 采样若放在门后面，被门挡住的那一 tick 就采不到数，
        //    等于用"挡住"掩盖了"列表是空的"，两个病看起来一模一样。
        //    代价：每 tick 多一次 `characters` 遍历（这个列表通常个位数，可忽略）。
        var loc = farmer.currentLocation;
        if (loc == null) { _guardBlock = 15; return; }
        int cx = farmer.TilePoint.X, cy = farmer.TilePoint.Y;
        {
            int nChar = 0, nMon = 0, nearest = -1;
            foreach (var c in loc.characters)
            {
                nChar++;
                if (!(c is Monster mm)) continue;
                nMon++;
                int dd = Math.Max(Math.Abs(mm.TilePoint.X - cx), Math.Abs(mm.TilePoint.Y - cy));
                if (nearest < 0 || dd < nearest) nearest = dd;
            }
            _guardCharsTotal = nChar;
            _guardCharsMonsters = nMon;
            _guardNearestMonster = nearest;
        }

        // ⑤ 游戏自己的 leftClick 门（MeleeWeapon.cs:487）——逐条照抄，别凭感觉加减
        if (farmer.health <= 0) { _guardBlock = 4; return; }
        if (Game1.activeClickableMenu != null) { _guardBlock = 5; return; }   // 开背包/菜单时不动手
        if (Game1.farmEvent != null) { _guardBlock = 6; return; }
        if (Game1.eventUp) { _guardBlock = 6; return; }
        if (farmer.swimming.Value || farmer.bathingClothes.Value || farmer.onBridge.Value) { _guardBlock = 7; return; }
        // ⑤补：反编译里没有、但这条路必须有的三条
        if (farmer.isInBed.Value) { _guardBlock = 8; return; }                // 躺床时姿势是躺的，别举剑
        if (farmer.isRidingHorse()) { _guardBlock = 9; return; }              // 骑马：DoDamage 末尾会 forceCanMove 把动画掐了
        // 🔴🔴 2026-10-03 真机逮到（恒「这次怎么好像甚至连怪都不打了」）：这里原来写的是
        //    `farmer.isEating || farmer.itemToEat != null` —— **`itemToEat` 是个永不清零的字段**：
        //    反编译 `Farmer.cs` 全文件，它只在 3 处被赋值（`eatObject` 9123 / `eat` 9165 / 9228），
        //    **没有任何一处置 null**（`doneEating()` 8851 只清 `isEating` 和 `mostRecentlyGrabbedItem`）
        //    ⇒ **这辈子吃过一次东西之后，这个条件恒为真** ⇒ guard 从此一刀不挥。
        //    真机现场：连吃 buff 之后遇怪，`/guard` 的 `block` 一直是 **10**、两趟下矿都是「共挥 0 刀」，
        //    人被阴影萨满/狙击手从 2~6 格外磨到 20 血（恒看着「快被打死了」）。
        //    ⇒ 判据**只留 `isEating`** —— 那才是"正在吃"的瞬时状态，`doneEating` 会把它清零。
        //    📌 教训：拿游戏字段当门之前，先反编译看**它什么时候被清**（只赋值不清零的字段 = 一次性闩）。
        if (farmer.isEating) { _guardBlock = 10; return; }   // 正在吃：挥击会把吃东西拆了

        // ⑥ 别抢正在播的动画（`UsingTool` 是权威信号，见方法头）
        if (_isChargingTool) { _guardBlock = 11; return; }   // 双保险：调用点本来就在蓄力块之后；
                                       //   万一以后有人挪了调用点，这条能挡住"挥剑打断蓄力"
                                       //   （那样会打出 ok:true 却一格没锄的假成功）
        if (farmer.UsingTool) { _guardBlock = 12; return; }

        // ⑧ 选武器槽。**每次挥击都重算**，不缓存 index —— 背包会变（Python 边挖边捡），
        //    缓存的槽位会指到别的物品上（"手里莫名多了个山洞萝卜"式的事故）。
        //    ⚠️ 2026-09-20：整段**挪到找怪之前** —— `GuardTargetable` 现在要看着这把武器
        //       才判得出"沙漠甲虫打不打得到"（`Bug.isArmoredBug` + BugKiller 附魔）。
        //       挥击用的槽位在下面**再算一次**，"每次重算"的语义一个字没变；
        //       这里多算的一次**只用于筛选**，不参与执行。
        int slot = _guardWeaponName.Length > 0
            ? FindMeleeWeaponSlot(farmer, _guardWeaponName)
            : PickBestMeleeSlot(farmer);
        var guardWeapon = slot >= 0 ? farmer.Items[slot] as MeleeWeapon : null;

        // ⑦ 找怪：切比雪夫半径 1 = 玩家所在 3×3。**用 foreach 不用 LINQ**——
        //    这是 60fps 的热路径，`OfType<>().Where(闭包)` 每 tick 都要分配枚举器 + 闭包，
        //    白给 GC 添活。（枚举语义与 /surroundings 一致，只是半径换成 1。）
        Monster? target = null;
        int bestD = int.MaxValue;
        foreach (var m in loc.characters.OfType<Monster>())
        {
            // ⛔ 打得动的才当目标（装石头的螃蟹 / 竹节虫 / 沙漠甲虫 / 无敌帧 / 隐身 —— 见 GuardTargetable）
            if (!GuardTargetable(m, guardWeapon)) continue;
            int dx = Math.Abs(m.TilePoint.X - cx), dy = Math.Abs(m.TilePoint.Y - cy);
            if (dx > 1 || dy > 1) continue;     // 切比雪夫半径 1
            int d = dx + dy;                    // 贴脸(0) > 正前(1) > 对角(2)
            if (d < bestD) { bestD = d; target = m; }
        }
        if (target == null) { _guardBlock = 13; return; }
        _guardBlock = 0;   // 走到这儿就是真要挥了（下面 ⑨ 里若"没武器"再改写成 14）

        if (slot < 0)
        {
            _guardBlock = 14;
            // 没武器 = **明确上报 + 当场自关**，不静默装死（宁报错别兜底）。
            // 固定文案 ⇒ 走 EnqueueAlert 的 `type:message` 4 秒节流键，不会刷屏；
            // 自关 ⇒ 不空转，也不让 AI 一直以为背后有人保它。
            _guardOn = false;
            _guardNoWeapon = true;
            EnqueueAlert("guard",
                "🛡️ guard 自动关闭：背包里找不到近战武器"
                + (_guardWeaponName.Length > 0 ? $"（Python 点名要的「{_guardWeaponName}」不在包里）" : ""),
                "warning", "guard");
            AddRecentEvent("guard", "🛡️ 贴身防御已关闭（没武器）", Game1.ticks);
            Monitor.Log($"[guard] 没武器 → 自关。want='{_guardWeaponName}'", LogLevel.Warn);
            return;
        }

        // ⑨ 挥：**换武器 → 转向 → 挥**，三步的顺序全是硬约束。
        //    ⚠️ 换武器必须在 `BeginUsingTool()` **之前** —— `doSwipe` 第一行就是
        //       `if (f == null || f.CurrentTool != this) return;`（`MeleeWeapon.cs:1129`），
        //       顺序反了 = **隔空挥**：伤害照落、动画不播。
        int prev = farmer.CurrentToolIndex;
        farmer.CurrentToolIndex = slot;
        int face = GuardFacing(cx, cy, target.TilePoint);
        if (face >= 0) farmer.FacingDirection = face;

        // 🔨 锤子（`MeleeWeapon.type.Value == 2`）：**冷却好了就重砸，没好就平砍**。
        //    【为什么锤子值得单独走一条】重砸 `triggerClubFunction`（`MeleeWeapon.cs:909`）的
        //      AoE 是 `Rectangle(Position.X-192, bb.Y-192, **384, 384**)` —— **6×6 格、36 格**！
        //      对比平砍那条（`getAreaOfEffect`，`MeleeWeapon.cs:695`）是「面前 1 格宽 × 1.75 深」
        //      ⇒ 被围殴时重砸一下顶十下平砍。（Python 的 `swing()` 早就有这条：
        //      `weapon_class == "hammer"` → `special=True` → `/tool {special:true}`；
        //      guard 第一版**只做了平砍**，是漏的。）
        //    【冷却谁管】**游戏自己管** —— `animateSpecialMove` 开头就是
        //      `... && specialCooldown() <= 0`（`MeleeWeapon.cs:1001`），冷却中调它 = **静默 no-op**
        //      （跟 `/tool` 那条"说用了其实没动"同族）。所以这里**先自己读一眼**再决定，
        //      别把"没冷却"和"没挥"混成一样。
        //      ⚠️ `specialCooldown()` 是 `protected`，ModEntry 调不到；但它对 type=2 返回的
        //         `clubCooldown` 是 **`public static int`**（`MeleeWeapon.cs:93`，在 `Update`
        //         里按毫秒递减）⇒ 直接读那个字段就够了。
        bool clubSpecial = false;
        if (farmer.Items[slot] is MeleeWeapon mw && mw.type.Value == 2)
        {
            try { clubSpecial = MeleeWeapon.clubCooldown <= 0; } catch { clubSpecial = false; }
        }

        try
        {
            if (clubSpecial)
            {
                // 🔨 重砸。⚠️ 与平砍**不同步**：`doAnimateSpecialMove`（`MeleeWeapon.cs:1063`）
                //    走的是 `animateOnce(176, 40f, 8, triggerClubFunction)`
                //    ⇒ **伤害在 8×40=320ms 后**的动画收尾帧才落，不是当帧。
                //    `beginSpecialMove` 会 `UsingTool=true; CanMove=false` ⇒ 门 ⑥ 天然挡住下一刀，
                //    不会把这段动画掐断（掐断 = `triggerClubFunction` 不触发 = **一下没打中**）。
                //    ⚠️ 程序调用没有农夫 Update 的复位（`triggerClubFunction` 自己不重置），
                //       所以照抄 `/tool special` 那条：**1.2s 后 forceCanMove 强制复位**
                //       （320ms 伤害 + 余量）。不补 = 小人一直举着锤子。
                ((MeleeWeapon)farmer.CurrentTool!).animateSpecialMove(farmer);
                var f2 = farmer;
                System.Threading.Tasks.Task.Run(() =>
                {
                    System.Threading.Thread.Sleep(1200);
                    try { EnqueueMainThread(() => { try { f2.forceCanMove(); } catch { } }); } catch { }
                });
            }
            else
            {
                farmer.BeginUsingTool();   // 同帧 `setFarmerAnimating` → `doSwipe` + `DoDamage`
                farmer.EndUsingTool();     // 与 `/tool`(:3000-3001) 对齐；对 MeleeWeapon 是 no-op
                                           // （`Tool.endUsing` 的效果分支把 MeleeWeapon 排除在外）
            }
        }
        finally
        {
            // ⑩ **欠着**，下一 tick 等动画播完再还（不能当帧还，见 _guardPendingRestore）。
            //    有多个怪时会把 prev 重新记一遍 —— 但那时 CurrentToolIndex 已经是武器槽，
            //    等于"继续欠着换回同一个原位"，语义正确。
            _guardPendingRestore = prev;
            _guardPendingRestoreSlot = slot;   // 🔴 还债时要核对"槽还是不是我们借的那个"，见 ②
        }

        // ⑪ 记账 + 上报。⚠️ 用 AddRecentEvent **不用 EnqueueAlert**：
        //    guard 是"背景在替你做"，不是"需要你处理"——进 /alerts 会把真正该看的告警挤掉。
        //    ⚠️ AddRecentEvent 的去重只比紧邻上一条，环形上限只有 20 条 ⇒ **真正防洪的是
        //    下面这个时间闩**。15s 是拍的（一次交战里怪一直在打，不该每刀一条）；
        //    真机测完按实际交战频率再调。
        _guardSwings++;
        double now = Game1.currentGameTime.TotalGameTime.TotalMilliseconds;
        string tname = $"{target.Name}({target.TilePoint.X},{target.TilePoint.Y})";
        if (now - _guardLastReportMs > 15000)
        {
            AddRecentEvent("guard", $"🛡️ 贴身自动反击 {tname}", Game1.ticks);
            _guardLastReportMs = now;
        }
        Monitor.Log($"[guard] {(clubSpecial ? "🔨重砸" : "挥")} #{_guardSwings} → {tname} hp={target.Health} "
            + $"slot={slot} 武器={farmer.Items[slot]?.Name ?? "?"}", LogLevel.Info);
        _guardLastTarget = tname;
    }

    /// <summary>🎯 guard 选目标时的"**这会儿打得动吗**"判据。
    ///
    /// 【为什么要有它】恒 2026-09-20 真机看出来的："螃蟹类和沙漠甲虫不打（除非能检测到它移动）"。
    ///   我那次真机测试正好撞上：贴着 Rock Crab 连挥 16 刀，它 HP 只从 272 掉到 268 —— **白挥**。
    ///
    /// 【游戏自己的机制】（反编译逐行核过 —— **不用去猜"它动没动"**）
    ///   · `RockCrab.takeDamage`（`RockCrab.cs:143`）：
    ///     `else if (Sprite.currentFrame % 4 == 0 && !shellGone.Value) { num = 0; playSound("crafting"); }`
    ///     ⇒ **还装着石头时伤害恒为 0**（"叮"一声，像敲在石头上）。
    ///   · `RockCrab.update`（`:202`）：`if (!withinPlayerThreshold() && !shellGone.Value) Halt();`
    ///     ，且随后 `else { if (!shellGone.Value) return; ... }` ⇒ **`shellGone=false` 的螃蟹根本不动**。
    ///     ⇒ 恒说的"检测到它移动才打得动"**跟 `shellGone` 是同一件事**，而 `shellGone` 是**精确信号**：
    ///       没有检测延迟、不会误判，而且 Truffle Crab 那种"靠近就自己脱壳"（`:206`）也一并覆盖。
    ///   · 🪵 **Stick Bug（竹节虫）就是 RockCrab 的一个变体**（`makeStickBug()`，`:68`，`Name="Stick Bug"`，
    ///     由 `MineShaft.cs:4175` 生成）—— 同一个 `shellGone` 门。而且它更狠：`hitWithTool`（`:98`）
    ///     对竹节虫**直接 `return false`**（镐子敲不动），炸弹那条破壳分支也带 `!isStickBug` ⇒ **炸弹也不脱壳**。
    ///   · ⚠️ 破壳正路是**镐子敲 5 下**（`performToolAction`，`:102`，`shellHealth` 5→0）——
    ///     那是**人的活儿，不是 guard 的**。guard 只挥武器、只转向不移动，**这里就是"不挥"**；
    ///     要敲壳得 AI 自己 `scene use` 换镐子上，**别自作主张去补镐子**（那会跟"只挥武器"打架）。
    ///
    /// 【顺带挡掉的】`isInvincible()`（通用无敌帧 + Leaper 蜷缩，`Monster.cs:369` / `Leaper.cs:66`）
    ///   和 `IsInvisible`（`NPC.cs:736`）—— 这两种挥了同样一点伤害都没有。
    /// </summary>
    private static bool GuardTargetable(Monster? m, MeleeWeapon? guardWeapon)
    {
        if (m == null || m.Health <= 0) return false;
        if (m.IsInvisible || m.isInvincible()) return false;
        if (m is RockCrab crab && !crab.shellGone.Value) return false;
        // 🐞 沙漠甲虫（`Bug.isArmoredBug`）—— 头骨矿洞的 Bug **全都是**这种：
        //    `Bug.cs` 的构造里 `if (areaType == 121) { isArmoredBug.Value = true; ... Health = 150; }`
        //    （121 = 头骨矿洞），而 `Bug.takeDamage`（`Bug.cs:106-113`）第一句就是
        //      `if (isArmoredBug.Value && (isBomb || !(who.CurrentTool is MeleeWeapon mw)
        //                                  || !mw.hasEnchantmentOfType<BugKillerEnchantment>()))
        //           { playSound("crafting"); return 0; }`
        //    ⇒ **炸弹 / 普通武器 / 镐子 一律 0 伤害**，只有带 `BugKiller` 附魔的近战武器打得动。
        //    恒 2026-09-20 现场一眼看穿："沙漠甲虫应该不打才正常吧！确实不该打，打不死。"
        //    ⇒ 手里这把打不动就别当目标（**跟装壳的岩蟹同一族：打得动才当目标**）。
        //    ⚠️ 判据看着的是 **guard 要用的那把武器**（不是 `CurrentTool`）—— 见 `GuardTick` ⑧。
        if (m is Bug bug && bug.isArmoredBug.Value
            && (guardWeapon == null
                || !guardWeapon.hasEnchantmentOfType<StardewValley.Enchantments.BugKillerEnchantment>()))
            return false;
        // 🧟 **木乃伊的尸体形态**（恒 2026-10-03 深夜：「对木乃伊的尸体形态发生了贴脸的无限追击…能跳过吗？」）
        //    `Mummy.takeDamage`（反编译 `Mummy.decompiled.cs:50`）第一句：
        //      `if (reviveTimer.Value > 0) { if (isBomb) { Health = 0; …; return 999; } return -1; }`
        //    ⇒ 尸体形态下**普通武器恒 -1**（挥多少下都白挥），**只有炸弹能清**；
        //      想一刀消灭得用带 `CrusaderEnchantment` 的武器（那是"打倒那一刀"就生效，不是打尸体）。
        //    ⚠️ 别拿 `Health` 当判据：进尸体形态时 `Health` 被重设成 `MaxHealth`（`:95`）⇒ 认不出来。
        //    ⇒ 和"装壳的岩蟹/沙漠甲虫"同族：**打得动才当目标**。要彻底清掉尸体得 AI 自己丢炸弹
        //      （炸矿脚本本来就在炸，爆炸顺手就把尸体清了）。
        if (m is Mummy mummy && mummy.reviveTimer.Value > 0) return false;
        return true;
    }

    /// <summary>🧭 玩家格 → 目标格的**朝向**（0上 1右 2下 3左）。
    /// ⚠️ 本文件**没有**"格→格朝向"的现成 helper：`GetFacingTile` 是**反方向**（朝向→格），
    ///   `/face` 只收一个 direction 数字。所以补这一个。
    ///
    /// 规则 = **主轴优先**（|dx| 大走左右，否则上下）；**平手（正对角 1,1）取左右** ——
    ///   剑的 AoE 是朝向前方那一条并按动画帧横扫（`getAreaOfEffect`，`MeleeWeapon.cs:695`），
    ///   横扫那一侧更容易蹭到对角。
    ///   ⚠️ 但**别指望一刀必中**：正对角的怪本来就在 AoE 边上，miss 一次是预期内的
    ///   —— 恒已接受（怪会自己走进正面那一格）。
    /// 同格（dx=dy=0，怪踩在玩家身上）返回 **-1** = "连朝向都别写"
    ///   （为什么不能白写朝向，见 `GuardTick` 方法头 ⛔①）。
    /// </summary>
    private static int GuardFacing(int px, int py, Point tile)
    {
        int sdx = tile.X - px, sdy = tile.Y - py;
        if (sdx == 0 && sdy == 0) return -1;
        if (Math.Abs(sdx) >= Math.Abs(sdy)) return sdx > 0 ? 1 : 3;
        return sdy > 0 ? 2 : 0;
    }

    /// <summary>🧰 guard 用：按名字在背包里找**近战武器**槽位；找不到回 -1。
    /// 匹配规则**照抄 `/select` 那套两趟**（精确 Name/DisplayName/QualifiedItemId 优先，
    ///   再 `Contains` 兜底）—— 别另写一套，写第二套就是"两份必然漂移"。
    /// ⚠️ 只认 `MeleeWeapon`：`/select "Iridium Scythe"` 是能选中**工具镰**的，那不是武器
    ///   （Python 的 `detect_weapon` 专门为这个打过补丁，见 bomb_common.py 那段注释）。
    /// </summary>
    private static int FindMeleeWeaponSlot(Farmer farmer, string name)
    {
        if (farmer?.Items == null || string.IsNullOrEmpty(name)) return -1;
        for (int i = 0; i < farmer.Items.Count; i++)
        {
            if (farmer.Items[i] is not MeleeWeapon mw) continue;
            if (mw.Name.Equals(name, StringComparison.OrdinalIgnoreCase)
                || (mw.DisplayName ?? "").Equals(name, StringComparison.OrdinalIgnoreCase)
                || (mw.QualifiedItemId ?? "").Equals(name, StringComparison.OrdinalIgnoreCase))
                return i;
        }
        for (int i = 0; i < farmer.Items.Count; i++)
        {
            if (farmer.Items[i] is MeleeWeapon mw
                && (mw.Name ?? "").Contains(name, StringComparison.OrdinalIgnoreCase))
                return i;
        }
        return -1;
    }

    /// <summary>🧰 guard 用：C# 自己挑一把武器（Python 没传名字时才走这里）。
    /// 优先级**照抄 Python 的 `WeaponMixin.detect_weapon`**，别自创：
    ///   先"非镰的近战武器"，再退到镰 —— 这是 2026-08-10 被"拿大镰刀挥挥挥"打出来的规矩
    ///   （实测 Iridium Scythe 是 `MeleeWeapon(wtype=3)` 且背包排第 3，会抢在银河锤前面）。
    /// 📌 已知不如 Python 的地方：不看伤害、不看 weapon_override。所以**正常路径永远是
    ///   Python 传名字进来**（`MineBot.detect_weapon()` 已经把优先级算完了），
    ///   这里只是"手搓 curl 开 guard"时的兜底。
    /// </summary>
    private static int PickBestMeleeSlot(Farmer farmer)
    {
        if (farmer?.Items == null) return -1;
        for (int i = 0; i < farmer.Items.Count; i++)
            if (farmer.Items[i] is MeleeWeapon mw && !mw.isScythe()) return i;
        for (int i = 0; i < farmer.Items.Count; i++)
            if (farmer.Items[i] is MeleeWeapon) return i;
        return -1;
    }

    // --- Helpers ---

    private void EnqueueMainThread(Action action)
    {
        lock (_queueLock)
        {
            _mainThreadQueue.Enqueue(action);
        }
    }

    /// <summary>
    /// Simple BFS pathfinding on the game map.
    /// </summary>
    /// <param name="blockWarps">🚪 true = **把门/传送格当障碍**（同图走位用）——
    /// 踩上去会换图，不能像普通地板那样穿过去；跨图走位（`map go`）传 false：
    /// 它**故意**要落在出口传送格上让游戏换图（见 `_walkExpectWarp`）。</param>
    private Queue<Point>? FindPath(GameLocation location, Point start, Point end, bool blockWarps = false)
    {
        if (start == end) return new Queue<Point>();

        // 一次 BFS 铺满可达区（父指针表）。命中终点就**早退**（近目标照样便宜）；
        // 没命中说明终点不可站/进不去，顺手拿**同一份**表去够它的邻居 ——
        // 不再像旧代码那样对每个候选邻居各跑一整趟 BFS（那是最坏 5 趟全图搜索）。
        var parents = BfsParents(location, start, end, blockWarps);
        var direct = Rebuild(parents, start, end);
        if (direct != null) return direct;

        // BFS 失败：终点不可走（床/家具/门）或路径被家具挡住（如床边电视卡位）
        // → 走到最近的可走邻居，而不是 BFS 失败让调用方传送闪现
        int[] ndx = { 0, 0, -1, 1 };
        int[] ndy = { -1, 1, 0, 0 };
        Queue<Point>? bestPath = null;
        var bestDist = int.MaxValue;
        for (int i = 0; i < 4; i++)
        {
            var cand = new Point(end.X + ndx[i], end.Y + ndy[i]);
            if (cand == start) return new Queue<Point>();
            if (!IsTilePassable(location, cand)) continue;
            if (blockWarps && IsWarpOrDoorTile(location, cand.X, cand.Y, out _)) continue;
            var d = Math.Abs(start.X - cand.X) + Math.Abs(start.Y - cand.Y);
            if (d >= bestDist) continue;
            var p = Rebuild(parents, start, cand);
            if (p != null) { bestPath = p; bestDist = d; }
        }
        return bestPath;
    }

    /// <summary>
    /// 🧭 从 start 起 BFS 铺开，返回「子 → 父」表（供 Rebuild 回溯路径）。
    /// 探到 stopAt 就**立即早退**；够不到则铺满整个可达区再返回，调用方可以复用同一份表。
    ///
    /// ⚠️ 2026-09-13 恒：这里原先藏着「长距离走位凭空瞬移」的真凶，两个病一起治了 ——
    ///
    ///  ① **上限扣错了对象**：旧代码 `maxSteps = 5000`，而 `maxSteps--` 是**每出队一个节点**扣 1，
    ///     即「最多探索 5000 个格子」、**不是**「路径最多 5000 步」。BFS 是广度优先 ——
    ///     要到曼哈顿距离 D 的目标，得先把**半径 D 以内所有格**淌一遍（约 2D² 格）。
    ///     ⇒ 能走的距离被死死卡在 √(5000/2) ≈ 50 格。真机对照（起点 Town(1,54)）：
    ///          · 旧站格 Town(15,40) 距离 28  ⇒ 约 1,570 格  ✅ 探得完 → 正常走路（所以"一直没出错"）
    ///          · 正解   Town(81,1)  距离 133 ⇒ 约 35,000 格 ❌ 爆上限 → 掉进 FindPath 的兜底**瞬移**
    ///     —— 这就是「**把错坐标改对之后反而开始凭空瞬移**」的完整真相。
    ///
    ///  ② **每个节点整条路径拷贝**：旧代码 `new List&lt;Point&gt;(path)` 每扩一格就复制整条路径，
    ///     探索 N 格 = O(N²) 次拷贝 —— 所以**不能只把 5000 调大**，那样一爆就是几十万次拷贝。
    ///
    /// 修法：**父指针回溯**（只记 parent，命中后再倒推）+ 上限放到地图格数 W*H
    /// （130×110 的镇子才 1.4 万格，时间和内存都是 O(W*H)）。
    /// </summary>
    private Dictionary<Point, Point> BfsParents(GameLocation location, Point start, Point stopAt,
                                               bool blockWarps = false)
    {
        int maxSteps = Math.Max(location.Map.DisplayWidth / 64 * (location.Map.DisplayHeight / 64), 1024);

        var parents = new Dictionary<Point, Point>();   // 子 → 父；start 不入表（回溯到它就停）
        var visited = new HashSet<Point> { start };
        var queue = new Queue<Point>();
        queue.Enqueue(start);

        int[] dx = { 0, 0, -1, 1 };
        int[] dy = { -1, 1, 0, 0 };

        while (queue.Count > 0 && maxSteps-- > 0)
        {
            var pos = queue.Dequeue();

            for (int i = 0; i < 4; i++)
            {
                var next = new Point(pos.X + dx[i], pos.Y + dy[i]);

                if (visited.Contains(next)) continue;
                // 🚪 门格（关着也 passable=false）当作「可跨越」放行——走位循环会在踩上它时先推门。
                if (!IsTilePassable(location, next) && !IsInteriorDoor(location, next)) continue;
                // 🚪 同图走位（blockWarps=true）：**门/传送格一律当障碍**（恒 2026-10-06
                //    「途径踩上了那些 warp 边界就切换地图」）—— 踩上去会换图，
                //    当普通地板穿过去 = 被游戏拽走（真机：小屋内部走位一路穿到屋外）。
                //    要么绕开，要么由调用方**如实停手**；跨图走位传 false，照旧"终点落在出口格换图"。
                if (blockWarps && IsWarpOrDoorTile(location, next.X, next.Y, out _)) continue;

                visited.Add(next);
                parents[next] = pos;

                if (next == stopAt) return parents;   // 近目标：早退，别白铺满整张图
                queue.Enqueue(next);
            }
        }

        return parents;   // 铺满（或撞上限）——够不够得到终点由调用方 Rebuild 判定
    }

    /// <summary>
    /// 🚶 用父指针表回溯出 start→end 的路径（**不含 start、含 end**，与旧 BfsTo 的返回形状一致）。
    /// 够不到（表里没这个格）返回 null。
    /// </summary>
    private static Queue<Point>? Rebuild(Dictionary<Point, Point> parents, Point start, Point end)
    {
        if (end == start) return new Queue<Point>();
        if (!parents.ContainsKey(end)) return null;

        var chain = new List<Point>();
        var cur = end;
        while (cur != start && parents.TryGetValue(cur, out var p))
        {
            chain.Add(cur);
            cur = p;
        }
        chain.Reverse();   // 回溯是 end→start，反转成 start→end 的行走顺序
        return new Queue<Point>(chain);
    }

    // 🐄 2026-08-26 恒：牲畜占格缓存。BFS 一趟要问几千格，逐格遍历 animals 太亏，
    //    按 (地点 + tick) 缓存占格集合，30 tick(约半秒)内复用——动物走动也跟得上。
    private HashSet<Point>? _animalTiles;
    private string? _animalTilesLoc;
    private int _animalTilesTick = int.MinValue;
    // 👹 怪物占的格（2026-10-03 恒「怪给一个不可穿行」）——与牲畜同款缓存（BFS 每格都要问，不能每次扫 characters）
    private HashSet<Point>? _monsterTiles;
    private string? _monsterTilesLoc;
    private int _monsterTilesTick = int.MinValue;

    /// <summary>
    /// 🛡️ 2026-08-26 恒：找离 target 最近的可走格（含 target 自己）。walk_to 入口校验用。
    /// 逐圈外扩，同圈内取曼哈顿最近；maxRadius 圈内找不到返回 null。
    /// </summary>
    private Point? FindNearestPassableTile(GameLocation loc, Point target, int maxRadius = 8)
    {
        if (IsTilePassable(loc, target)) return target;
        for (int r = 1; r <= maxRadius; r++)
        {
            Point? best = null;
            int bestD = int.MaxValue;
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (Math.Abs(dx) != r && Math.Abs(dy) != r) continue;   // 只扫当前这一圈
                    var c = new Point(target.X + dx, target.Y + dy);
                    if (!IsTilePassable(loc, c)) continue;
                    int d = Math.Abs(dx) + Math.Abs(dy);
                    if (d < bestD) { bestD = d; best = c; }
                }
            }
            if (best != null) return best;
        }
        return null;
    }

    /// <summary>当前地点牲畜占的格子（Farm 上放牧的 / 鸡舍畜棚内的）。非动物地点返回空集。</summary>
    private HashSet<Point> GetAnimalTiles(GameLocation location)
    {
        var locName = location.NameOrUniqueName ?? location.Name;
        if (_animalTiles != null && _animalTilesLoc == locName && Game1.ticks - _animalTilesTick < 30)
            return _animalTiles;

        var set = new HashSet<Point>();
        try
        {
            IEnumerable<FarmAnimal>? list = location is Farm farm ? farm.animals.Values
                : location is AnimalHouse ah ? ah.animals.Values
                : null;
            if (list != null)
                foreach (var a in list)
                    if (a != null) set.Add(a.TilePoint);
        }
        catch { }

        _animalTiles = set;
        _animalTilesLoc = locName;
        _animalTilesTick = Game1.ticks;
        return set;
    }

    /// <summary>当前地点**怪物**占的格子（2026-10-03 恒：「怪给一个不可穿行」）。非怪物地点返回空集。
    ///
    /// ⚠️ 判据与 `/passable` 的 `blocker` **同一套**：`Character.GetBoundingBox()` 与该格 64×64 相交
    ///    （游戏自己的 `GameLocation.isCharacterAtTile` 就是这么写的，反编译 `:5318`）——
    ///    用**包围盒**而不是 `TilePoint`：大怪占多格，只对 `TilePoint` 会漏掉它压着的那几格。
    /// ⚠️ 与 `GetAnimalTiles` 一样带 30 tick 缓存：BFS 是**逐格**问它的（一张图几千格），
    ///    每次现扫 `loc.characters` 会把走位拖慢；30 tick 的滞后对"绕过怪"完全够用。
    /// </summary>
    private HashSet<Point> GetMonsterTiles(GameLocation location)
    {
        var locName = location.NameOrUniqueName ?? location.Name;
        if (_monsterTiles != null && _monsterTilesLoc == locName && Game1.ticks - _monsterTilesTick < 30)
            return _monsterTiles;

        var set = new HashSet<Point>();
        try
        {
            foreach (var c in location.characters)
            {
                if (c is not StardewValley.Monsters.Monster) continue;
                var box = c.GetBoundingBox();
                int x0 = box.X / 64, y0 = box.Y / 64;
                int x1 = (box.X + box.Width - 1) / 64, y1 = (box.Y + box.Height - 1) / 64;
                for (int gx = x0; gx <= x1; gx++)
                    for (int gy = y0; gy <= y1; gy++)
                        set.Add(new Point(gx, gy));
            }
        }
        catch { }

        _monsterTiles = set;
        _monsterTilesLoc = locName;
        _monsterTilesTick = Game1.ticks;
        return set;
    }

    /// <summary>
    /// 连通域洪水填充：从 start 沿**地图图层 isTilePassable**（不含 object/家具/水）能走到 target 吗。
    /// ⚠️ 刻意只用地图图层——岩石是 object 层且可炸穿，不该当连通分界；只有墙/地形（地图层不可走）才切胞腔。
    /// 返回 false 表示 target 与 start 被一圈墙格隔开（不同墙圈胞腔，position 进去会卡死）。越界格直接视为不可达。
    /// </summary>
    private bool ConnectedMapLayer(GameLocation location, Point start, Point target)
    {
        if (!location.isTilePassable(new Vector2(start.X, start.Y))) return start == target;
        if (!location.isTilePassable(new Vector2(target.X, target.Y))) return false;

        int mapWidth = location.Map.DisplayWidth / 64;
        int mapHeight = location.Map.DisplayHeight / 64;
        var seen = new HashSet<string>();
        var q = new Queue<Point>();
        q.Enqueue(start);
        seen.Add(cellKey(start));
        int[] dx = { 1, -1, 0, 0 };
        int[] dy = { 0, 0, 1, -1 };
        while (q.Count > 0)
        {
            var cur = q.Dequeue();
            if (cur.X == target.X && cur.Y == target.Y) return true;
            for (int i = 0; i < 4; i++)
            {
                int nx = cur.X + dx[i], ny = cur.Y + dy[i];
                if (nx < 0 || ny < 0 || nx >= mapWidth || ny >= mapHeight) continue;
                var np = new Point(nx, ny);
                var key = cellKey(np);
                if (seen.Contains(key)) continue;
                if (!location.isTilePassable(new Vector2(nx, ny))) continue;
                seen.Add(key);
                q.Enqueue(np);
            }
        }
        return false;
    }

    private static string cellKey(Point p) => p.X + "," + p.Y;

    /// <summary>
    /// 🚪 1.6 室内隔间门识别：该格是不是「同图隔间门」（非 warp，interact 开门、门格 passable false→true）。
    /// 数据源 = GameLocation.interiorDoors（InteriorDoorDictionary，进图时由地图属性 "Doors" 解析填好）。
    /// </summary>
    private static bool IsInteriorDoor(GameLocation loc, Point p)
    {
        try { return loc.interiorDoors != null && loc.interiorDoors.ContainsKey(p); }
        catch { return false; }
    }

    /// <summary>门当前开没开（interiorDoors 直接给出 bool 开态）。</summary>
    private static bool IsInteriorDoorOpen(GameLocation loc, Point p)
    {
        try { return loc.interiorDoors != null && loc.interiorDoors.TryGetValue(p, out bool open) && open; }
        catch { return false; }
    }

    /// <summary>
    /// 🚪 门感知走位·跨帧复查（2026-09-10 真机抓出的坑）。
    /// checkAction 推门后**不能同帧判结果**：门禁弹的 DialogueBox 走延迟队列，
    /// 要下一帧才进 Game1.activeClickableMenu，同帧 `is DialogueBox` 恒 false
    /// → 门禁被整个漏掉：弹窗挂在屏幕上、AI 卡死在门前、既不报错也不停走（浴场男更衣室门实测）。
    /// 所以推门只记挂起，结果在这里每帧复查；本方法挂在 OnUpdateTicked 顶部、
    /// **菜单守卫之外**——被弹窗挡着时走位块可能不执行，只有这里还能跑。
    /// </summary>
    private void CheckPendingDoorPush()
    {
        if (!_doorPushPending.HasValue || !Context.IsWorldReady) return;
        var farmer = Game1.player;
        var loc = farmer?.currentLocation;
        if (loc == null) { _doorPushPending = null; return; }
        if (loc.NameOrUniqueName != _doorPushLoc) { _doorPushPending = null; return; }   // 已换图 → 挂起作废
        var tile = _doorPushPending.Value;

        if (IsInteriorDoorOpen(loc, tile)) { _doorPushPending = null; return; }          // 门开了 → 清挂起，走位继续

        _doorPushTicks++;
        if (Game1.activeClickableMenu is StardewValley.Menus.DialogueBox lockedBox)
        {
            // 门禁拦下（好感不够 / 性别不符 / 未到营业时间）→ 关弹窗、停走、报，别硬闯穿墙
            var reason = "";
            try { reason = lockedBox.getCurrentString() ?? ""; } catch { }
            try { lockedBox.exitThisMenu(); } catch { }
            Game1.activeClickableMenu = null;
            Game1.dialogueUp = false;
            StopWalkForDoor(tile, loc.NameOrUniqueName, reason);
            return;
        }
        if (_doorPushTicks > 90)
        {
            // 推了 1.5s，门没开也没弹窗 → 推不动（这扇门不靠 checkAction 开），别在门前耗死
            StopWalkForDoor(tile, loc.NameOrUniqueName, null);
        }
    }

    /// <summary>推门被拦/推不开 → 清走位 + 报警。reason 非空=门禁原话，空=无提示的推不开。</summary>
    private void StopWalkForDoor(Point tile, string locName, string? reason)
    {
        _doorPushPending = null;
        _pathQueue = null;
        _walkRoute = null;
        _walkSegIdx = 0;
        _walkSegmentStarted = false;
        var why = string.IsNullOrEmpty(reason)
            ? "推不开（无门禁提示）"
            : $"锁着「{reason}」";
        EnqueueAlert("walk_door_locked",
            $"🚪 门{why}（{locName} ({tile.X},{tile.Y})）→ 停在门前，没硬闯", "warning", "walk");
    }

    /// <summary>
    /// 🚧 运行时阻挡物 —— **游戏没把它们画进瓦片层**，我们的尺子必须自己去问游戏。
    ///
    /// 2026-09-23 恒真机：「AI 直接穿过了山体塌方（锁矿井路）的大石头」。
    /// 根因（三步钉死）：`StardewValley.Locations/Mountain.cs:352` 的塌方**只写在**
    /// `isCollidingPosition`（`if (landslide.Value &amp;&amp; position.Intersects(landSlideRect)) return true;`）
    /// 和 `isTilePlaceable` 里，**`isTilePassable` / 瓦片属性完全没有它**；
    /// 而走位是**直接改 `farmer.Position`**（同下面 building/resourceClump 两段的说明）
    /// ⇒ 尺子说能走，角色就真的穿过去了，游戏自己的碰撞根本没机会介入。
    /// 实测：`/passable (50,6) Mountain` 回 `true`，拿 `/passable_rect` 跑连通域，
    /// 塌方当墙时「矿井口/探险家公会」整片与农场侧**断开**（1226 vs 1610 格）。
    ///
    /// 条目 = (地图名, "是否生效"的私有 NetBool 字段, "阻挡矩形"的私有字段) ——
    /// **反射读游戏自己的字段，不抄坐标**（抄了就会跟游戏漂）。
    /// ⚠️ 只覆盖"我们真会踩到"的两处；将来再撞到同类，往表里加一行即可。
    /// ⚠️ 别拿 `loc.isCollidingPosition(...)` 当可走性谓词 —— 基类那个重载
    ///    （GameLocation.cs:2493）会 updateMap 并连带查角色/物体/怪物，影响面太大。
    /// </summary>
    private static readonly (string Map, string FlagField, string RectField)[] RuntimeBlockers = {
        ("Mountain", "landslide", "landSlideRect"),                // 🏔️ 山体塌方：春5日前堵死矿井口/公会那片
        ("Mountain", "railroadAreaBlocked", "railroadBlockRect"),  // 🛤️ 铁路石堆：夏3日地震后清
    };

    /// <summary>反射读私有实例字段（`ReflectField` 那个只认 Public，这两处都是 private）。</summary>
    private static object? ReflectPrivate(object obj, string field)
    {
        try
        {
            var f = obj.GetType().GetField(field,
                BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Instance);
            return f?.GetValue(obj);
        }
        catch { return null; }
    }

    /// <summary>该格是否落在"运行时阻挡物"里（判据与游戏 `isTilePlaceable` 一致：**格中心像素**在矩形内）。</summary>
    private static bool IsRuntimeBlocked(GameLocation location, Point tile)
    {
        if (location == null) return false;
        foreach (var rb in RuntimeBlockers)
        {
            if (location.Name != rb.Map) continue;
            try
            {
                var flagObj = ReflectPrivate(location, rb.FlagField);
                if (flagObj == null) continue;
                var flagVal = flagObj.GetType().GetProperty("Value")?.GetValue(flagObj);
                if (!(flagVal is bool active) || !active) continue;
                if (ReflectPrivate(location, rb.RectField) is Microsoft.Xna.Framework.Rectangle r
                    && r.Contains(tile.X * 64 + 32, tile.Y * 64 + 32))
                    return true;
            }
            catch { }
        }
        return false;
    }

    // ═══════════════════════════════════════════════════════════════
    //  🧭 「够得着」闸 —— 2026-10-03 恒点头的统一口径（一键全图那族）
    // ═══════════════════════════════════════════════════════════════
    //
    //  起因：`/store_all` `/chest_take_list` `/toggle_doors` 这三条"一键全图"端点
    //        **一个距离判定都没有**（2026-10-03 审计复核：三个 handler 区间内 `TilePoint` 零命中）——
    //        玩家站在农场任何角落，背包里的东西能飞进几十格外的箱子、五个棚门一起翻。
    //        ⚠️ 这**不是"拟人"问题**：Python 侧那三条路**都有走位**（`_walk_to_chest` 等）。
    //        真正的缺口只有两个：① "走到了 A 箱、写入却落到 B 箱"（候选集是整图）；
    //        ② "人没到门口，门先翻了"（`/toggle_doors` 压根不碰玩家对象）。
    //
    //  口径（和 10-01 恒「不兜底了，走到附近做个样子就 ok」同一把尺子）：
    //    · **只对玩家同图、且切比雪夫距离 ≤ `ReachTiles` 的目标生效**；
    //    · 够不着的**不静默丢弃** —— 一律进回包（`tooFar` / `skipped`，带坐标），
    //      上层拿坐标走过去再叫一次（`/toggle_doors` 还支持 `building` 只翻点名的那一栋）。
    //
    //  ⚠️ 别和 `IsReachableByWalking` 混：那个问的是"**结构上连连通**"（给兜底瞬移当闸，要 BFS）；
    //     这里问的是"**伸手够不够得着**"，跟中间有没有墙无关，一个减法就够。
    private const int ReachTiles = 4;

    /// <summary>玩家**够得着**这一格吗：同图（`loc` 给了就必须是当前图）且切比雪夫距离 ≤ `ReachTiles`。</summary>
    private static bool IsWithinReach(Farmer? farmer, GameLocation? loc, Vector2 tile)
    {
        if (farmer == null) return false;
        if (loc != null && !ReferenceEquals(farmer.currentLocation, loc)) return false;
        return Math.Abs(farmer.TilePoint.X - (int)tile.X) <= ReachTiles
            && Math.Abs(farmer.TilePoint.Y - (int)tile.Y) <= ReachTiles;
    }

    /// <summary>动物门所在格 = `building.tileX/tileY + animalDoor`（反射，逐个探测类型）。
    /// 读不到就返回 false —— **不许猜**（同 `/farm_buildings` 的只读口径：缺键＝不知道）。</summary>
    private static bool TryGetAnimalDoorTile(Building? b, out int x, out int y)
    {
        x = -1; y = -1;
        if (b == null) return false;
        try
        {
            var rt = b.GetType();
            var fDoor = rt.GetField("animalDoor",
                BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)
                ?? typeof(Building).GetField("animalDoor",
                    BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
            var dv = fDoor?.GetValue(b);
            if (dv == null) return false;
            var vt = dv.GetType();
            var xv = (object?)vt.GetProperty("X")?.GetValue(dv) ?? vt.GetField("X")?.GetValue(dv);
            var yv = (object?)vt.GetProperty("Y")?.GetValue(dv) ?? vt.GetField("Y")?.GetValue(dv);
            if (xv == null || yv == null) return false;
            x = b.tileX.Value + Convert.ToInt32(xv);
            y = b.tileY.Value + Convert.ToInt32(yv);
            return true;
        }
        catch { return false; }
    }

    /// <summary>
    /// 🌊 兜底瞬移前的**连通闸门**：目标格必须与起点"真的走得通"（判据=完整的 `IsTilePassable`）。
    ///
    /// 为什么非有不可：给 `IsTilePassable` 加上"运行时阻挡物"之后，BFS 会**正确地**返回 null，
    /// 而 `walk` 那条兜底**不看连通性**（只查目标格站不站得住）——那等于把"走过去"换成"传送过去"，
    /// 人照样到了不该到的地方，而且这次连动画都没有。**只堵一半 = 没堵**。
    ///
    /// ⚠️ 判据用**完整的 `IsTilePassable`**，不是 `ConnectedMapLayer` —— 那个**故意**只看地图图层
    ///    （岩石在 object 层、可炸穿，不算分界），用途是炸矿的"墙圈胞腔"，两件事别混。
    /// ⚠️ `ignoreTransient=true` 把**牲畜**排除在外：动物会走，构不成"结构性屏障"，
    ///    否则满屋子动物的畜棚会被判成"和外面不连通"，把原本正常的兜底瞬移也一并毙掉。
    /// </summary>
    private bool IsReachableByWalking(GameLocation loc, Point from, Point to, int cap = 40000,
                                     bool blockWarps = false)
    {
        if (from == to) return true;
        var seen = new HashSet<Point> { from };
        var q = new Queue<Point>();
        q.Enqueue(from);
        int[] dx = { 0, 0, -1, 1 };
        int[] dy = { -1, 1, 0, 0 };
        int n = 0;
        while (q.Count > 0 && n++ < cap)
        {
            var p = q.Dequeue();
            for (int i = 0; i < 4; i++)
            {
                var np = new Point(p.X + dx[i], p.Y + dy[i]);
                if (seen.Contains(np)) continue;
                if (!IsTilePassable(loc, np, ignoreTransient: true)) continue;
                // 🚪 同一把尺子：这条是"兜底瞬移"的连通闸门，问了它就不能让瞬移跨过传送格
                if (blockWarps && IsWarpOrDoorTile(loc, np.X, np.Y, out _)) continue;
                if (np == to) return true;
                seen.Add(np);
                q.Enqueue(np);
            }
        }
        return false;
    }

    /// <summary>
    /// 判定某格能否作为走位落点（BFS / `/passable` / `/surroundings` / `/move` 全走这一处）。
    ///
    /// `allowWater=false`(默认)：水格不可站（普通走位不落水）；
    /// `allowWater=true`：放行水格（淘金/放蟹笼时允许站水上近格——SDV 站浅水合法，配合"淘完回原位"）。
    ///
    /// 「运行时阻挡物」现在有四层，**按恒的裁决各管各的**：
    ///   · 🐄 **牲畜**（`GetAnimalTiles`，08-26）：实心 —— 不挡就会规划出踩牛身上的路、顶住干等到超时；
    ///   · 👹 **怪物**（`GetMonsterTiles`，10-03 恒「怪给一个不可穿行」）：实心；
    ///   · 🧑 **NPC / 🐴 马 / 🐾 宠物**：**故意不算**（恒 2026-10-03 给的优先级「绕过怪 ＞ 走路被挡**穿过 npc** ＞ 马」——
    ///     镇子道路开阔、马又停在马厩里，这两个"穿过去"就够用；⚠️ 以后别顺手把它们也堵上）；
    ///   · `ignoreTransient=true`（连通闸门用）：**牲畜和怪都不算** —— 它们会走，构不成结构性屏障。
    /// </summary>
    private bool IsTilePassable(GameLocation location, Point tile, bool allowWater = false,
                                bool ignoreTransient = false)
    {
        // Check map bounds
        if (tile.X < 0 || tile.Y < 0) return false;
        var mapWidth = location.Map.DisplayWidth / 64;
        var mapHeight = location.Map.DisplayHeight / 64;
        if (tile.X >= mapWidth || tile.Y >= mapHeight) return false;

        // 🚧 运行时阻挡物（山体塌方 / 铁路石堆，2026-09-23）：见 `RuntimeBlockers` 的长注释。
        //    放最前面：只比一次地图名，平时的代价是一个字符串比较。
        if (IsRuntimeBlocked(location, tile)) return false;

        // Use the game's built-in passability check（只查地图图层，不查家具/物体）
        var tileVec = new Vector2(tile.X, tile.Y);
        if (!location.isTilePassable(tileVec)) return false;

        // 🧱 2026-09-19 恒「房子的贴图本是不能走的，建筑有一个固定的占位方形，可导航直接穿过贴图往面内走了」：
        //    **建筑占位**以前一个字都没查。而走位是 `ModEntry.cs:2110/2114` **直接改 `farmer.Position`**
        //    硬推过去（本文件 :2120 的注释自陈 "direct position manipulation bypasses …"）⇒
        //    **尺子说能走，角色就真的能穿过去**，游戏自己的碰撞根本没机会介入。
        //    判据照抄游戏（`GameLocation.cs:7419` 的 `CollisionMask.Buildings` 分支），它有两个口径：
        //      · 移动者**尊重可通行性**  ⇒ `!building.isTilePassable(tile)`
        //      · 其它（忽略可通行性）⇒ `!building.occupiesTile(tile)`（**粗暴整块方框**）
        //    这里取 **`isTilePassable`** —— 它 =「方框 ∩ 建筑自己的逐格属性图」（`Building.cs:2105`），
        //    **永远不会比整块方框更严**（框外恒 true），把细化交给游戏自己的数据。
        //    ⚠️ 特意**不**用 `occupiesTile`：那是整块方框、会把"走到门口那一格"也一起堵死，
        //       而门口那格恰恰是 `BUILDING_DOORS` 的落点。
        //    ⚠️ 只管**占位方形**：精灵画到方框外的格（屋顶/墙面外伸）游戏自己也允许站，不在此列。
        try
        {
            foreach (var b in location.buildings)
            {
                if (b != null && !b.isMoving && !b.isTilePassable(tileVec))
                    return false;
            }
        }
        catch { }

        // 🪨 2026-09-20 恒「还有你说的可通行性」：**resourceClumps（2×2 大石头/树桩/原木/陨石）
        //    以前一个字都没查**。反编译实锤：`GameLocation.isTilePassable`（GameLocation.cs:2898）
        //    **只查两样** —— Back 层有没有 `Passable` 属性、Buildings 层有没有实心块
        //    ⇒ 上面那道关卡对资源堆**恒放行**（跟 09-12 查出来的"水格从来没被拦过"是同一个病）。
        //    而走位是**直接改 `farmer.Position`**（见上面建筑那段的 :20581）⇒
        //    **尺子说能走，角色就真穿过去了**，游戏自己的碰撞根本没机会介入。
        //    判据照抄游戏自己的碰撞掩码（`GameLocation.cs:2615`）：它按**包围盒相交**判 ——
        //    `resourceClump.getBoundingBox()`（`ResourceClump.cs:445`）=
        //    `Rectangle(瓷砖X*64, 瓷砖Y*64, w*64, h*64)` ⇒ 对"一个查询格"来说，
        //    逐格等价物就是 `occupiesTile(x,y)`（`ResourceClump.cs:448`，同一段算术）。
        //    ⚠️ **不自己写 `tile.X + width`**：`width`/`height` 都是 NetInt，
        //       写死 2×2 会在将来出现非 2×2 的资源堆时**静默算错**（判据别放消费侧猜）。
        //    ⚠️ 管的是**可通行性**，不是"能不能敲"——敲的工具等级门槛在 `clear_area`/`ValidateToolUse`。
        try
        {
            foreach (var rc in location.resourceClumps)
            {
                if (rc != null && rc.occupiesTile(tile.X, tile.Y)) return false;
            }
        }
        catch { }

        // 💧 2026-08-29 恒拍板：默认(allowWater=false)水格不可站——SDV 地图层把水边/浅水标成 passable=true，
        //    但玩家站上去半身浸水、不拟人。普通走位保持排除水格；淘金/蟹笼把 allowWater=true(或走位时 _walkAllowWater)
        //    放行 → 选址能贴近闪光点(藏水中岸偏远)"站水上淘"，淘完回原位(见 _pan_run/_crab_place)。
        //    ⚠️ /walk_to 内部走 FindPath/BfsTo/落点验证，全都调本函数——靠 _walkAllowWater(HandleWalkTo 读请求设置)
        //    一次放行整条走位链，不用改 FindPath 签名。
        // 🔴 2026-09-12：上面那条"水格排除"**从来没生效过** —— 反编译实锤：
        //    `GameLocation.isTilePassable(Vector2)`（GameLocation.cs:2898）**只查两样** ——
        //    Back 层有没有 `Passable` 属性、Buildings 层有没有实心块 —— **一个字都没提水**。
        //    所以**开阔海面也返回 true** ⇒ `!isTilePassable` 恒 false ⇒ 整个条件永远不成立 ⇒ 水格一路放行。
        //    真机后果：AI 走上海滩开阔水面（恒 2026-09-12 截图：泡在海里、栈道在头顶）。
        //    ⚠️ **不止那一格** —— 海/河/湖的开阔水面全都能走。2026-08-30 那条
        //    "SDV 判可走的水格 = 桥/浅滩"的假设是**错的**（SDV 的通行判定里根本没有水这回事）。
        // ✅ 正确判据（**不依赖魔数**）：**开阔水 = 水格 且 Buildings 层是空的**（上面没铺任何东西）。
        //    实测（2026-09-12 真机扫图）：
        //      · 码头面 (52,25)：水格 + Buildings 层有瓦片（`Passable:T` 的桥面）⇒ **可站** ✅
        //      · 开阔海 (35,38)：水格 + Buildings 层**空** ⇒ **不可站** ❌（恒就是在这泡的水）
        //    为什么不用 SDV 自带的 `isOpenWater()`（GameLocation.cs:13229）：它靠**硬编码瓦片编号**
        //    (628/629/734/759) 认码头，而我没有端点能读到瓦片编号、**无法验证海滩码头是否真用这几个号**；
        //    赌错了就会把码头一并堵死（比原 bug 更糟）。这里用的判据当场实测过，且不依赖任何编号。
        //    ⚠️ 安全性：上面那道 `isTilePassable` 已经先挡掉"Buildings 层有实心块"的格子，
        //       所以走到这里的"水格 + 有 Buildings 瓦片"必然是**可走的桥/码头面** —— 不误伤过河的路
        //       （2026-08-30 想解决的问题依然被妥善处理，只是这次判据是对的）。
        var bLayer = location.Map?.GetLayer("Buildings");
        bool hasDeck = bLayer != null && tile.X < bLayer.LayerWidth && tile.Y < bLayer.LayerHeight
                       && bLayer.Tiles[tile.X, tile.Y] != null;
        if (!allowWater && !_walkAllowWater && location.isWaterTile(tile.X, tile.Y) && !hasDeck)
            return false;

        // 🐄 2026-08-26 恒：牲畜是实心的，BFS 以前不认它 → 规划出踩到牛身上的路，
        //    人顶在动物上不动、walk_to 干等 20 秒超时，最后退化成满屋 position 乱传
        //    （鸡舍只有 16 台机器照样卡死，证明根因是动物不是杂物）。
        //    加上这条后：目标格是动物 → BFS 走不通 → FindPath 的"退到最近可走邻居"
        //    兜底才真正生效，正好落在卡迪纳尔相邻格，interact 一次就摸到。
        //    ⚠️ `ignoreTransient`（2026-09-23）：连通闸门 `IsReachableByWalking` 用得到 ——
        //       动物会走，不是结构性屏障；把它们算进去的话，满屋牲畜的畜棚会被判成"和外面不连通"。
        if (!ignoreTransient && GetAnimalTiles(location).Contains(tile)) return false;

        // 👹 2026-10-03 恒：「**怪给一个不可穿行吧**，碰到怪或者站在怪上的情况还是比较频繁的」。
        //    ⚠️ 在这之前 `IsTilePassable` **一个字都没查 `loc.characters`** ⇒ 怪/NPC/马/宠物**全都不挡路**，
        //       AI 是**直接从怪身上走过去**的（走位是直接改 `farmer.Position`，游戏碰撞没机会介入）。
        //    只把**怪**算进来（NPC/马照旧穿过，理由见本函数 doc）；`ignoreTransient` 时也不算（会走）。
        //    ⚠️ 反过来说：怪踩到玩家身上时**起点格也会变成"不可走"** —— 这不影响走位，
        //       `BfsParents()` 是把起点**无条件**入队的（回溯到它就停），人照样走得出来。
        if (!ignoreTransient && GetMonsterTiles(location).Contains(tile)) return false;

        // 额外：家具/摆放物碰撞（室内床/桌子/箱子等 isTilePassable 不查，会穿墙）
        // 🛏️ 2026-09-27(164)：**判据照游戏改** —— 恒一句破案：「是我干的。我挪了床和电视。
        //    **真人可以从床经过，ai可不行。**」⇒ AI 在自家屋里被自己的家具关成死区
        //    （门口 (3,11) 那一小块走不进房间，只能靠 `/position` 瞬移）—— 直接撞"是不是拟人"那条验收。
        //
        // 游戏自己怎么算（反编译 `GameLocation.isCollidingPosition` :2626）：
        //     foreach (Furniture item in furniture)
        //         if (item.furniture_type.Value != 12
        //             && item.IntersectsForCollision(position)
        //             && (!rectangle.HasValue || !item.IntersectsForCollision(rectangle.Value)))
        //             return true;                      // = 撞了
        // ⇒ 我们旧写法与游戏有**三处**不同，而且**每一处都更严**：
        //     ① 旧：`!f.isPassable()`（`Furniture.isPassable()` 只对 type 12 放行，这点两边一致）
        //     ② 旧：按 `getTilesWide/High` 的**整格 footprint** —— 游戏用的是**像素级碰撞盒**
        //        `IntersectsForCollision(rect)`。家具贴图常常填不满它的格子 ⇒ 我们**多挡了一整圈格**。
        //     ③ 游戏还有一道"**已经叠在里面就不算撞**"（`!item.IntersectsForCollision(rectangle.Value)`）
        //        —— 让人能**从家具里走出来**、不会被卡死。⚠️ 这道是**像素级**的逃生口，
        //        本函数是**逐格**查询（BFS/`/passable`/`/surroundings` 共用），拿不到"人现在站哪"，
        //        所以**故意不移植** —— 移植不了就别假装有。（少了它只会偏严，不会偏松。）
        //     ④ 游戏整段外面还有 `if (!flag ...)`（`flag` = `Game1.eventUp` 且事件不忽略碰撞）；
        //        节日事件里家具不挡人。本函数是纯几何查询，**保持与事件无关**，同样不移植。
        //    📌 通式：**"我们比游戏严"只会以"AI 干不了人能干的事"的形式出现** —— 而它的表现
        //       不是报错，是**静默地绕路/瞬移/干等**（这次就伪装成了"走不到"）。
        try
        {
            foreach (var f in location.furniture)
            {
                if (f == null) continue;
                if (f.furniture_type.Value == 12) continue;   // 床等：游戏两处都放行（见上 ①）
                // ⚠️ 必须写全名：本文件同时 using 了 `xTile.Dimensions`（有同名 Rectangle）⇒ 裸写歧义。
                if (f.IntersectsForCollision(new Microsoft.Xna.Framework.Rectangle(tile.X * 64, tile.Y * 64, 64, 64)))
                    return false;
            }
            if (location.objects != null && location.objects.TryGetValue(tileVec, out var obj) && obj != null)
            {
                if (!obj.isPassable()) return false;
            }
        }
        catch { }
        return true;
    }

    /// <summary>
    /// Parse a hex color string ("RRGGBB" or "AARRGGBB", with or without #) to Color.
    /// Returns null on failure.
    /// </summary>
    private static Color? ParseColor(string? hex)
    {
        if (string.IsNullOrWhiteSpace(hex)) return null;
        hex = hex.TrimStart('#');
        if (hex.Length != 6 && hex.Length != 8) return null;

        try
        {
            uint val = Convert.ToUInt32(hex, 16);
            if (hex.Length == 6)
            {
                // RRGGBB → opaque
                byte r = (byte)((val >> 16) & 0xFF);
                byte g = (byte)((val >> 8) & 0xFF);
                byte b = (byte)(val & 0xFF);
                return new Color(r, g, b);
            }
            else
            {
                // AARRGGBB
                byte a = (byte)((val >> 24) & 0xFF);
                byte r = (byte)((val >> 16) & 0xFF);
                byte g = (byte)((val >> 8) & 0xFF);
                byte b = (byte)(val & 0xFF);
                return new Color(r, g, b, a);
            }
        }
        catch { return null; }
    }
}
